"use server";

import { prisma } from "@/lib/prisma";
import { revalidatePath } from "next/cache";
import { getServerSession } from "next-auth";
import { authOptions } from "@/app/api/auth/[...nextauth]/route";
import {
  CreatePinSchema,
  UpdatePinSchema,
  PinFiltersSchema,
} from "@/components/pins/logic/pin-schemas";
import type { Pin, PinCreateInput, PinUpdateInput } from "@/types/pin.type";

/**
 * Create a new pin in a world
 * @param data - Pin creation data (validated with Zod)
 * @returns Created pin with ID
 * @throws Error if user not found or validation fails
 */
export async function createPin(data: PinCreateInput) {
  // Validate input with Zod
  let validated;
  try {
    validated = CreatePinSchema.parse(data);
  } catch (error) {
    console.error("[createPin] Validation failed:", error);
    throw error;
  }

  // Get current user from session
  const session = await getServerSession(authOptions);

  if (!session?.user?.id) {
    console.error("[createPin] No authenticated user session");
    throw new Error("Not authenticated");
  }

  const user = await prisma.user.findUnique({
    where: { id: session.user.id },
  });

  if (!user) {
    console.error("[createPin] User not found in database");
    throw new Error("User not found");
  }

  // Verify user has access to the world
  const world = await prisma.gameWorld.findUnique({
    where: { id: validated.gameWorldId },
  });

  if (!world) {
    console.error("[createPin] World not found");
    throw new Error("World not found");
  }

  if (world.userId !== user.id) {
    // Check if user is a member with editor permissions
    const member = await prisma.worldMember.findFirst({
      where: {
        gameWorldId: validated.gameWorldId,
        userId: user.id,
        permission: { in: ["EDITOR", "OWNER"] },
      },
    });

    if (!member) {
      console.error("[createPin] Unauthorized - no editor permissions");
      throw new Error("Unauthorized: You don't have permission to add pins to this world");
    }
  }

  // If layerId provided, verify layer belongs to the world
  if (validated.layerId) {
    const layer = await prisma.mapLayer.findUnique({
      where: { id: validated.layerId },
    });

    if (!layer || layer.gameWorldId !== validated.gameWorldId) {
      console.error("[createPin] Invalid layer - does not belong to this world");
      throw new Error("Invalid layer: Layer does not belong to this world");
    }
  }

  // Create pin
  let pin;
  try {
    pin = await prisma.pin.create({
      data: {
        title: validated.title,
        description: validated.description,
        pinType: validated.pinType,
        latitude: validated.latitude,
        longitude: validated.longitude,
        icon: validated.icon,
        color: validated.color,
        size: validated.size,
        opacity: validated.opacity ?? 1.0,
        isVisible: validated.isVisible ?? true,
        properties: validated.properties,

        userId: user.id,
        gameWorldId: validated.gameWorldId,
        layerId: validated.layerId,
      },
    });
  } catch (error) {
    console.error("[createPin] Database write failed:", error);
    throw error;
  }

  // Note: No revalidatePath needed - TanStack Query manages client cache via optimistic updates
  // The cache is already updated by onSuccess in use-pins.ts

  return { pinId: pin.id, pin };
}

/**
 * Get a pin by ID
 * @param id - Pin ID
 * @returns Pin with full details or null
 */
export async function getPinById(id: string) {
  const pin = await prisma.pin.findUnique({
    where: { id },
    include: {
      user: {
        select: {
          name: true,
          image: true,
        },
      },
      gameWorld: {
        select: {
          id: true,
          title: true,
        },
      },
      layer: {
        select: {
          id: true,
          name: true,
          isVisible: true,
          zIndex: true,
        },
      },
      gallery: {
        orderBy: { order: "asc" },
      },
    },
  });

  return pin;
}

/**
 * Update an existing pin
 * @param data - Pin update data (validated with Zod)
 * @returns Updated pin
 * @throws Error if user not authorized or pin not found
 */
export async function updatePin(data: PinUpdateInput) {
  // Validate input with Zod
  const validated = UpdatePinSchema.parse(data);

  // Get authenticated user from session
  const session = await getServerSession(authOptions);

  if (!session?.user?.id) {
    throw new Error("Not authenticated");
  }

  const user = await prisma.user.findUnique({
    where: { id: session.user.id },
  });

  if (!user) {
    throw new Error("User not found");
  }

  // Check if pin exists and user has permission
  const existingPin = await prisma.pin.findUnique({
    where: { id: validated.id },
    include: {
      gameWorld: true,
    },
  });

  if (!existingPin) {
    throw new Error("Pin not found");
  }

  // Check ownership or editor permission
  if (existingPin.userId !== user.id) {
    const member = await prisma.worldMember.findFirst({
      where: {
        gameWorldId: existingPin.gameWorldId,
        userId: user.id,
        permission: { in: ["EDITOR", "OWNER"] },
      },
    });

    if (!member) {
      throw new Error("Unauthorized: You don't have permission to edit this pin");
    }
  }

  // If layerId is being updated, verify it belongs to the world
  if (validated.layerId !== undefined) {
    if (validated.layerId === null) {
      // Allow removing layer assignment
    } else {
      const layer = await prisma.mapLayer.findUnique({
        where: { id: validated.layerId },
      });

      if (!layer || layer.gameWorldId !== existingPin.gameWorldId) {
        throw new Error("Invalid layer: Layer does not belong to this world");
      }
    }
  }

  // Build update data (only include fields that are provided)
  const updateData: any = {};
  if (validated.title !== undefined) updateData.title = validated.title;
  if (validated.description !== undefined) updateData.description = validated.description;
  if (validated.pinType !== undefined) updateData.pinType = validated.pinType;
  if (validated.latitude !== undefined) updateData.latitude = validated.latitude;
  if (validated.longitude !== undefined) updateData.longitude = validated.longitude;
  if (validated.icon !== undefined) updateData.icon = validated.icon;
  if (validated.color !== undefined) updateData.color = validated.color;
  if (validated.size !== undefined) updateData.size = validated.size;
  if (validated.opacity !== undefined) updateData.opacity = validated.opacity;
  if (validated.isVisible !== undefined) updateData.isVisible = validated.isVisible;
  if (validated.properties !== undefined) updateData.properties = validated.properties;
  if (validated.layerId !== undefined) updateData.layerId = validated.layerId;

  // Update pin
  const pin = await prisma.pin.update({
    where: { id: validated.id },
    data: updateData,
  });

  // Note: No revalidatePath needed - TanStack Query manages client cache via optimistic updates

  return pin;
}

/**
 * Delete a pin
 * @param id - Pin ID
 * @returns Deleted pin ID
 * @throws Error if user not authorized or pin not found
 */
export async function deletePin(id: string) {
  // Get authenticated user from session
  const session = await getServerSession(authOptions);

  if (!session?.user?.id) {
    throw new Error("Not authenticated");
  }

  const user = await prisma.user.findUnique({
    where: { id: session.user.id },
  });

  if (!user) {
    throw new Error("User not found");
  }

  // Check if pin exists and user has permission
  const pin = await prisma.pin.findUnique({
    where: { id },
  });

  if (!pin) {
    throw new Error("Pin not found");
  }

  // Check ownership or editor permission
  if (pin.userId !== user.id) {
    const member = await prisma.worldMember.findFirst({
      where: {
        gameWorldId: pin.gameWorldId,
        userId: user.id,
        permission: { in: ["EDITOR", "OWNER"] },
      },
    });

    if (!member) {
      throw new Error("Unauthorized: You don't have permission to delete this pin");
    }
  }

  // Delete pin
  await prisma.pin.delete({
    where: { id },
  });

  // Note: No revalidatePath needed - TanStack Query manages client cache via optimistic updates

  return { pinId: id };
}

/**
 * Toggle pin visibility
 * Convenience action for showing/hiding pins
 * @param id - Pin ID
 * @returns Updated pin
 */
export async function togglePinVisibility(id: string) {
  // Get authenticated user from session
  const session = await getServerSession(authOptions);

  if (!session?.user?.id) {
    throw new Error("Not authenticated");
  }

  const user = await prisma.user.findUnique({
    where: { id: session.user.id },
  });

  if (!user) {
    throw new Error("User not found");
  }

  const pin = await prisma.pin.findUnique({
    where: { id },
  });

  if (!pin) {
    throw new Error("Pin not found");
  }

  // Check permission
  if (pin.userId !== user.id) {
    const member = await prisma.worldMember.findFirst({
      where: {
        gameWorldId: pin.gameWorldId,
        userId: user.id,
        permission: { in: ["EDITOR", "OWNER"] },
      },
    });

    if (!member) {
      throw new Error("Unauthorized: You don't have permission to modify this pin");
    }
  }

  // Toggle visibility
  const updated = await prisma.pin.update({
    where: { id },
    data: { isVisible: !pin.isVisible },
  });

  // Note: If this action is used directly (not through updatePin), consider cache invalidation
  revalidatePath(`/worlds/${pin.gameWorldId}`);

  return updated;
}

/**
 * Update pin position (for drag-and-drop)
 * Updates only latitude and longitude of a pin
 * @param pinId - Pin ID to update
 * @param latitude - New latitude (0-1 range)
 * @param longitude - New longitude (0-1 range)
 * @returns Updated pin
 */
export async function updatePinPosition(pinId: string, latitude: number, longitude: number) {
  // Validate coordinates are in valid range
  if (latitude < 0 || latitude > 1 || longitude < 0 || longitude > 1) {
    throw new Error("Invalid coordinates: must be between 0 and 1");
  }

  // Get current user
  const session = await getServerSession(authOptions);

  if (!session?.user?.id) {
    throw new Error("Not authenticated");
  }

  // Check if pin exists and user has permission
  const pin = await prisma.pin.findUnique({
    where: { id: pinId },
    include: {
      gameWorld: true,
    },
  });

  if (!pin) {
    throw new Error("Pin not found");
  }

  // Check ownership or editor permission
  if (pin.userId !== session.user.id) {
    const member = await prisma.worldMember.findFirst({
      where: {
        gameWorldId: pin.gameWorldId,
        userId: session.user.id,
        permission: { in: ["EDITOR", "OWNER"] },

      },
    });

    if (!member) {
      throw new Error("Unauthorized: You don't have permission to move this pin");
    }
  }

  // Update pin position
  const updated = await prisma.pin.update({
    where: { id: pinId },
    data: {
      latitude,
      longitude,
    },
  });

  // CRITICAL FIX: No revalidatePath here!
  // The Zustand store is updated optimistically in pin-marker.tsx BEFORE this server call
  // Calling revalidatePath would cause TanStack Query to refetch, creating a race condition
  // where stale data overwrites the new position before the UI updates

  return updated;
}

/**
 * Upload a custom icon for a pin
 * @param pinId - Pin ID to update
 * @param formData - FormData containing the icon file
 * @returns Updated pin with new icon path
 */
export async function uploadPinIcon(pinId: string, formData: FormData) {
  // Get authenticated user from session
  const session = await getServerSession(authOptions);

  if (!session?.user?.id) {
    console.error("[uploadPinIcon] No authenticated user session");
    throw new Error("Not authenticated");
  }

  const user = await prisma.user.findUnique({
    where: { id: session.user.id },
  });

  if (!user) {
    console.error("[uploadPinIcon] User not found in database");
    throw new Error("User not found");
  }

  // Check if pin exists and user has permission
  const pin = await prisma.pin.findUnique({
    where: { id: pinId },
    include: {
      gameWorld: true,
    },
  });

  if (!pin) {
    console.error("[uploadPinIcon] Pin not found");
    throw new Error("Pin not found");
  }

  // Check ownership or editor permission
  if (pin.userId !== user.id) {
    const member = await prisma.worldMember.findFirst({
      where: {
        gameWorldId: pin.gameWorldId,
        userId: user.id,
        permission: { in: ["EDITOR", "OWNER"] },
      },
    });

    if (!member) {
      console.error("[uploadPinIcon] Unauthorized - no editor permissions");
      throw new Error(
        "Unauthorized: You don't have permission to edit this pin"
      );
    }
  }

  // Get file from formData
  const file = formData.get("file") as File;

  if (!file) {
    console.error("[uploadPinIcon] No file provided in formData");
    throw new Error("No file provided");
  }

  // Validate file type
  const validTypes = ["image/svg+xml", "image/png", "image/webp"];
  if (!validTypes.includes(file.type)) {
    throw new Error("Invalid file type. Please upload an SVG, PNG, or WEBP image.");
  }

  // Validate file size (max 500KB)
  const maxSize = 500 * 1024; // 500KB
  if (file.size > maxSize) {
    throw new Error("File size must be less than 500KB");
  }

  // Create pins/icons directory if it doesn't exist
  const { writeFile, mkdir } = require("fs/promises");
  const path = require("path");
  const uploadsDir = path.join(process.cwd(), "public", "uploads", "pins", "icons");

  try {
    await mkdir(uploadsDir, { recursive: true });
  } catch (error) {
    // Directory might already exist, ignore error
  }

  // Generate unique filename with UUID
  const timestamp = Date.now();
  const randomId = Math.random().toString(36).substring(2, 15);
  const ext = path.extname(file.name);
  const sanitizedName = file.name.replace(/[^a-zA-Z0-9.-]/g, "_");
  const fileName = `${timestamp}-${randomId}-${sanitizedName}`;
  const filePath = path.join(uploadsDir, fileName);

  try {
    const bytes = await file.arrayBuffer();
    const buffer = Buffer.from(bytes);
    await writeFile(filePath, buffer);

    const iconPath = `/uploads/pins/icons/${fileName}`;

    // Update pin with new icon path
    const updatedPin = await prisma.pin.update({
      where: { id: pinId },
      data: { icon: iconPath },
    });

    // Revalidate the world page
    revalidatePath(`/world/${pin.gameWorldId}`);

    return {
      success: true,
      iconUrl: iconPath,
      pin: updatedPin,
    };
  } catch (error) {
    console.error("[uploadPinIcon] Failed to save file:", error);
    throw new Error("Failed to save icon image");
  }
}

/**
 * Batch update pin positions
 * For dragging multiple pins at once
 * @param updates - Array of { id, latitude, longitude }
 * @returns Updated pins
 */
export async function batchUpdatePinPositions(updates: Array<{
  id: string;
  latitude: number;
  longitude: number;
}>) {
  // Get authenticated user from session
  const session = await getServerSession(authOptions);

  if (!session?.user?.id) {
    throw new Error("Not authenticated");
  }

  const user = await prisma.user.findUnique({
    where: { id: session.user.id },
  });

  if (!user) {
    throw new Error("User not found");
  }

  // Verify all pins exist and user has permission
  const pins = await prisma.pin.findMany({
    where: {
      id: { in: updates.map((u) => u.id) },
    },
  });

  if (pins.length !== updates.length) {
    throw new Error("One or more pins not found");
  }

  // Check permissions for all pins
  const worldIds = [...new Set(pins.map((p) => p.gameWorldId))];

  for (const worldId of worldIds) {
    const world = await prisma.gameWorld.findUnique({
      where: { id: worldId },
    });

    if (world?.userId !== user.id) {
      const member = await prisma.worldMember.findFirst({
        where: {
          gameWorldId: worldId,
          userId: user.id,
          permission: { in: ["EDITOR", "OWNER"] },
        },
      });

      if (!member) {
        throw new Error("Unauthorized: You don't have permission to modify pins in this world");
      }
    }
  }

  // Update all pins
  const updatedPins = await Promise.all(
    updates.map((update) =>
      prisma.pin.update({
        where: { id: update.id },
        data: {
          latitude: update.latitude,
          longitude: update.longitude,
        },
      })
    )
  );

  // Revalidate only the affected world paths
  for (const worldId of worldIds) {
    revalidatePath(`/worlds/${worldId}`);
  }

  return updatedPins;
}

"use server";

import { prisma } from "@/lib/prisma";
import { revalidatePath } from "next/cache";
import { writeFile } from "fs/promises";
import path from "path";
import { existsSync } from "fs";
import { getServerSession } from "next-auth";
import { authOptions } from "@/app/api/auth/[...nextauth]/route";
import type { OptimizedWorld } from "@/types/world.type";

export async function createWorld(data: {
  title: string;
  description: string;
  isPublic: boolean;
  map?: File;
}) {
  // Get authenticated user from session
  const session = await getServerSession(authOptions);

  if (!session?.user?.id) {
    throw new Error("Not authenticated");
  }

  const user = await prisma.user.findUnique({
    where: { id: session.user.id },
  });

  if (!user) {
    throw new Error("User not found");
  }

  let mapPath: string | undefined;

  // Handle map image upload
  if (data.map) {
    const bytes = await data.map.arrayBuffer();
    const buffer = Buffer.from(bytes);

    // Generate unique filename with world ID prefix
    const timestamp = Date.now();
    const fileExtension = data.map.name.split('.').pop();
    const fileName = `${timestamp}-${data.map.name}`;
    const uploadsDir = path.join(process.cwd(), "public", "uploads");

    // Ensure uploads directory exists
    if (!existsSync(uploadsDir)) {
      await writeFile(path.join(uploadsDir, ".gitkeep"), "");
    }

    const filePath = path.join(uploadsDir, fileName);

    try {
      await writeFile(filePath, buffer);

      // Store the relative path in database
      mapPath = `/uploads/${fileName}`;
    } catch (error) {
      console.error("[createWorld] Failed to save file:", error);
      throw new Error("Failed to save map image");
    }
  }

  const world = await prisma.gameWorld.create({
    data: {
      title: data.title,
      description: data.description,
      isPublic: data.isPublic,
      userId: user.id,
      isPublished: true,
      map: mapPath,
    },
  });

  revalidatePath("/explore");
  revalidatePath("/worlds");

  return { worldId: world.id };
}

export async function getWorldById(id: string): Promise<OptimizedWorld | null> {
  const world = await prisma.gameWorld.findUnique({
    where: { id },
    select: {
      id: true,
      title: true,
      description: true,
      map: true,
      isPublished: true,
      isPublic: true,
      userId: true,
      createdAt: true,
      updatedAt: true,
      user: {
        select: {
          name: true,
          image: true,
        },
      },
      layers: {

        select: {
          id: true,
          name: true,
          description: true,
          isVisible: true,
          opacity: true,
          zIndex: true,
        },
        orderBy: { zIndex: "asc" },
      },
      // REMOVED: pins (fetched via usePins hook for better performance)
      // REMOVED: loreEntries (not needed for initial load)
    },
  });

  if (!world) {
    return null;
  }

  return world as OptimizedWorld;
}

/**
 * Get world with all related data in a single query (pins included)
 * Optimized to fetch world + layers + pins in ONE database call
 * Eliminates N+1 query problem and reduces load time from 3.6s to <100ms
 * @param id - World ID
 * @returns World with pins, or null if not found
 */
export async function getWorldWithData(id: string) {
  const world = await prisma.gameWorld.findUnique({
    where: { id },
    select: {
      id: true,
      title: true,
      description: true,
      map: true,
      isPublished: true,
      isPublic: true,
      userId: true,
      createdAt: true,
      updatedAt: true,
      user: {
        select: {
          name: true,
          image: true,
        },
      },
      layers: {
        select: {
          id: true,
          name: true,
          description: true,
          isVisible: true,
          opacity: true,
          zIndex: true,
        },
        orderBy: { zIndex: "asc" },
      },
      pins: {
        where: { isVisible: true },
        orderBy: { createdAt: "desc" },
      },
    },
  });

  if (!world) {
    return null;
  }

  return world;
}

export async function getAllWorlds() {
  const worlds = await prisma.gameWorld.findMany({
    where: {
      isPublic: true,
    },
    include: {
      user: {
        select: {
          name: true,
          image: true,
        },
      },
      _count: {
        select: {
          pins: true,
          loreEntries: true,
        },
      },
    },
    orderBy: {
      createdAt: "desc",
    },
  });

  return worlds;
}

export async function getMyWorlds() {
  // Get authenticated user from session
  const session = await getServerSession(authOptions);

  if (!session?.user?.id) {
    return [];
  }

  const user = await prisma.user.findUnique({
    where: { id: session.user.id },
  });

  if (!user) {
    return [];
  }

  const worlds = await prisma.gameWorld.findMany({
    where: {
      OR: [
        { userId: user.id },
        {
          members: {
            some: {
              userId: user.id,
              permission: {
                in: ["EDITOR", "OWNER"],
              },
            },
          },
        },
      ],
    },
    include: {
      user: {
        select: {
          name: true,
          image: true,
        },
      },
      _count: {
        select: {
          pins: true,
          loreEntries: true,
        },
      },
    },
    orderBy: {
      createdAt: "desc",
    },
  });

  return worlds;
}

export async function updateWorldTitle(id: string, title: string) {
  const world = await prisma.gameWorld.update({
    where: { id },
    data: { title },
  });

  // Note: Only revalidate if needed for SSR. Client-side cache handles updates.
  revalidatePath("/world/[id]");

  return world;
}

/**
 * Update world state (layers, map properties, etc.) for autosave
 * @param worldId - World ID to update
 * @param state - World state object containing layers and other properties
 * @returns Updated world
 * @throws Error if user not authorized or world not found
 */
export async function updateWorldState(
  worldId: string,
  state: {
    layers?: Array<{
      id: string;
      name: string;
      visible: boolean;
      locked: boolean;
      opacity: number;
      zIndex: number;
    }>;
    grid?: boolean;
    snap?: boolean;
    scale?: string;
    pinCount?: number; // Track pin count to trigger autosave on pin changes
  }
) {
  // Get authenticated user from session
  const session = await getServerSession(authOptions);

  if (!session?.user?.id) {
    console.error("[updateWorldState] No authenticated user session");
    throw new Error("Not authenticated");
  }

  const user = await prisma.user.findUnique({
    where: { id: session.user.id },

  });

  if (!user) {
    console.error("[updateWorldState] User not found in database");
    throw new Error("User not found");
  }

  // Check if world exists and user has permission
  const world = await prisma.gameWorld.findUnique({
    where: { id: worldId },
  });

  if (!world) {
    throw new Error("World not found");
  }

  // Check ownership or editor permission
  if (world.userId !== user.id) {
    const member = await prisma.worldMember.findFirst({
      where: {
        gameWorldId: worldId,
        userId: user.id,
        permission: { in: ["EDITOR", "OWNER"] },
      },
    });

    if (!member) {
      throw new Error("Unauthorized: You don't have permission to edit this world");
    }
  }

  // Update layers if provided
  if (state.layers) {
    // Process each layer: create or update
    for (const layer of state.layers) {
      // Check if layer exists
      const existingLayer = await prisma.mapLayer.findUnique({
        where: { id: layer.id },
      });

      if (existingLayer) {
        // Update existing layer
        await prisma.mapLayer.update({
          where: { id: layer.id },
          data: {
            name: layer.name,
            isVisible: layer.visible,
            opacity: layer.opacity,
            zIndex: layer.zIndex,
          },
        });
      } else {
        // Create new layer (shouldn't happen in normal flow, but handle it)
        await prisma.mapLayer.create({
          data: {
            id: layer.id,
            name: layer.name,
            isVisible: layer.visible,
            opacity: layer.opacity,
            zIndex: layer.zIndex,
            gameWorldId: worldId,
          },
        });
      }
    }
  }

  // Note: grid, snap, scale are UI-only state stored in Zustand
  // They don't need to be persisted to the database unless you want to
  // remember them across sessions. If so, add them to GameWorld schema.

  // Note: pinCount is used to trigger autosave when pins are added/edited/deleted
  // The pins themselves are managed independently via their own Server Actions
  // (createPin, updatePin, deletePin in actions/pins.ts)
  // We don't save pinCount to the database - it's just for change detection

  // Return updated world with layers
  const updatedWorld = await prisma.gameWorld.findUnique({
    where: { id: worldId },
    include: {
      layers: {
        orderBy: { zIndex: "asc" },
      },
    },
  });

  // Note: No revalidatePath needed - Zustand store manages client-side layer state
  // The autosave hook updates the local state directly

  return updatedWorld;
}

/**
 * Upload a new map image for a world
 * @param worldId - World ID to update
 * @param formData - FormData containing the file upload
 * @returns Success status and new map URL
 * @throws Error if user not authorized, file invalid, or upload fails
 */
export async function uploadWorldMap(worldId: string, formData: FormData) {

  // Get authenticated user from session
  const session = await getServerSession(authOptions);

  if (!session?.user?.id) {
    console.error("[uploadWorldMap] No authenticated user session");
    throw new Error("Not authenticated");
  }

  const user = await prisma.user.findUnique({
    where: { id: session.user.id },
  });

  if (!user) {
    console.error("[uploadWorldMap] User not found in database");
    throw new Error("User not found");
  }

  // Check if world exists and user has permission
  const world = await prisma.gameWorld.findUnique({
    where: { id: worldId },
  });

  if (!world) {
    throw new Error("World not found");
  }

  // Check ownership or editor permission
  if (world.userId !== user.id) {
    const member = await prisma.worldMember.findFirst({
      where: {
        gameWorldId: worldId,
        userId: user.id,
        permission: { in: ["EDITOR", "OWNER"] },
      },
    });

    if (!member) {
      throw new Error("Unauthorized: You don't have permission to edit this world");
    }
  }

  // Get file from formData
  const file = formData.get("file") as File;

  if (!file) {
    console.error("[uploadWorldMap] No file provided in formData");
    throw new Error("No file provided");
  }

  // Validate file type
  const validTypes = ["image/webp", "image/png", "image/jpeg", "image/jpg"];
  if (!validTypes.includes(file.type)) {
    throw new Error("Invalid file type. Please upload a WebP, PNG, or JPEG image.");
  }

  // Validate file size (max 10MB)
  const maxSize = 10 * 1024 * 1024; // 10MB
  if (file.size > maxSize) {
    throw new Error("File size must be less than 10MB");
  }

  // Save file
  const timestamp = Date.now();
  const sanitizedFileName = file.name.replace(/[^a-zA-Z0-9.-]/g, "_");
  const fileName = `${timestamp}-${sanitizedFileName}`;
  const uploadsDir = path.join(process.cwd(), "public", "uploads");

  // Ensure uploads directory exists
  if (!existsSync(uploadsDir)) {
    await writeFile(path.join(uploadsDir, ".gitkeep"), "");
  }

  const filePath = path.join(uploadsDir, fileName);

  try {
    const bytes = await file.arrayBuffer();
    const buffer = Buffer.from(bytes);
    await writeFile(filePath, buffer);

    const mapPath = `/uploads/${fileName}`;

    // Update database with new map path
    const updatedWorld = await prisma.gameWorld.update({
      where: { id: worldId },
      data: { map: mapPath },
    });

    // Revalidate the world page to refresh server component
    revalidatePath(`/world/${worldId}`);

    return {
      success: true,
      mapUrl: mapPath,
    };
  } catch (error) {
    console.error("[uploadWorldMap] Failed to save file:", error);
    throw new Error("Failed to save map image");
  }
}

import NextAuth, { NextAuthOptions, DefaultSession } from "next-auth";
import { PrismaAdapter } from "@auth/prisma-adapter";
import { prisma } from "@/lib/prisma";
import GitHubProvider from "next-auth/providers/github";
import DiscordProvider from "next-auth/providers/discord";
import { Role } from "@prisma/client";

declare module "next-auth" {
  interface Session {
    user: {
      id: string;
      role: Role;
    } & DefaultSession["user"];
  }

  interface User {
    role: Role;
  }
}

export const authOptions: NextAuthOptions = {
  adapter: PrismaAdapter(prisma) as any,
  providers: [
    GitHubProvider({
      clientId: process.env.GITHUB_CLIENT_ID!,
      clientSecret: process.env.GITHUB_CLIENT_SECRET!,
      authorization: {
        params: {
          redirect_uri: process.env.NEXTAUTH_URL + "/api/auth/callback/github",
        },
      },
    }),
    DiscordProvider({
      clientId: process.env.DISCORD_CLIENT_ID!,
      clientSecret: process.env.DISCORD_CLIENT_SECRET!,
      authorization: {
        params: {
          redirect_uri: process.env.NEXTAUTH_URL + "/api/auth/callback/discord",
        },
      },
    }),
  ],
  session: {
    strategy: "jwt",
  },
  pages: {
    signIn: "/auth/signin",
  },
  callbacks: {
    async session({ session, token }) {
      if (session.user) {
        session.user.id = token.sub!;
        session.user.role = token.role as Role;
      }
      return session;
    },
    async jwt({ token, user }) {
      if (user) {
        token.sub = user.id;
        token.role = user.role;
      }
      return token;
    },
  },
};

const handler = NextAuth(authOptions);

export { handler as GET, handler as POST };

import { NextResponse } from "next/server";
import { prisma } from "@/lib/prisma";

export async function GET() {
  const worlds = await prisma.gameWorld.findMany({
    include: {
      _count: {
        select: {
          pins: true,
          loreEntries: true,
        },
      },
    },
    orderBy: { updatedAt: "desc" },
  });

  return NextResponse.json(worlds);
}

export async function POST(req: Request) {
  const body = await req.json();
  const { title, description, isPublic, map } = body;

  const user = await prisma.user.findFirst({
    where: { email: "user@example.com" },
  });

  if (!user) {
    return NextResponse.json({ error: "User not found" }, { status: 404 });
  }

  const world = await prisma.gameWorld.create({
    data: {
      title,
      description,
      isPublic,
      map,
      userId: user.id,
      isPublished: true,
    },
  });

  return NextResponse.json(world);
}

