"use client";

import * as React from "react";

interface Position {
  x: number;
  y: number;
}

interface UseContextMenuPositionOptions {
  position: Position;
  onClose: () => void;
}

interface UseContextMenuPositionReturn {
  menuRef: React.RefObject<HTMLDivElement | null>;
  adjustedPosition: Position;
}

export function useContextMenuPosition({
  position,
  onClose,
}: UseContextMenuPositionOptions): UseContextMenuPositionReturn {
  const menuRef = React.useRef<HTMLDivElement>(null);
  const [adjustedPosition, setAdjustedPosition] = React.useState(position);

  React.useEffect(() => {
    if (!menuRef.current) return;

    const menu = menuRef.current;
    const rect = menu.getBoundingClientRect();
    const viewportWidth = window.innerWidth;
    const viewportHeight = window.innerHeight;

    let adjustedX = position.x;
    let adjustedY = position.y;

    if (position.x + rect.width > viewportWidth - 16) {
      adjustedX = viewportWidth - rect.width - 16;
    }

    if (position.y + rect.height > viewportHeight - 16) {
      adjustedY = viewportHeight - rect.height - 16;
    }

    if (adjustedX < 16) adjustedX = 16;
    if (adjustedY < 16) adjustedY = 16;

    setAdjustedPosition({ x: adjustedX, y: adjustedY });
  }, [position]);

  React.useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (
        menuRef.current &&
        !menuRef.current.contains(event.target as Node)
      ) {
        onClose();
      }
    };

    document.addEventListener("mousedown", handleClickOutside);
    return () => {
      document.removeEventListener("mousedown", handleClickOutside);
    };
  }, [onClose]);

  React.useEffect(() => {
    const handleEscape = (event: KeyboardEvent) => {
      if (event.key === "Escape") {
        onClose();
      }
    };

    document.addEventListener("keydown", handleEscape);
    return () => {
      document.removeEventListener("keydown", handleEscape);
    };
  }, [onClose]);

  React.useEffect(() => {
    const handleContextMenu = (event: MouseEvent) => {
      event.preventDefault();
    };

    document.addEventListener("contextmenu", handleContextMenu);
    return () => {
      document.removeEventListener("contextmenu", handleContextMenu);
    };
  }, []);

  return { menuRef, adjustedPosition };
}

import { useState, useRef, useCallback } from "react";
import { updatePinPosition } from "@/actions/pins";

/**
 * Configuration for usePinDrag hook
 */
export interface UsePinDragConfig {
  /** Pin ID to update */
  pinId: string;
  /** Initial position (as percentage 0-1) */
  latitude: number;
  longitude: number;
  /** Map dimensions in pixels for boundary clamping */
  mapWidth: number;
  mapHeight: number;
  /** Current transform scale for coordinate conversion */
  scale: number;
  /** Whether the layer is locked (prevents dragging) */
  isLocked?: boolean;
  /** Callback to select pin on drag start */
  onSelectPin?: (pinId: string) => void;
  /** Callback to update pin in Zustand store (optimistic update) */
  onUpdatePin?: (pinId: string, updates: { latitude: number; longitude: number }) => void;
}

/**
 * Return type for usePinDrag hook
 */
export interface UsePinDragReturn {
  /** Whether the pin is currently being dragged */
  isDragging: boolean;
  /** Current drag position in pixels (null if not dragging) */
  dragPosition: { x: number; y: number } | null;
  /** Whether the pin moved significantly during drag (prevents click on drag end) */
  hasMovedDuringDrag: boolean;
  /** Mouse down handler to attach to pin element */
  handleMouseDown: (e: React.MouseEvent) => void;
}

/**
 * Custom hook for pin drag-and-drop functionality.
 *
 * Features:
 * - Drag starts only after 3px movement (prevents hover from triggering drag)
 * - Position clamping to map boundaries
 * - Optimistic updates to Zustand store
 * - Background DB sync via updatePinPosition server action
 * - Window-level event listeners for drag continuation
 * - Layer lock detection
 *
 * @example
 * ```tsx
 * const { isDragging, dragPosition, hasMovedDuringDrag, handleMouseDown } = usePinDrag({
 *   pinId: pin.id,
 *   latitude: pin.latitude,
 *   longitude: pin.longitude,
 *   mapWidth: 1920,
 *   mapHeight: 1080,
 *   scale: transform.scale,
 *   isLocked: layer?.locked ?? false,
 *   onSelectPin: selectPin,
 *   onUpdatePin: updatePin,
 * });
 * ```
 */
export function usePinDrag(config: UsePinDragConfig): UsePinDragReturn {
  const {
    pinId,
    latitude,
    longitude,
    mapWidth,
    mapHeight,
    scale,
    isLocked = false,
    onSelectPin,
    onUpdatePin,
  } = config;

  // Drag state
  const [isDragging, setIsDragging] = useState(false);
  const [dragPosition, setDragPosition] = useState<{ x: number; y: number } | null>(null);
  const [hasMovedDuringDrag, setHasMovedDuringDrag] = useState(false);

  // Refs for drag logic
  const dragStartPos = useRef<{ x: number; y: number } | null>(null);
  const isDraggingRef = useRef(false);
  const dragPositionRef = useRef<{ x: number; y: number } | null>(null);
  const hasMovedDuringDragRef = useRef(false);

  // Convert percentage coordinates to pixels
  const initialPixelX = longitude * mapWidth;
  const initialPixelY = latitude * mapHeight;

  /**
   * Mouse move handler - attached to window during drag
   */
  const handleMouseMove = useCallback((e: MouseEvent) => {
    // Initialize drag on first significant movement
    if (!dragStartPos.current) {
      return;

    }

    // Calculate delta in screen coordinates (adjusted for scale)
    const deltaX = (e.clientX - dragStartPos.current.x) / scale;
    const deltaY = (e.clientY - dragStartPos.current.y) / scale;

    // Check if movement is significant (> 3 pixels to account for small movements)
    const hasSignificantMovement = Math.abs(deltaX) > 3 || Math.abs(deltaY) > 3;

    if (hasSignificantMovement) {
      // Start dragging on first significant movement
      if (!isDraggingRef.current) {
        isDraggingRef.current = true;
        setIsDragging(true);
      }
      hasMovedDuringDragRef.current = true;
      setHasMovedDuringDrag(true);
    }

    // Only update position if we're actively dragging
    if (!isDraggingRef.current) {
      return;
    }

    // Calculate new position (start from pin's original position)
    let newX = initialPixelX + deltaX;
    let newY = initialPixelY + deltaY;

    // Clamp to map boundaries
    newX = Math.max(0, Math.min(mapWidth, newX));
    newY = Math.max(0, Math.min(mapHeight, newY));

    // Update visual position only (not database yet)
    const newPosition = { x: newX, y: newY };
    dragPositionRef.current = newPosition;
    setDragPosition(newPosition);
  }, [scale, mapWidth, mapHeight, initialPixelX, initialPixelY]);

  /**
   * Mouse up handler - attached to window during drag
   */
  const handleMouseUp = useCallback(async (e: MouseEvent) => {
    // Always clean up window listeners, even if we never started dragging
    window.removeEventListener("mousemove", handleMouseMove);
    window.removeEventListener("mouseup", handleMouseUp);

    // Only proceed with drag logic if we were actually dragging
    if (!isDraggingRef.current) {
      dragStartPos.current = null;
      return;
    }

    isDraggingRef.current = false;
    setIsDragging(false);

    // If we have a drag position and actually moved, save to database
    const currentDragPosition = dragPositionRef.current;
    if (currentDragPosition && hasMovedDuringDragRef.current) {
      // Convert pixel position to map coordinates (0-1 range)
      const newLatitude = Math.max(0, Math.min(1, currentDragPosition.y / mapHeight));
      const newLongitude = Math.max(0, Math.min(1, currentDragPosition.x / mapWidth));

      // CRITICAL FIX: Update Zustand store FIRST (optimistic update)
      // This prevents race condition where TanStack Query refetch overwrites new position
      if (onUpdatePin) {
        onUpdatePin(pinId, {
          latitude: newLatitude,
          longitude: newLongitude,
        });
      }

      // Then update database in background (fire-and-forget)
      // Zustand is now source of truth, DB sync happens asynchronously
      updatePinPosition(pinId, newLatitude, newLongitude).catch((error) => {
        console.error("Failed to save pin position to database:", error);
        // Note: We could rollback here, but for UX we keep the optimistic update
        // The next page refresh will sync with DB state
      });

      // Clear drag position
      dragPositionRef.current = null;
      setDragPosition(null);
    }

    dragStartPos.current = null;
    // Note: Don't reset hasMovedDuringDrag here, as handleClick needs it
    // It will be reset on next mouseDown
  }, [mapWidth, mapHeight, pinId, onUpdatePin, handleMouseMove]);

  /**
   * Mouse down handler - attach to pin element
   */
  const handleMouseDown = useCallback((e: React.MouseEvent) => {
    // Prevent dragging if layer is locked
    if (isLocked) {
      return;
    }

    // Only left mouse button
    if (e.button !== 0) {

      return;
    }

    e.preventDefault();
    e.stopPropagation();

    // Store initial mouse position
    dragStartPos.current = {
      x: e.clientX,
      y: e.clientY,
    };

    // DON'T set isDragging yet - wait for actual mouse movement
    // This prevents hover from triggering drag behavior
    setHasMovedDuringDrag(false); // Reset movement flag
    hasMovedDuringDragRef.current = false;

    // Select pin on drag start
    if (onSelectPin) {
      onSelectPin(pinId);
    }

    // Add window-level event listeners for drag continuation
    window.addEventListener("mousemove", handleMouseMove);
    window.addEventListener("mouseup", handleMouseUp);
  }, [isLocked, pinId, onSelectPin, handleMouseMove, handleMouseUp]);

  return {
    isDragging,
    dragPosition,
    hasMovedDuringDrag,
    handleMouseDown,
  };
}

import { useState, useEffect, useCallback } from "react";
import { usePinsStore } from "@/stores/use-pins-store";
import { eventManager } from "@/lib/event-manager";

interface UsePinEventsParams {
  pinId: string;
  isDragging: boolean;
  isPinSelected: boolean;
}

interface UsePinEventsReturn {
  isHovered: boolean;
  handleMouseEnter: () => void;
  handleMouseLeave: () => void;
}

/**
 * Custom hook to manage pin event interactions.
 * Handles hover state, event capture, and integration with the pins store.
 *
 * This hook encapsulates all event-related logic for a pin marker:
 * - Hover state management
 * - Event capture via eventManager (prevents deselection bugs)
 * - Integration with usePinsStore for hover/selection state
 *
 * @param params - Hook parameters
 * @param params.pinId - The ID of the pin
 * @param params.isDragging - Whether the pin is currently being dragged
 * @param params.isPinSelected - Whether the pin is currently selected
 *
 * @returns Event state and handlers
 */
export function usePinEvents({
  pinId,
  isDragging,
  isPinSelected,
}: UsePinEventsParams): UsePinEventsReturn {
  // Hover state for this specific pin
  const [isHovered, setIsHovered] = useState(false);

  // Store methods for hover and selection
  const setHoverPin = usePinsStore((state) => state.setHoverPin);

  /**
   * Capture events when pin is hovered or selected.
   * This prevents the deselection bug that occurs when clicking outside pins.
   * The eventManager ensures that map clicks don't interfere with pin interactions.
   */
  useEffect(() => {
    // Only capture events if not dragging (dragging has its own event handling)
    if (!isDragging && (isHovered || isPinSelected)) {
      const release = eventManager.capture("pin-marker");
      return () => release();
    }
  }, [isHovered, isPinSelected, isDragging]);

  /**
   * Handle mouse enter event.
   * Sets local hover state and updates the global hover pin in the store.
   */
  const handleMouseEnter = useCallback(() => {
    setIsHovered(true);
    setHoverPin(pinId);
  }, [pinId, setHoverPin]);

  /**
   * Handle mouse leave event.
   * Clears local hover state and removes the global hover pin from the store.
   */
  const handleMouseLeave = useCallback(() => {
    setIsHovered(false);
    setHoverPin(null);
  }, [setHoverPin]);

  return {
    isHovered,
    handleMouseEnter,
    handleMouseLeave,
  };
}

import { useState, useCallback, useEffect, useRef } from "react";
import { z } from "zod";
import { PinTypeEnum, PIN_TYPE_COLORS, PIN_TYPE_SIZES, type PinCreateInput, type PinUpdateInput } from "@/types/pin.type";
import { CreatePinSchema, UpdatePinSchema } from "./pin-schemas";

export interface PinFormData {
  title: string;
  description: string;
  pinType: PinTypeEnum;
  latitude: number;
  longitude: number;
  color: string;
  size: number;
  isVisible: boolean;
  properties: string;
  icon: string;
  layerId: string;
}

export interface UsePinFormOptions {
  initialData?: Partial<PinFormData>;
  mode: "create" | "edit";
  worldId?: string;
  pinId?: string;
}

export function usePinForm({ initialData, mode, worldId, pinId }: UsePinFormOptions) {
  const [formData, setFormData] = useState<PinFormData>({
    title: initialData?.title || "",
    description: initialData?.description || "",
    pinType: initialData?.pinType || PinTypeEnum.CUSTOM,
    latitude: initialData?.latitude || 0,
    longitude: initialData?.longitude || 0,
    color: initialData?.color || PIN_TYPE_COLORS[PinTypeEnum.CUSTOM],
    size: initialData?.size || PIN_TYPE_SIZES[PinTypeEnum.CUSTOM],
    isVisible: initialData?.isVisible ?? true,
    properties: initialData?.properties || "",
    icon: initialData?.icon || "",
    layerId: initialData?.layerId || "",
  });

  const [errors, setErrors] = useState<Record<string, string>>({});

  // Auto-sync pin type color and size
  useEffect(() => {
    if (formData.pinType && !initialData?.color) {
      setFormData((prev) => ({
        ...prev,
        color: PIN_TYPE_COLORS[formData.pinType],
        size: PIN_TYPE_SIZES[formData.pinType],
      }));
    }
  }, [formData.pinType, initialData?.color]);

  // Sync initialData changes (for edit mode)
  useEffect(() => {
    if (mode === "edit" && initialData) {
      setFormData((prev) => ({
        ...prev,
        ...initialData,
      }));
    }
  }, [mode, initialData]);

  const updateField = useCallback((field: keyof PinFormData, value: string | number | boolean) => {
    setFormData((prev) => ({ ...prev, [field]: value }));
    // Clear error for this field when user types
    if (errors[field]) {
      setErrors((prev) => {
        const newErrors = { ...prev };
        delete newErrors[field];
        return newErrors;
      });
    }
  }, [errors]);

  const validate = useCallback((): boolean => {
    const schema = mode === "create" ? CreatePinSchema : UpdatePinSchema;

    try {
      if (mode === "create") {
        const dataToValidate = {
          ...formData,
          gameWorldId: worldId || "",
        };
        CreatePinSchema.parse(dataToValidate);
      } else {
        const dataToValidate = {
          id: pinId || "",
          ...formData,
        };
        UpdatePinSchema.parse(dataToValidate);
      }

      setErrors({});
      return true;
    } catch (error) {
      if (error instanceof z.ZodError) {
        const newErrors: Record<string, string> = {};
        error.issues.forEach((issue) => {

          if (issue.path.length > 0) {
            newErrors[issue.path[0].toString()] = issue.message;
          }
        });
        setErrors(newErrors);
      }
      return false;
    }
  }, [formData, mode, worldId, pinId]);

  const getSubmitData = useCallback((): PinCreateInput | PinUpdateInput => {
    let properties = undefined;

    if (formData.properties) {
      try {
        properties = JSON.parse(formData.properties);
      } catch {
        throw new Error("Invalid JSON in properties field");
      }
    }

    const baseData = {
      title: formData.title,
      description: formData.description || undefined,
      pinType: formData.pinType,
      latitude: formData.latitude,
      longitude: formData.longitude,
      color: formData.color,
      size: formData.size,
      isVisible: formData.isVisible,
      properties,
      icon: formData.icon || undefined,
      layerId: formData.layerId || undefined,
    };

    if (mode === "create") {
      return {
        ...baseData,
        gameWorldId: worldId || "",
      } as PinCreateInput;
    } else {
      return {
        id: pinId || "",
        ...baseData,
      } as PinUpdateInput;
    }
  }, [formData, mode, worldId, pinId]);

  const reset = useCallback(() => {
    setFormData({
      title: initialData?.title || "",
      description: initialData?.description || "",
      pinType: initialData?.pinType || PinTypeEnum.CUSTOM,
      latitude: initialData?.latitude || 0,
      longitude: initialData?.longitude || 0,
      color: initialData?.color || PIN_TYPE_COLORS[PinTypeEnum.CUSTOM],
      size: initialData?.size || PIN_TYPE_SIZES[PinTypeEnum.CUSTOM],
      isVisible: initialData?.isVisible ?? true,
      properties: initialData?.properties || "",
      icon: initialData?.icon || "",
      layerId: initialData?.layerId || "",
    });
    setErrors({});
  }, [initialData]);

  return {
    formData,
    errors,
    updateField,
    validate,
    getSubmitData,
    reset,
  };
}

import { useMemo } from "react";
import type { Pin } from "@prisma/client";

/**
 * Position calculation hook for pin markers
 *
 * Handles coordinate conversion from latitude/longitude to pixel positions,
 * applies layer offsets, and manages drag positioning.
 *
 * @param pin - Pin data with layer information
 * @param dragPosition - Current drag position (if dragging)
 * @param imageDimensions - Original image dimensions from MapImage
 * @param transform - Map transform state (not used in calculation but needed for consistency)
 * @param layers - Available layers for offset lookup
 *
 * @returns Calculated position, dimensions, and layer info
 */
export function usePinPosition(
  pin: Pin & {
    layer?: {
      id: string;
      isVisible: boolean;
      zIndex: number;
    } | null;
  },
  dragPosition: { x: number; y: number } | null,
  imageDimensions: { width: number; height: number } | undefined,
  transform: {
    scale: number;
    translateX: number;
    translateY: number;
  },
  layers: Array<{
    id: string;
    offsetX?: number;
    offsetY?: number;
    locked?: boolean;
  }>
) {
  // Memoized position calculation to avoid recalculating on every render
  const position = useMemo(() => {
    // Find the layer this pin belongs to (if any)
    const layer = pin.layerId
      ? layers.find((layer) => layer.id === pin.layerId)
      : null;

    // Extract layer offset for position calculation
    const layerOffsetX = layer?.offsetX ?? 0;
    const layerOffsetY = layer?.offsetY ?? 0;

    // Use original image dimensions if provided (from MapImage), otherwise use fallback
    // Note: mapWidth/mapHeight are passed via imageDimensions for consistency
    const actualWidth = imageDimensions?.width ?? 0;
    const actualHeight = imageDimensions?.height ?? 0;

    // Convert lat/lng to pixel coordinates (percentage of ORIGINAL image dimensions)
    // Using drag position if dragging, otherwise use pin's stored position
    const latitude = dragPosition
      ? dragPosition.y / actualHeight
      : pin.latitude;
    const longitude = dragPosition
      ? dragPosition.x / actualWidth
      : pin.longitude;

    // Position is fixed relative to map image (percentage-based)
    // No transform applied here - the parent map container handles pan/zoom
    // Apply layer offset to the final position
    const x = longitude * actualWidth + layerOffsetX;
    const y = latitude * actualHeight + layerOffsetY;

    return {
      x,
      y,
      actualWidth,
      actualHeight,
      layer,
      layerOffsetX,
      layerOffsetY,
      latitude,
      longitude,
    };
  }, [pin, dragPosition, imageDimensions, layers]);

  return position;
}

/**
 * Type exports for TypeScript consumers
 */
export type PinPosition = ReturnType<typeof usePinPosition>;
export type PinPositionCoordinates = Pick<PinPosition, "x" | "y">;
export type PinPositionDimensions = Pick<PinPosition, "actualWidth" | "actualHeight">;

/**
 * Hook for managing description editing state and operations
 */

import * as React from "react"
import { usePinsStore } from "@/stores/use-pins-store"
import type { Pin } from "@prisma/client"

export function usePopupDescription(pin: Pin) {
  const [isEditing, setIsEditing] = React.useState(false)
  const [editedDesc, setEditedDesc] = React.useState(pin.description || "")
  const textareaRef = React.useRef<HTMLTextAreaElement>(null)

  const updatePinServer = usePinsStore((state) => state.updatePinServer)
  const updatePin = usePinsStore((state) => state.updatePin)

  // Keep local state in sync with pin prop when not editing
  React.useEffect(() => {
    if (!isEditing) {
      setEditedDesc(pin.description || "")
    }
  }, [pin.description, isEditing])

  // Focus textarea when editing starts
  React.useEffect(() => {
    if (isEditing && textareaRef.current) {
      textareaRef.current.focus()
    }
  }, [isEditing])

  const handleSave = async () => {
    const newDesc = editedDesc.trim()

    // Optimistic update
    updatePin(pin.id, { description: newDesc })
    setIsEditing(false)

    // Server sync
    try {
      await updatePinServer({ id: pin.id, description: newDesc })
    } catch (error) {
      console.error("Failed to update pin description:", error)
    }
  }

  const handleCancel = () => {
    setIsEditing(false)
    setEditedDesc(pin.description || "")
  }

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === "Enter" && e.ctrlKey) {
      e.preventDefault()
      handleSave()
    } else if (e.key === "Escape") {
      e.preventDefault()
      handleCancel()
    }
  }

  const startEditing = () => setIsEditing(true)

  return {
    isEditing,
    editedDesc,
    setEditedDesc,
    textareaRef,
    startEditing,
    handleSave,
    handleCancel,
    handleKeyDown,
  }
}

/**
 * Hook for managing icon selection state and operations
