import { MapPin, ChevronDown, Plus, Crosshair, FileText, Copy, Lock } from "lucide-react";

export interface PinActionDropdownProps {
  worldId: string;
  onAddPin: () => void;
  onTogglePlaceMode: () => void;
  isPlacingMode?: boolean;
  isLayerSelected?: boolean;
}

export function PinActionDropdown({
  worldId,
  onAddPin,
  onTogglePlaceMode,
  isPlacingMode = false,
  isLayerSelected = true,
}: PinActionDropdownProps) {
  const [isOpen, setIsOpen] = useState(false);
  const [showTooltip, setShowTooltip] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);

  // Close dropdown when clicking outside
  useEffect(() => {
    function handleClickOutside(event: MouseEvent) {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsOpen(false);
      }
    }

    // Close dropdown on Escape key
    function handleEscapeKey(event: KeyboardEvent) {
      if (event.key === "Escape") {
        setIsOpen(false);
      }
    }

    if (isOpen) {
      document.addEventListener("mousedown", handleClickOutside);
      document.addEventListener("keydown", handleEscapeKey);
    }

    return () => {
      document.removeEventListener("mousedown", handleClickOutside);
      document.removeEventListener("keydown", handleEscapeKey);
    };
  }, [isOpen]);

  const handleAddPin = () => {
    setIsOpen(false);
    onAddPin();
  };

  const handleTogglePlaceMode = () => {
    setIsOpen(false);
    onTogglePlaceMode();
  };

  const handleImportCSV = () => {
    setIsOpen(false);
    // TODO: Implement CSV import functionality
  };

  const handleDuplicateExisting = () => {
    setIsOpen(false);
    // TODO: Implement duplicate existing functionality
  };

  return (
    <div ref={dropdownRef} className="relative">
      {/* Trigger Button */}
      <div className="relative">
        <button
          onClick={() => isLayerSelected && setIsOpen(!isOpen)}
          onMouseEnter={() => !isLayerSelected && setShowTooltip(true)}
          onMouseLeave={() => setShowTooltip(false)}
          disabled={!isLayerSelected}
          className={`
            w-full flex items-center justify-center gap-2 px-3 py-2 rounded-sm
            transition-all duration-200
            bg-background-elevated border border-border-subtle
            ${isLayerSelected
              ? "hover:text-accent-gold hover:border-accent-gold/50 hover:bg-accent-gold/10 cursor-pointer"
              : "opacity-50 cursor-not-allowed"
            }
            ${isOpen ? "border-accent-gold/50 bg-accent-gold/10" : "text-text-secondary"}
          `}
          title={isLayerSelected ? "Add Pin" : undefined}
        >
          <MapPin className="w-4 h-4" />
          <span className="text-sm font-medium">Add Pin</span>
          {isLayerSelected && (
            <ChevronDown
              className={`
                w-4 h-4 transition-transform duration-200
                ${isOpen ? "rotate-180" : ""}
              `}
            />

"use client";

import { cn } from "@/lib/utils";
import { pinTypeConfig, type PinType } from "@/constants/pin-types";
import { useContextMenuPosition } from "../logic/use-context-menu-position";
import { PinMenuHeader } from "./pin-menu-header";
import { PinTypeMenuItem } from "./pin-type-menu-item";

export interface PinContextMenuProps {
  position: { x: number; y: number };
  onClose: () => void;
  onSelectPinType: (pinType: string, lat: number, lng: number) => void;
  coordinates: { lat: number; lng: number };
}

export function PinContextMenu({
  position,
  onClose,
  onSelectPinType,
  coordinates,
}: PinContextMenuProps) {
  const { menuRef, adjustedPosition } = useContextMenuPosition({
    position,
    onClose,
  });

  const handleSelectPinType = (pinType: string) => {
    onSelectPinType(pinType, coordinates.lat, coordinates.lng);
    onClose();
  };

  return (
    <div
      ref={menuRef}
      className={cn(
        "fixed z-50 min-w-[200px] rounded-sm border border-border-subtle",
        "bg-background-card shadow-xl p-1",
        "animate-in fade-in zoom-in-95 duration-200",
        "data-[state=open]:animate-in data-[state=closed]:animate-out",
        "data-[state=closed]:fade-out-0 data-[state=closed]:zoom-out-95"
      )}
      style={{
        left: adjustedPosition.x,
        top: adjustedPosition.y,
      }}
    >
      <PinMenuHeader />

      <div className="py-1">
        {Object.entries(pinTypeConfig).map(([type, config]) => (
          <PinTypeMenuItem
            key={type}
            type={type}
            config={config}
            onSelect={handleSelectPinType}
          />
        ))}
      </div>

      <div className="my-1 border-t border-border-subtle" />

      <button
        onClick={onClose}
        className={cn(
          "w-full flex items-center justify-center px-3 py-2 rounded-sm",
          "text-sm font-medium text-text-muted",
          "hover:text-text-primary hover:bg-background-elevated",
          "transition-all duration-150"
        )}
      >
        Cancel
      </button>
    </div>
  );
}

"use client";

import { useRef, useEffect, useState } from "react";
import { X } from "lucide-react";
import { useCreatePin } from "@/stores/use-pins-store";
import { usePinForm } from "../logic/use-pin-form";
import { PinForm } from "./pin-form";
import { useToast } from "@/hooks/use-toast";

interface FormLayer {
  id: string;
  name: string;
}

interface PinCreateFormProps {
  worldId: string;
  layers?: FormLayer[];
  initialLat?: number;
  initialLng?: number;
  initialLayerId?: string;
  initialPinType?: string;
  onSuccess?: () => void;
  onClose?: () => void;
}

export function PinCreateForm({
  worldId,
  layers = [],
  initialLat,
  initialLng,
  initialLayerId,
  initialPinType,
  onSuccess,
  onClose,
}: PinCreateFormProps) {
  const titleRef = useRef<HTMLInputElement>(null);
  const { toast, showToast } = useToast();

  const form = usePinForm({
    mode: "create",
    worldId,
    initialData: {
      latitude: initialLat || 0,
      longitude: initialLng || 0,
      layerId: initialLayerId || "",
      pinType: initialPinType as any,
    },
  });

  const createPinMutation = useCreatePin();
  const [isCreating, setIsCreating] = useState(false);

  // Auto-focus title field when form opens
  useEffect(() => {
    if (titleRef.current) {
      titleRef.current.focus();
    }
  }, []);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!form.validate()) {
      return;
    }

    setIsCreating(true);

    try {
      const data = form.getSubmitData();
      await createPinMutation(data as any);
      showToast("Pin created successfully!", "success");
      onSuccess?.();
    } catch (error) {
      if (error instanceof Error) {
        showToast(error.message, "error");
      } else {
        showToast("An unexpected error occurred", "error");
      }
    } finally {
      setIsCreating(false);
    }
  };

  return (
    <>
      {toast && (
        <div
          className={`fixed top-4 right-4 z-50 px-4 py-3 rounded-sm border shadow-lg ${
            toast.type === "success"
              ? "bg-status-success/20 border-status-success text-status-success"
              : "bg-status-error/20 border-status-error text-status-error"
          }`}
        >
          <div className="flex items-center gap-2">
            {toast.type === "success" ? (
              <svg className="w-5 h-5" fill="none">
                <path
                  d="M20 6L9 17l-5-5"
                  stroke="currentColor"

                  strokeWidth="2"
                  strokeLinecap="round"
                  strokeLinejoin="round"
                />
              </svg>
            ) : (
              <X className="w-5 h-5" />
            )}
            <span className="text-sm font-medium">{toast.message}</span>
          </div>
        </div>
      )}

      <PinForm
        formData={form.formData}
        errors={form.errors}
        onUpdateField={form.updateField as any}
        layers={layers}
        mode="create"
        showLayer={layers.length > 0}
        isSubmitting={isCreating}
        onSubmit={handleSubmit}
        onCancel={onClose}
        titleRef={titleRef}
      />
    </>
  );
}

"use client";

import { useState } from "react";
import { X } from "lucide-react";
import { useUpdatePinServer, useDeletePinServer } from "@/stores/use-pins-store";
import { usePinForm } from "../logic/use-pin-form";
import { PinForm } from "./pin-form";
import { useToast } from "@/hooks/use-toast";
import type { Pin } from "@/types/pin.type";

interface FormLayer {
  id: string;
  name: string;
}

interface PinEditFormProps {
  pin: Pin;
  layers?: FormLayer[];
  onSuccess?: () => void;
  onClose?: () => void;
}

export function PinEditForm({
  pin,
  layers = [],
  onSuccess,
  onClose,
}: PinEditFormProps) {
  const [showDeleteConfirm, setShowDeleteConfirm] = useState(false);
  const { toast, showToast } = useToast();

  const form = usePinForm({
    mode: "edit",
    worldId: pin.gameWorldId,
    pinId: pin.id,
    initialData: {
      title: pin.title,
      description: pin.description || "",
      pinType: pin.pinType as any,
      latitude: pin.latitude,
      longitude: pin.longitude,
      color: pin.color,
      size: pin.size,
      isVisible: pin.isVisible,
      properties: pin.properties ? JSON.stringify(pin.properties, null, 2) : "",
      icon: pin.icon || "",
      layerId: pin.layerId || "",
    },
  });

  const updatePinMutation = useUpdatePinServer();
  const deletePinMutation = useDeletePinServer();
  const [isUpdating, setIsUpdating] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!form.validate()) {
      return;
    }

    setIsUpdating(true);

    try {
      const data = form.getSubmitData();
      await updatePinMutation(data as any);
      showToast("Pin updated successfully!", "success");
      onSuccess?.();
    } catch (error) {
      if (error instanceof Error) {
        showToast(error.message, "error");
      } else {
        showToast("An unexpected error occurred", "error");
      }
    } finally {
      setIsUpdating(false);
    }
  };

  const handleDelete = async () => {
    if (showDeleteConfirm) {
      setIsDeleting(true);
      try {
        await deletePinMutation(pin.id);
        showToast("Pin deleted successfully!", "success");
        onSuccess?.();
      } catch (error) {
        if (error instanceof Error) {
          showToast(error.message, "error");
        } else {
          showToast("An unexpected error occurred", "error");
        }
      } finally {
        setIsDeleting(false);
      }
    } else {
      setShowDeleteConfirm(true);
    }
  };

  return (
    <>
      {toast && (
        <div
          className={`fixed top-4 right-4 z-50 px-4 py-3 rounded-sm border shadow-lg ${
            toast.type === "success"
              ? "bg-status-success/20 border-status-success text-status-success"
              : "bg-status-error/20 border-status-error text-status-error"
          }`}
        >
          <div className="flex items-center gap-2">
            {toast.type === "success" ? (
              <svg className="w-5 h-5" fill="none">
                <path
                  d="M20 6L9 17l-5-5"
                  stroke="currentColor"
                  strokeWidth="2"
                  strokeLinecap="round"
                  strokeLinejoin="round"
                />
              </svg>
            ) : (
              <X className="w-5 h-5" />
            )}
            <span className="text-sm font-medium">{toast.message}</span>
          </div>
        </div>
      )}

      {showDeleteConfirm && (
        <div className="mb-4 p-4 bg-red-50 border border-red-200 rounded-sm">
          <p className="text-sm text-red-900 font-medium mb-2">
            Are you sure you want to delete this pin?
          </p>
          <p className="text-xs text-red-700 mb-3">
            This action cannot be undone.
          </p>
          <div className="flex gap-2">
            <button
              type="button"
              onClick={() => setShowDeleteConfirm(false)}
              className="px-3 py-1.5 text-sm bg-white border border-red-300 rounded-md hover:bg-red-50 transition-colors"
            >
              Cancel
            </button>
            <button
              type="button"
              onClick={handleDelete}
              disabled={isDeleting}
              className="px-3 py-1.5 text-sm bg-red-600 text-white rounded-md hover:bg-red-700 transition-colors disabled:opacity-50"
            >
              {isDeleting ? "Deleting..." : "Yes, delete it"}
            </button>
          </div>
        </div>
      )}

      <PinForm
        formData={form.formData}
        errors={form.errors}
        onUpdateField={form.updateField as any}
        layers={layers}
        mode="edit"
        showLayer={layers.length > 0}
        isSubmitting={isUpdating}
        onSubmit={handleSubmit}
        onCancel={onClose}
        onDelete={showDeleteConfirm ? undefined : handleDelete}
      />
    </>
  );
}

import { FC } from "react";
import { X } from "lucide-react";
import { Button } from "@/components/ui/button";

interface FormActionsProps {
  mode: "create" | "edit";
  isSubmitting: boolean;
  onCancel?: () => void;
  onDelete?: () => void;
}

export const FormActions: FC<FormActionsProps> = ({
  mode,
  isSubmitting,
  onCancel,
  onDelete,
}) => (
  <div className="flex items-center gap-3 pt-4">
    <Button
      type="submit"
      disabled={isSubmitting}
      className="flex-1"
    >
      {isSubmitting
        ? mode === "create"
          ? "Creating..."
          : "Updating..."
        : mode === "create"
          ? "Create Pin"
          : "Update Pin"
      }
    </Button>

    {onCancel && (
      <Button
        type="button"
        variant="secondary"
        onClick={onCancel}
        disabled={isSubmitting}
      >
        Cancel
      </Button>
    )}

    {mode === "edit" && onDelete && (
      <Button
        type="button"
        variant="secondary"
        onClick={onDelete}
        disabled={isSubmitting}
        className="ml-auto bg-red-600 hover:bg-red-700 text-white"
      >
        <X className="w-4 h-4 mr-2" />
        Delete
      </Button>
    )}
  </div>
);

