export { useMarkerVisibility } from "./use-marker-visibility";
export { useMarkerStyling } from "./use-marker-styling";

import { MarkerIcon } from "./marker-icon";
import { MarkerSelectionRing } from "./marker-selection-ring";

interface MarkerContainerProps {
  /** Position X in pixels */
  x: number;
  /** Position Y in pixels */
  y: number;
  /** Z-index for rendering order */
  zIndex: number;
  /** Final size in pixels */
  size: number;
  /** Icon size in pixels */
  iconSize: number;
  /** Whether to use custom image or Lucide icon */
  isCustomImage: boolean;
  /** Icon name (Lucide or custom path) */
  iconName: string;
  /** Pin title for alt text */
  title: string;
  /** Background color */
  color: string;
  /** Opacity (0-1) */
  opacity: number;
  /** Box shadow CSS */
  boxShadow: string;
  /** Transform scale CSS */
  transformScale: string;
  /** Whether the pin is selected */
  isSelected: boolean;
  /** Whether the layer is locked */
  isLayerLocked: boolean;
  /** Whether the pin is being dragged */
  isDragging: boolean;
  /** Click handler */
  onClick: (e: React.MouseEvent) => void;
  /** Mouse down handler */
  onMouseDown: (e: React.MouseEvent) => void;
  /** Mouse enter handler */
  onMouseEnter: () => void;
  /** Mouse leave handler */
  onMouseLeave: () => void;
}

/**
 * MarkerContainer - Main marker container with icon and styling
 *
 * Renders the complete pin marker including:
 * - Selection ring (when selected)
 * - Main marker container with proper positioning
 * - Icon (custom image or Lucide)
 * - Interactive handlers (click, drag, hover)
 *
 * @example
 * ```tsx
 * <MarkerContainer
 *   x={position.x}
 *   y={position.y}
 *   zIndex={finalZIndex}
 *   size={finalSize}
 *   iconSize={iconSize}
 *   isCustomImage={isCustomImage}
 *   iconName={iconName}
 *   title={pin.title}
 *   color={pin.color}
 *   opacity={pin.opacity}
 *   boxShadow={boxShadow}
 *   transformScale={transformScale}
 *   isSelected={isPinSelected}
 *   isLayerLocked={isLayerLocked}
 *   isDragging={isDragging}
 *   onClick={handleClick}
 *   onMouseDown={handleMouseDown}
 *   onMouseEnter={handleMouseEnter}
 *   onMouseLeave={handleMouseLeave}
 * />
 * ```
 */
export function MarkerContainer({
  x,
  y,
  zIndex,
  size,
  iconSize,
  isCustomImage,
  iconName,
  title,
  color,
  opacity,
  boxShadow,
  transformScale,
  isSelected,
  isLayerLocked,
  isDragging,
  onClick,
  onMouseDown,
  onMouseEnter,
  onMouseLeave,
}: MarkerContainerProps) {
  const cursorClass = isDragging

    ? "cursor-grabbing"
    : isLayerLocked
      ? "cursor-not-allowed"
      : "cursor-pointer";

  return (
    <div
      className={`absolute ${cursorClass}`}
      style={{
        left: `${x}px`,
        top: `${y}px`,
        transform: "translate(-50%, -50%)",
        zIndex,
      }}
      onClick={onClick}
      onMouseDown={onMouseDown}
      onMouseEnter={onMouseEnter}
      onMouseLeave={onMouseLeave}
    >
      {/* Selection ring indicator */}
      <MarkerSelectionRing isSelected={isSelected} pinSize={size} />

      {/* Main marker */}
      <div
        className="flex items-center justify-center transition-all duration-150 overflow-hidden"
        style={{
          width: `${size}px`,
          height: `${size}px`,
          backgroundColor: isCustomImage ? "transparent" : color,
          borderRadius: "var(--radius-sm)",
          opacity,
          boxShadow,
          transform: transformScale,
        }}
      >
        <MarkerIcon
          iconName={iconName}
          title={title}
          iconSize={iconSize}
          isCustomImage={isCustomImage}
        />
      </div>
    </div>
  );
}

import * as LucideIcons from "lucide-react";

interface MarkerIconProps {
  /** Icon name (Lucide icon or custom image path) */
  iconName: string;
  /** Pin title for alt text */
  title: string;
  /** Calculated icon size in pixels */
  iconSize: number;
  /** Whether this is a custom uploaded image */
  isCustomImage: boolean;
}

/**
 * MarkerIcon - Renders pin icon (Lucide or custom image)
 *
 * Displays either a custom uploaded image or a Lucide icon component.
 * Handles icon scaling and styling.
 *
 * @example
 * ```tsx
 * <MarkerIcon
 *   iconName={pin.icon || pinConfig.icon}
 *   title={pin.title}
 *   iconSize={16 * transform.scale}
 *   isCustomImage={iconName?.startsWith("/")}
 * />
 * ```
 */
export function MarkerIcon({ iconName, title, iconSize, isCustomImage }: MarkerIconProps) {
  if (isCustomImage) {
    return (
      <img
        src={iconName}
        alt={title}
        className="w-full h-full object-contain"
        style={{ filter: "drop-shadow(0 1px 2px rgba(0,0,0,0.3))" }}
      />
    );
  }

  // Get Lucide icon component for non-custom icons
  const IconComponent = (LucideIcons as any)[iconName] || LucideIcons.MapPin;

  return (
    <IconComponent
      width={iconSize}
      height={iconSize}
      style={{ color: "white", opacity: 0.9 }}
    />
  );
}

interface MarkerSelectionRingProps {
  /** Whether this pin is currently selected */
  isSelected: boolean;
  /** Size of the pin marker (used to calculate ring size) */
  pinSize: number;
}

/**
 * MarkerSelectionRing - Animated selection indicator
 *
 * Displays a pulsing ring around selected pins to provide visual feedback.
 * Only rendered when the pin is selected.
 *
 * @example
 * ```tsx
 * <MarkerSelectionRing
 *   isSelected={isPinSelected}
 *   pinSize={finalSize}
 * />
 * ```
 */
export function MarkerSelectionRing({ isSelected, pinSize }: MarkerSelectionRingProps) {
  if (!isSelected) {
    return null;
  }

  return (
    <div
      className="absolute inset-0 rounded-full animate-pulse"
      style={{
        width: `${pinSize + 8}px`,
        height: `${pinSize + 8}px`,
        border: "2px solid rgba(59, 130, 246, 0.8)",
        transform: "translate(-50%, -50%)",
        left: "50%",
        top: "50%",
      }}
    />
  );
}

import type { Pin } from "@prisma/client";

interface UseMarkerStylingParams {
  pin: Pin & {
    layer?: {
      id: string;
      isVisible: boolean;
      zIndex: number;
    } | null;
  };
  transform: {
    scale: number;
    translateX: number;
    translateY: number;
  };
  isDragging: boolean;
  isPinSelected: boolean;
  isHovered: boolean;
}

/**
 * useMarkerStyling - Calculates style properties for pin markers
 *
 * Handles:
 * - Size constraints (min/max size based on zoom)
 * - Z-index calculation (layer-based + interaction boosts)
 * - Icon scaling (proportional to zoom with constraints)
 *
 * @returns Style properties and computed values
 */
export function useMarkerStyling({
  pin,
  transform,
  isDragging,
  isPinSelected,
  isHovered,
}: UseMarkerStylingParams) {
  // Ensure pins always render above the map image (z-index: 0)
  // Base z-index of 10 ensures pins are above the image but below UI overlays (z-index: 50+)
  const baseZIndex = 10;
  const layerZIndex = pin.layer?.zIndex ?? 0;
  const finalZIndex = isDragging || isPinSelected ? 9999 : baseZIndex + layerZIndex;

  // SIZE CONSTRAINTS: Apply min/max size to prevent microscopic or oversized pins
  const MIN_PIN_SIZE = 8;
  const MAX_PIN_SIZE = 128;
  const scaledSize = pin.size * transform.scale;
  const finalSize = Math.max(MIN_PIN_SIZE, Math.min(MAX_PIN_SIZE, scaledSize));

  // Icon size scales proportionally but with constraints
  const iconScale = Math.max(0.5, Math.min(3, transform.scale));
  const iconSize = 16 * iconScale;

  // Shadow calculation based on interaction state
  const getBoxShadow = () => {
    if (isDragging) {
      return "0 8px 20px rgba(0, 0, 0, 0.6)";
    }
    if (isPinSelected) {
      return "0 0 0 4px rgba(59, 130, 246, 0.3), 0 4px 12px rgba(0, 0, 0, 0.5)";
    }
    if (isHovered) {
      return "0 4px 12px rgba(0, 0, 0, 0.5)";
    }
    return "0 2px 8px rgba(0, 0, 0, 0.3)";
  };

  // Transform scale based on interaction state
  const getTransformScale = () => {
    if (isDragging) return "scale(1.2)";
    if (isPinSelected) return "scale(1.05)";
    if (isHovered) return "scale(1.1)";
    return "scale(1)";
  };

  return {
    finalZIndex,
    finalSize,
    iconSize,
    boxShadow: getBoxShadow(),
    transformScale: getTransformScale(),
  };
}

import type { Pin } from "@prisma/client";

interface UseMarkerVisibilityParams {
  pin: Pin & {
    layer?: {
      id: string;
      isVisible: boolean;
      zIndex: number;
    } | null;
  };
  transform: {
    scale: number;
    translateX: number;
    translateY: number;
  };
  isDragging: boolean;
  isHovered: boolean;
  isPinSelected: boolean;
}

/**
 * useMarkerVisibility - Calculates visibility conditions for pin markers
 *
 * Handles multiple visibility constraints:
 * - Explicit visibility flag (pin.isVisible)
 * - Zoom-based visibility (min/max zoom range)
 * - Size-based visibility (hide when too small)
 * - Interaction state (always show when dragging, hovered, or selected)
 *
 * @returns Whether the marker should be rendered
 */
export function useMarkerVisibility({
  pin,
  transform,
  isDragging,
  isHovered,
  isPinSelected,
}: UseMarkerVisibilityParams): boolean {
  // Single source of truth for visibility - already filtered at map-canvas level
  const isVisible = pin.isVisible;

  // ZOOM-BASED VISIBILITY: Hide pins that are too small to be useful
  const MIN_VISIBLE_SIZE = 6; // Minimum 6px to be visible/clickable
  const currentSize = pin.size * transform.scale;

  // ZOOM RANGE VISIBILITY: Check if current zoom is within pin's min/max zoom range
  const zoomPercentage = transform.scale * 100;
  const withinZoomRange =
    zoomPercentage >= (pin.minZoom ?? 0) && zoomPercentage <= (pin.maxZoom ?? 200);

  // INTERACTION STATE: Always show when interacting
  const isInteracting = isDragging || isHovered || isPinSelected;

  // Combine all visibility conditions
  return isVisible && (isInteracting || (withinZoomRange && currentSize >= MIN_VISIBLE_SIZE));
}

"use client";

import { memo } from "react";
import { useMapStore } from "@/stores/map-store";
import { usePinsStore } from "@/stores/use-pins-store";
import { getPinTypeConfig, type PinType } from "@/constants/pin-types";
import { usePinDrag } from "@/components/pins/logic/use-pin-drag";
import { usePinEvents } from "@/components/pins/logic/use-pin-events";
import { usePinPosition } from "@/components/pins/logic/use-pin-position";
import { eventManager } from "@/lib/event-manager";
import type { Pin } from "@prisma/client";
import { MarkerContainer } from "./pin-marker/marker-container";
import { useMarkerVisibility } from "./pin-marker/use-marker-visibility";
import { useMarkerStyling } from "./pin-marker/use-marker-styling";

interface PinMarkerProps {
  pin: Pin & {
    layer?: {
      id: string;
      isVisible: boolean;
      zIndex: number;
    } | null;
  };
  mapWidth: number;
  mapHeight: number;
  imageDimensions?: { width: number; height: number };
  transform: {
    scale: number;
    translateX: number;
    translateY: number;
  };
  onPinClick?: (pin: Pin) => void;
}

/**
 * PinMarker - Interactive map pin with drag-and-drop
 *
 * Orchestrates all pin marker functionality:
 * - Position calculation with layer offsets
 * - Drag-and-drop with optimistic updates
 * - Hover/selection state management
 * - Visibility based on zoom and size
 * - Custom or Lucide icon rendering
 *
 * Refactored from 430 lines to ~100 lines by extracting:
 * - UI components (MarkerContainer, MarkerIcon, MarkerSelectionRing)
 * - Logic hooks (usePinDrag, usePinEvents, usePinPosition)
 * - Utility hooks (useMarkerVisibility, useMarkerStyling)
 */
export function PinMarker({
  pin,
  mapWidth,
  mapHeight,
  imageDimensions,
  transform,
  onPinClick,
}: PinMarkerProps) {
  // Store access
  const layers = useMapStore((state) => state.layers);
  const selectPin = usePinsStore((state) => state.selectPin);
  const updatePin = usePinsStore((state) => state.updatePin);
  const selectedPinId = usePinsStore((state) => state.selectedPinId);

  const isPinSelected = selectedPinId === pin.id;

  // Calculate position with layer offsets
  const position = usePinPosition(pin, null, imageDimensions, transform, layers);

  // Get layer info for lock state
  const layer = pin.layerId ? layers.find((layer) => layer.id === pin.layerId) : null;
  const isLayerLocked = layer?.locked ?? false;

  // Drag functionality
  const { isDragging, dragPosition, hasMovedDuringDrag, handleMouseDown } = usePinDrag({
    pinId: pin.id,
    latitude: pin.latitude,
    longitude: pin.longitude,
    mapWidth: position.actualWidth || mapWidth,
    mapHeight: position.actualHeight || mapHeight,
    scale: transform.scale,
    isLocked: isLayerLocked,
    onSelectPin: selectPin,
    onUpdatePin: updatePin,
  });

  // Recalculate position with drag offset
  const dragAwarePosition = usePinPosition(pin, dragPosition, imageDimensions, transform, layers);

  // Event handling (hover, event capture)
  const { isHovered, handleMouseEnter, handleMouseLeave } = usePinEvents({
    pinId: pin.id,
    isDragging,
    isPinSelected,
  });

  // Capture events when pin is hovered or selected
  // NOTE: This is handled by usePinEvents internally via useEffect

  // Visibility calculation
  const shouldRender = useMarkerVisibility({

    pin,
    transform,
    isDragging,
    isHovered,
    isPinSelected,
  });

  if (!shouldRender) {
    return null;
  }

  // Icon configuration
  const pinConfig = getPinTypeConfig(pin.pinType as PinType);
  const iconName = pin.icon || pinConfig.icon;
  const isCustomImage = iconName?.startsWith("/");

  // Style calculations
  const { finalZIndex, finalSize, iconSize, boxShadow, transformScale } = useMarkerStyling({
    pin,
    transform,
    isDragging,
    isPinSelected,
    isHovered,
  });

  // Click handler (prevented if we just finished dragging)
  const handleClick = (e: React.MouseEvent) => {
    if (hasMovedDuringDrag) {
      return;
    }
    e.stopPropagation();
    selectPin(pin.id);
    onPinClick?.(pin);
  };

  return (
    <MarkerContainer
      x={dragAwarePosition.x}
      y={dragAwarePosition.y}
      zIndex={finalZIndex}
      size={finalSize}
      iconSize={iconSize}
      isCustomImage={isCustomImage}
      iconName={iconName}
      title={pin.title}
      color={pin.color}
      opacity={pin.opacity}
      boxShadow={boxShadow}
      transformScale={transformScale}
      isSelected={isPinSelected}
      isLayerLocked={isLayerLocked}
      isDragging={isDragging}
      onClick={handleClick}
      onMouseDown={handleMouseDown}
      onMouseEnter={handleMouseEnter}
      onMouseLeave={handleMouseLeave}
    />
  );
}

/**
 * MemoizedPinMarker - Performance-optimized pin marker with custom comparison
 *
 * PERFORMANCE STRATEGY:
 * ====================
 *
 * CRITICAL PROPS (trigger re-render):
 * - pin.id: Unique identifier - if changed, this is a different pin
 * - pin.isVisible: Visibility toggle - directly affects rendering
 * - pin.size: Affects visual size calculation
 * - pin.color: Affects visual appearance
 * - pin.icon: Affects which icon is displayed
 * - pin.latitude / pin.longitude: Position changes (drag operations)
 * - pin.layerId: Layer assignment affects z-index and offsets
 * - pin.opacity: Visual transparency
 * - pin.minZoom / pin.maxZoom: Zoom-based visibility
 * - transform.scale: Affects size and zoom-based visibility
 * - transform.translateX: Affects position when panning
 * - transform.translateY: Affects position when panning
 *
 * EXCLUDED PROPS (intentionally ignored):
 * - pin.title: Only used for alt text - doesn't affect rendering
 * - pin.description: Not used in marker rendering
 * - pin.createdAt / pin.updatedAt: Metadata only
 * - pin.worldId: Not used in rendering
 * - pin.userId: Not used in rendering
 * - layer properties: Computed from mapStore, not props
 * - imageDimensions: Cached in parent, rarely changes
 * - mapWidth / mapHeight: Only used for position calc, derived from imageDimensions
 *
 * WHY THIS MATTERS:
 * ================
 * Without memoization, EVERY pin re-renders on EVERY transform change (pan/zoom).
 * With 100 pins and 60fps, that's 6000 renders/second = major lag.
 *
 * With memoization, only pins affected by the change re-render:
 * - Pan/zoom: All pins re-render (transform changes) - EXPECTED
 * - Title edit: Only edited pin re-renders - OPTIMIZED
 * - Visibility toggle: Only toggled pin re-renders - OPTIMIZED
 * - Selection: Only selected pin updates - OPTIMIZED

 *
 * TESTING:
 * ========
 * 1. Open React DevTools Profiler
 * 2. Start profiling
 * 3. Pan/zoom map - expect all pins to re-render (transform change)
 * 4. Edit pin title - expect ONLY that pin to re-render
 * 5. Toggle pin visibility - expect ONLY that pin to re-render
 * 6. Select different pin - expect minimal re-renders
 *
 * EXPECTED PERFORMANCE:
 * ====================
 * - 60fps during pan/zoom with 100+ pins
 * - <16ms render time per frame
 * - No cascade re-renders on unrelated prop changes
 */
export const MemoizedPinMarker = memo(PinMarker, (prevProps, nextProps) => {
  // Compare critical props that affect rendering
  return (
    // Identity check - different pin entirely
    prevProps.pin.id === nextProps.pin.id &&
    // Visibility - directly affects whether we render
    prevProps.pin.isVisible === nextProps.pin.isVisible &&
    // Visual properties that affect appearance
    prevProps.pin.size === nextProps.pin.size &&
    prevProps.pin.color === nextProps.pin.color &&
    prevProps.pin.icon === nextProps.pin.icon &&
    prevProps.pin.opacity === nextProps.pin.opacity &&
    // Position - affects where the pin is rendered
    prevProps.pin.latitude === nextProps.pin.latitude &&
    prevProps.pin.longitude === nextProps.pin.longitude &&
    // Zoom range - affects visibility at different zoom levels
    prevProps.pin.minZoom === nextProps.pin.minZoom &&
    prevProps.pin.maxZoom === nextProps.pin.maxZoom &&
    // Layer assignment - affects z-index and offsets
    prevProps.pin.layerId === nextProps.pin.layerId &&
    // Transform - affects size, position, and visibility
    prevProps.transform.scale === nextProps.transform.scale &&
    prevProps.transform.translateX === nextProps.transform.translateX &&
    prevProps.transform.translateY === nextProps.transform.translateY
  );
});

MemoizedPinMarker.displayName = "MemoizedPinMarker";

