export function Toast({ toast, onHide }: ToastProps) {
  useEffect(() => {
    // Add animation class on mount
    const toastElement = document.getElementById("toast-notification");
    if (toastElement) {
      toastElement.classList.add("animate-in", "slide-in-from-top");
    }
  }, []);

  const Icon = toast.type === "success" ? Check : AlertCircle;

  return (
    <div
      id="toast-notification"
      className="fixed top-4 right-4 z-[9999] min-w-[300px] max-w-md animate-in fade-in duration-200"
    >
      <div
        className={`flex items-start gap-3 px-4 py-3 rounded-lg border shadow-lg ${
