        <button
          onClick={onHide}
          className={`flex-shrink-0 p-0.5 rounded hover:bg-black/10 transition-colors ${
            toast.type === "success" ? "text-emerald-300" : "text-rose-300"
          }`}
        >
          <X className="w-4 h-4" />
        </button>
      </div>
    </div>
  );
