"use client";

import { X } from "lucide-react";

interface FileUploadPreviewProps {
  previewUrl: string;
  fileName: string;
  fileSize: number;
  fileSizeUnit: "MB" | "KB";
  onRemove: (e: React.MouseEvent) => void;
  disabled?: boolean;
  previewClassName?: string;
}

export function FileUploadPreview({
  previewUrl,
  fileName,
  fileSize,
  fileSizeUnit,
  onRemove,
  disabled = false,
  previewClassName = "aspect-video w-full",
}: FileUploadPreviewProps) {
  const formatSize = () => {
    return fileSizeUnit === "MB"
      ? (fileSize / 1024 / 1024).toFixed(2)
      : (fileSize / 1024).toFixed(1);
  };

  return (
    <div className="space-y-3">
      <div className={`${previewClassName} overflow-hidden rounded-md bg-background-base`}>
        <img
          src={previewUrl}
          alt="Preview"
          className="w-full h-full object-contain"
        />
      </div>
      <div className="text-sm text-text-muted">
        <p className="font-medium text-text-secondary truncate">{fileName}</p>
        <p className="text-xs">
          {formatSize()} {fileSizeUnit}
        </p>
      </div>
      <button
        onClick={onRemove}
        disabled={disabled}
        className="text-sm text-accent-gold hover:text-accent-gold/80 disabled:opacity-50 disabled:cursor-not-allowed"
      >
        Choose different file
      </button>
    </div>
  );
}

"use client";

import { Loader2, Upload } from "lucide-react";
import { useRef } from "react";

interface FileUploadZoneProps {
  previewUrl: string | null;
  isUploading: boolean;
  accept: string;
  onFileSelect: (e: React.ChangeEvent<HTMLInputElement>) => void;
  onDragOver: (e: React.DragEvent) => void;
  onDrop: (e: React.DragEvent) => void;
  disabled?: boolean;
  previewClassName?: string;
  children?: React.ReactNode;
}

export function FileUploadZone({
  previewUrl,
  isUploading,
  accept,
  onFileSelect,
  onDragOver,
  onDrop,
  disabled = false,
  previewClassName = "aspect-video w-full",
  children,
}: FileUploadZoneProps) {
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleClick = () => {
    if (!disabled && !isUploading) {
      fileInputRef.current?.click();
    }
  };

  return (
    <div
      onDragOver={onDragOver}
      onDrop={onDrop}
      className={`relative border-2 border-dashed rounded-lg p-6 text-center transition-colors ${
        previewUrl
          ? "border-border-base bg-background-base"
          : "border-border-subtle hover:border-accent-gold hover:bg-background-hover cursor-pointer"
      }`}
      onClick={handleClick}
    >
      <input
        ref={fileInputRef}
        type="file"
        accept={accept}
        onChange={onFileSelect}
        disabled={disabled || isUploading}
        className="hidden"
      />

      {children || (
        <div className="space-y-2">
          <div className="w-12 h-12 mx-auto flex items-center justify-center rounded-full bg-background-base">
            {isUploading ? (
              <Loader2 className="w-6 h-6 text-accent-gold animate-spin" />
            ) : (
              <Upload className="w-6 h-6 text-text-muted" />
            )}
          </div>
          <div>
            <p className="text-sm text-text-secondary font-medium">
              Click to upload or drag and drop
            </p>
          </div>
        </div>
      )}
    </div>
  );
}

