import { useMapStore } from "@/stores/map-store";

/**
 * Prepares world state for autosave by combining store state with pin count
 * Returns a stable object reference for autosave comparison
 */
export function useAutosavePreparation(pinCount: number) {
  const layers = useMapStore((state) => state.layers);
  const grid = useMapStore((state) => state.grid);
  const snap = useMapStore((state) => state.snap);
  const scale = useMapStore((state) => state.scale);

  return {
    layers,
    grid,
    snap,
    scale,
    pinCount,
  };
}

import { useState, useCallback, useEffect } from "react";
import { useRouter } from "next/navigation";
import { useMapStore } from "@/stores/map-store";
import type { OptimizedWorldLayer } from "@/types/world.type";

interface UseLayersPanelProps {
  worldId?: string;
  worldLayers?: OptimizedWorldLayer[];
}

interface AddLayerData {
  name: string;
  visible: boolean;
  locked: boolean;
  opacity: number;
  zIndex: number;
  scale: number;
  offsetX: number;
  offsetY: number;
}

export function useLayersPanel({ worldId, worldLayers = [] }: UseLayersPanelProps) {
  const router = useRouter();

  // Store selectors
  const layers = useMapStore((state) => state.layers);
  const toggleLayerVisibility = useMapStore((state) => state.toggleLayerVisibility);
  const toggleLayerLock = useMapStore((state) => state.toggleLayerLock);
  const updateLayerOpacity = useMapStore((state) => state.updateLayerOpacity);
  const moveLayerUp = useMapStore((state) => state.moveLayerUp);
  const moveLayerDown = useMapStore((state) => state.moveLayerDown);
  const addLayer = useMapStore((state) => state.addLayer);
  const removeLayer = useMapStore((state) => state.removeLayer);

  // Local state
  const [showAddDialog, setShowAddDialog] = useState(false);
  const [newLayerName, setNewLayerName] = useState("");
  const [showDeleteConfirm, setShowDeleteConfirm] = useState<string | null>(null);
  const [showUploadDialog, setShowUploadDialog] = useState(false);

  // Computed
  const sortedLayers = [...layers].sort((a, b) => b.zIndex - a.zIndex);

  // Handlers
  const handleToggleVisibility = useCallback((layerId: string) => {
    toggleLayerVisibility(layerId);
  }, [toggleLayerVisibility]);

  const handleToggleLock = useCallback((layerId: string) => {
    toggleLayerLock(layerId);
  }, [toggleLayerLock]);

  const handleOpacityChange = useCallback((layerId: string, opacity: number) => {
    updateLayerOpacity(layerId, opacity);
  }, [updateLayerOpacity]);

  const handleMoveUp = useCallback((layerId: string) => {
    // Prevent moving the base map layer
    const layer = layers.find((l) => l.id === layerId);
    if (layer?.isBaseMap) return;
    moveLayerUp(layerId);
  }, [moveLayerUp, layers]);

  const handleMoveDown = useCallback((layerId: string) => {
    // Prevent moving the base map layer
    const layer = layers.find((l) => l.id === layerId);
    if (layer?.isBaseMap) return;
    moveLayerDown(layerId);
  }, [moveLayerDown, layers]);

  const handleAddLayer = useCallback(() => {
    if (newLayerName.trim()) {
      const maxZIndex = layers.length > 0 ? Math.max(...layers.map((l) => l.zIndex)) : 0;
      const layerData: AddLayerData = {
        name: newLayerName.trim(),
        visible: true,
        locked: false,
        opacity: 1,
        zIndex: maxZIndex + 1,
        scale: 1.0,
        offsetX: 0,
        offsetY: 0,
      };
      addLayer(layerData);
      setNewLayerName("");
      setShowAddDialog(false);
    }
  }, [newLayerName, layers, addLayer]);

  const handleDeleteLayer = useCallback((layerId: string) => {
    // Prevent deleting the base map layer
    const layer = layers.find((l) => l.id === layerId);
    if (layer?.isBaseMap) return;
    removeLayer(layerId);
    setShowDeleteConfirm(null);
  }, [removeLayer, layers]);

  const handleCancelDelete = useCallback(() => {
    setShowDeleteConfirm(null);
  }, []);

  const handleOpenAddDialog = useCallback(() => {
    setShowAddDialog(true);
  }, []);

  const handleCloseAddDialog = useCallback(() => {
    setShowAddDialog(false);
    setNewLayerName("");
  }, []);

  const handleStartDeleteConfirm = useCallback((layerId: string) => {
    setShowDeleteConfirm(layerId);
  }, []);

  const handleOpenUploadDialog = useCallback(() => {
    setShowUploadDialog(true);
  }, []);

  const handleCloseUploadDialog = useCallback(() => {
    setShowUploadDialog(false);
  }, []);

  const handleMapUploadSuccess = useCallback(
    (mapUrl: string) => {
      setShowUploadDialog(false);

      // Refresh the page to show the new map
      if (worldId) {
        router.refresh();
      }
    },
    [worldId, router]
  );

  // Keyboard shortcuts
  useEffect(() => {
    const handleEscape = (e: KeyboardEvent) => {
      if (e.key === "Escape" && showDeleteConfirm) {
        handleCancelDelete();
      }
    };

    if (showDeleteConfirm) {
      window.addEventListener("keydown", handleEscape);
      return () => window.removeEventListener("keydown", handleEscape);
    }
  }, [showDeleteConfirm, handleCancelDelete]);

  // Layer color utility
  const getLayerColor = useCallback((index: number) => {
    const colors = ["bg-accent-gold", "bg-blue-500", "bg-purple-500", "bg-emerald-500", "bg-rose-500"];
    return colors[index % colors.length];
  }, []);

  return {
    // State
    layers: sortedLayers,
    showAddDialog,
    newLayerName,
    showDeleteConfirm,
    showUploadDialog,

    // Actions
    setNewLayerName,
    handleToggleVisibility,
    handleToggleLock,
    handleOpacityChange,
    handleMoveUp,
    handleMoveDown,
    handleAddLayer,
    handleDeleteLayer,
    handleCancelDelete,
    handleOpenAddDialog,
    handleCloseAddDialog,
    handleStartDeleteConfirm,
    handleOpenUploadDialog,
    handleCloseUploadDialog,
    handleMapUploadSuccess,

    // Utilities
    getLayerColor,
  };
}

"use client";

import { useCallback } from "react";
import type { PinWithLayer } from "./use-pins-filtering";

interface UseMapHandlersProps {
  isCreatingPin: boolean;
  selectPin: (id: string | null) => void;
  clearSelection: () => void;
  stopCreating: () => void;
  startCreating: () => void;
}

interface MapHandlers {
  handlePinClick: (pin: PinWithLayer) => void;
  handlePopupClose: () => void;
  handleToggleCreatePin: () => void;
}

export function useMapHandlers({
  isCreatingPin,
  selectPin,
  clearSelection,
  stopCreating,
  startCreating,
}: UseMapHandlersProps): MapHandlers {
  const handlePinClick = useCallback(
    (pin: PinWithLayer) => {
      selectPin(pin.id);
    },
    [selectPin]
  );

  const handlePopupClose = useCallback(() => {
    clearSelection();
  }, [clearSelection]);

  const handleToggleCreatePin = useCallback(() => {
    if (isCreatingPin) {
      stopCreating();
    } else {
      selectPin(null);
      startCreating();
    }
  }, [isCreatingPin, stopCreating, selectPin, startCreating]);

  return {
    handlePinClick,
    handlePopupClose,
    handleToggleCreatePin,
  };
}

import { useState, useCallback, useRef, useEffect } from "react";

export interface ImageDimensions {
  width: number;
  height: number;
}

const DEFAULT_MAP_DIMENSIONS: ImageDimensions = {
  width: 1920,
  height: 1080,
};

export function useMapImage(mapImage?: string | null) {
  const [imageError, setImageError] = useState(false);
  const [imageLoaded, setImageLoaded] = useState(false);
  const [imageDimensions, setImageDimensions] = useState<ImageDimensions>({
    width: 0,
    height: 0,
  });
  const imageRef = useRef<HTMLImageElement>(null);
  const isMountedRef = useRef(true);

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      isMountedRef.current = false;
    };
  }, []);

  const handleImageLoad = useCallback(() => {
    if (!isMountedRef.current) return;

    setImageLoaded(true);
    setImageError(false);
    if (imageRef.current) {
      const dimensions = {
        width: imageRef.current.naturalWidth,
        height: imageRef.current.naturalHeight,
      };
      setImageDimensions(dimensions);
    }
  }, []);

  const handleImageError = useCallback(() => {
    if (!isMountedRef.current) return;

    setImageError(true);
    setImageLoaded(false);
  }, []);

  // Reset states when mapImage changes
  useEffect(() => {
    setImageLoaded(false);
    setImageError(false);
  }, [mapImage]);

  const shouldShowGrid = !mapImage || imageError || !imageLoaded;
  const dimensions = {
    width: imageDimensions.width || DEFAULT_MAP_DIMENSIONS.width,
    height: imageDimensions.height || DEFAULT_MAP_DIMENSIONS.height,
  };

  return {
    imageRef,
    imageError,
    imageLoaded,
    imageDimensions: dimensions,
    shouldShowGrid,
    handleImageLoad,
    handleImageError,
  };
}

import { useCallback, useEffect, useRef, useState } from "react";
import type { Pin } from "@prisma/client";
import { PinTypeEnum } from "@/types/pin.type";
import { eventManager } from "@/lib/event-manager";

export interface ContextMenuState {
  position: { x: number; y: number };
  coordinates: { lat: number; lng: number };
}

export interface UseMapInteractionsOptions {
  worldId?: string;
  selectedPin?: Pin | null;
  isCreatingPin?: boolean;
  transform: { scale: number; translateX: number; translateY: number };
  imageDimensions: { width: number; height: number };
  containerRef: React.RefObject<HTMLDivElement | null>;
  onCreatePin?: (data: {
    gameWorldId: string;
    title: string;
    pinType: PinTypeEnum;
    latitude: number;
    longitude: number;
    layerId?: string;
    isVisible: boolean;
  }) => void;
  onCloseContextMenu?: () => void;
  onStopCreating?: () => void;
  onSelectPin?: (pinId: string | null) => void;
  onClearSelection?: () => void;
}

export function useMapInteractions(options: UseMapInteractionsOptions) {
  const {
    worldId,
    selectedPin,
    isCreatingPin,
    transform,
    imageDimensions,
    containerRef,
    onCreatePin,
    onCloseContextMenu,
    onStopCreating,
    onSelectPin,
    onClearSelection,
  } = options;

  const [contextMenu, setContextMenu] = useState<ContextMenuState | null>(null);
  const isMountedRef = useRef(true);

  useEffect(() => {
    return () => {
      isMountedRef.current = false;
    };
  }, []);

  const handleClick = useCallback((e: React.MouseEvent) => {
    // Don't handle click if event was captured by another element
    if (eventManager.isCaptured()) {
      return;
    }

    // Close context menu on left click
    if (contextMenu) {
      setContextMenu(null);
      onCloseContextMenu?.();
      return;
    }

    // Deselect pin when clicking on empty space (left button only)
    if (e.button === 0 && selectedPin) {
      const rect = containerRef.current?.getBoundingClientRect();
      if (!rect) return;

      const x = e.clientX - rect.left;
      const y = e.clientY - rect.top;

      // Check if click is not on a pin marker
      // (Pin markers have their own click handlers)
      onClearSelection?.();
    }
  }, [contextMenu, selectedPin, containerRef, onCloseContextMenu, onClearSelection]);

  const handleContextMenu = useCallback((e: React.MouseEvent) => {
    e.preventDefault();

    const rect = containerRef.current?.getBoundingClientRect();
    if (!rect) return;

    // Get screen coordinates
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;

    // Guard against division by zero
    if (transform.scale <= 0) return;

    // Convert to map coordinates (0-1 range)
    const adjustedX = (x - transform.translateX) / transform.scale;
    const adjustedY = (y - transform.translateY) / transform.scale;

    const lng = adjustedX / imageDimensions.width;
    const lat = adjustedY / imageDimensions.height;

    if (!isMountedRef.current) return;

    setContextMenu({
      position: { x: e.clientX, y: e.clientY },
      coordinates: { lat, lng },
    });
  }, [containerRef, transform, imageDimensions]);

  const closeContextMenu = useCallback(() => {
    setContextMenu(null);
  }, []);

  const handleSelectPinType = useCallback((pinType: string, lat: number, lng: number) => {
    if (!worldId) {
      console.error("[handleSelectPinType] No worldId provided");
      return;
    }

    // Close context menu
    closeContextMenu();

    // Create pin immediately with default values
    onCreatePin?.({
      gameWorldId: worldId,
      title: `New ${pinType}`,
      pinType: pinType as PinTypeEnum,
      latitude: lat,
      longitude: lng,
      layerId: undefined, // Will be set by the selected layer from store
      isVisible: true,
    });
  }, [worldId, closeContextMenu, onCreatePin]);

  // Handle Escape key to cancel pin placement or close context menu
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (!isMountedRef.current) return;

      if (e.key === "Escape") {
        if (contextMenu) {
          setContextMenu(null);
        } else if (isCreatingPin) {
          onStopCreating?.();
        }
      }
    };

    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, [isCreatingPin, onStopCreating, contextMenu]);

  return {
    contextMenu,
    closeContextMenu,
    handleClick,
    handleContextMenu,
    handleSelectPinType,
  };
}

import { useState, useCallback, useEffect, useRef } from "react";

export interface Transform {
  scale: number;
  translateX: number;
  translateY: number;
}

export interface UseMapPanOptions {
  isCreatingPin?: boolean; // Disable drag when creating a pin
  onDragStart?: () => void;
  onDragEnd?: () => void;
}

export function useMapPan(options: UseMapPanOptions = {}) {
  const { isCreatingPin = false, onDragStart, onDragEnd } = options;
  const [transform, setTransform] = useState<Transform>({
    scale: 1,
    translateX: 0,
    translateY: 0,
  });
  const [isDragging, setIsDragging] = useState(false);
  const isDraggingRef = useRef(false);
  const dragStart = useRef({ x: 0, y: 0 });

  const handleMouseDown = useCallback((e: React.MouseEvent) => {
    // Only allow dragging with left mouse button, not when creating a pin
    if (e.button === 0 && !isCreatingPin && !isDraggingRef.current) {
      isDraggingRef.current = true;
      setIsDragging(true);
      dragStart.current = {
        x: e.clientX - transform.translateX,
        y: e.clientY - transform.translateY,
      };
      onDragStart?.();
    }
  }, [transform.translateX, transform.translateY, isCreatingPin, onDragStart]);

  // Attach window listeners once, check ref for drag state
  useEffect(() => {
    const handleMouseMove = (e: MouseEvent) => {
      if (isDraggingRef.current) {
        e.preventDefault();
        setTransform((prev) => ({
          ...prev,
          translateX: e.clientX - dragStart.current.x,
          translateY: e.clientY - dragStart.current.y,
        }));
      }
    };

    const handleMouseUp = (e: MouseEvent) => {
      if (isDraggingRef.current) {
        e.preventDefault();
        isDraggingRef.current = false;
        setIsDragging(false);
        onDragEnd?.();
      }
    };

    // Attach listeners to window for drag continuity
    window.addEventListener('mousemove', handleMouseMove, { passive: false });
    window.addEventListener('mouseup', handleMouseUp, { passive: false });

    return () => {
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('mouseup', handleMouseUp);
    };
  }, [onDragEnd]);

  const reset = useCallback(() => {
    setTransform({ scale: 1, translateX: 0, translateY: 0 });
  }, []);

  return {
    transform,
    isDragging,
    handleMouseDown,
    reset,
    setTransform,
  };
}

"use client";

import { useEffect, type RefObject } from "react";

const MIN_ZOOM = 0.1;
const MAX_ZOOM = 5.0;
const ZOOM_WHEEL_FACTOR_IN = 1.1;
const ZOOM_WHEEL_FACTOR_OUT = 0.9;

interface Transform {
  scale: number;
  translateX: number;
  translateY: number;
}

interface UseMapWheelProps {
  containerRef: RefObject<HTMLDivElement | null>;
  transform: Transform;
  setTransform: (update: (prev: Transform) => Transform) => void;
}

export function useMapWheel({
  containerRef,
  transform,
  setTransform,
}: UseMapWheelProps) {
  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;

    const handleWheelNonPassive = (e: WheelEvent) => {
      e.preventDefault();
      const delta = e.deltaY > 0 ? ZOOM_WHEEL_FACTOR_OUT : ZOOM_WHEEL_FACTOR_IN;
      const newScale = Math.min(
        Math.max(transform.scale * delta, MIN_ZOOM),
        MAX_ZOOM
      );

      setTransform((prev) => ({
        ...prev,
        scale: newScale,
      }));
    };

    container.addEventListener("wheel", handleWheelNonPassive, { passive: false });

    return () => {
      container.removeEventListener("wheel", handleWheelNonPassive);
    };
  }, [transform.scale, setTransform]);
}

import { useCallback } from "react";
import type { Transform } from "./use-map-pan";

const MIN_ZOOM = 0.1;
const MAX_ZOOM = 5.0;
const ZOOM_BUTTON_FACTOR = 1.2;
const ZOOM_WHEEL_FACTOR_IN = 1.1;
const ZOOM_WHEEL_FACTOR_OUT = 0.9;

export interface UseMapZoomOptions {
  onZoomChange?: (scale: number) => void;
}

export function useMapZoom(
  transform: Transform,
  setTransform: (updater: (prev: Transform) => Transform) => void,
  options: UseMapZoomOptions = {}
) {
  const handleWheel = useCallback((e: React.WheelEvent) => {
    e.preventDefault();
    const delta = e.deltaY > 0 ? ZOOM_WHEEL_FACTOR_OUT : ZOOM_WHEEL_FACTOR_IN;
    const newScale = Math.min(
      Math.max(transform.scale * delta, MIN_ZOOM),
      MAX_ZOOM
    );

    setTransform((prev) => ({
      ...prev,
      scale: newScale,
    }));

    options.onZoomChange?.(newScale);
  }, [transform.scale, setTransform, options]);

  const handleZoomIn = useCallback(() => {
    setTransform((prev) => ({
      ...prev,
      scale: Math.min(prev.scale * ZOOM_BUTTON_FACTOR, MAX_ZOOM),
    }));
  }, [setTransform]);

  const handleZoomOut = useCallback(() => {
    setTransform((prev) => ({
      ...prev,
      scale: Math.max(prev.scale / ZOOM_BUTTON_FACTOR, MIN_ZOOM),
    }));
  }, [setTransform]);

  return {
    handleWheel,
    handleZoomIn,
    handleZoomOut,
  };
}

import { useCallback } from "react";
import {
  usePinTypeFilters,
  useTogglePinTypeFilter,
  useShowAllPinTypes,
  useHideAllPinTypes,
  useVisiblePinTypes,
  useShowAllPinTypesValue,
} from "@/stores/use-pins-store";
import type { PinTypeEnum } from "@/types/pin.type";

/**
 * Hook for accessing pin filters state and actions
 * Provides a convenient interface for filtering pins by type
 *
 * @example
 * ```tsx
 * const { filters, showAll, toggleFilter, isTypeVisible } = usePinFilters();
 *
 * // Check if city pins are visible
 * if (isTypeVisible(PinTypeEnum.CITY)) {
 *   // Show city pins
 * }
 *
 * // Toggle a filter
 * toggleFilter(PinTypeEnum.DUNGEON);
 * ```
 */
export function usePinFilters() {
  const filters = usePinTypeFilters();
  const showAll = useShowAllPinTypesValue();
  const toggleFilter = useTogglePinTypeFilter();
  const showAllTypes = useShowAllPinTypes();
  const hideAllTypes = useHideAllPinTypes();
  const visibleTypes = useVisiblePinTypes();

  const isTypeVisible = (pinType: PinTypeEnum): boolean => {
    return filters[pinType] ?? true;
  };

  return {
    toggleFilter,
    setFilter: (pinType: PinTypeEnum, value: boolean) => {
      // This is handled by toggle, but we could add setPinTypeFilter if needed
      if (value !== filters[pinType]) {
        toggleFilter(pinType);
      }
    },
    showAllTypes,
    hideAllTypes,
    resetFilters: showAllTypes, // Reset = show all
    isTypeVisible,
    filters,
    showAll,
    visibleTypes,
  };
}

/**
 * Hook to check if a specific pin type is currently visible
 *
 * @example
 * ```tsx
 * const isCityVisible = useIsPinTypeVisible(PinTypeEnum.CITY);
 * ```
 */
export function useIsPinTypeVisible(pinType: PinTypeEnum): boolean {
  const filters = usePinTypeFilters();
  return filters[pinType] ?? true;
}

/**
 * Hook to filter an array of pins based on current filters
 *
 * @example
 * ```tsx
 * const filteredPins = useFilteredPins(allPins);
 * ```
 */
export function useFilteredPins<T extends { pinType: PinTypeEnum }>(pins: T[]): T[] {
  const visibleTypes = useVisiblePinTypes();

  return useCallback(() => {
    return pins.filter((pin) => visibleTypes.includes(pin.pinType));
  }, [pins, visibleTypes])();
}

/**
 * Hook to get the count of visible pin types
 * Useful for displaying "5 of 9 types visible"
 *
 * @example
 * ```tsx
 * const visibleCount = useVisiblePinTypesCount(); // 5
 * ```
 */
export function useVisiblePinTypesCount(): number {
  const visibleTypes = useVisiblePinTypes();
  return visibleTypes.length;
}

/**
 * Hook to check if any filters are active (some types hidden)
 *
 * @example
 * ```tsx
 * const hasActiveFilters = useHasActiveFilters(); // true if some types are hidden
 * ```
 */
export function useHasActiveFilters(): boolean {
  const showAll = useShowAllPinTypesValue();
  return !showAll;
}

