import { useMemo } from "react";
import type { Pin } from "@prisma/client";
import { usePinTypeFilters } from "@/stores/use-pins-store";

// Extended type for pins with layer relations (using Prisma types)
export interface PinWithLayer extends Pin {
  layer?: {
    id: string;
    name: string;
    isVisible: boolean;
    zIndex: number;
  } | null;
}

export interface UsePinsFilteringOptions {
  pins: PinWithLayer[];
  layers: Array<{ id: string; visible: boolean; zIndex: number }>;
}

export function usePinsFiltering({ pins, layers }: UsePinsFilteringOptions) {
  // Get active filters from store (Record<PinTypeEnum, boolean>)
  const pinFilters = usePinTypeFilters();

  const visiblePins = useMemo(() => {
    return pins
      .filter((pin) => {
        // Check pin visibility from DB
        if (!pin.isVisible) {
          return false;
        }

        // Check layer visibility from DB (if layer assigned)
        if (pin.layerId && pin.layer) {
          if (!pin.layer.isVisible) {
            return false;
          }
        }

        // Apply user-defined type filters
        // If the pin type is explicitly set to false in filters, hide it
        if (pinFilters[pin.pinType] === false) {
          return false;
        }

        // Pin is visible
        return true;
      })
      .sort((a, b) => {
        // Sort by layer zIndex
        const aLayer = layers.find((l) => l.id === a.layerId);
        const bLayer = layers.find((l) => l.id === b.layerId);
        const aZIndex = aLayer?.zIndex ?? 0;
        const bZIndex = bLayer?.zIndex ?? 0;
        return aZIndex - bZIndex;
      });
  }, [pins, layers, pinFilters]);

  return {
    visiblePins,
  };
}

import { useState, useEffect, useCallback } from "react";
import { useSelectedPin, useUpdatePin } from "@/stores/use-pins-store";
import { updatePin, uploadPinIcon } from "@/actions/pins";
import { useToast } from "@/hooks/use-toast";
import type { Pin } from "@prisma/client";

interface PinFormState {
  title: string;
  description: string;
  pinType: Pin["pinType"];
  icon: string | null;
  size: number;
  color: string;
  opacity: number;
  isVisible: boolean;
  minZoom: number;
  maxZoom: number;
}

export function usePropertiesPanel() {
  const selectedPin = useSelectedPin();
  const updatePinInStore = useUpdatePin();
  const { showToast } = useToast();

  const [formState, setFormState] = useState<PinFormState>({
    title: "",
    description: "",
    pinType: "CUSTOM",
    icon: null,
    size: 32,
    color: "#3b82f6",
    opacity: 1,
    isVisible: true,
    minZoom: 0,
    maxZoom: 200,
  });
  const [isUpdating, setIsUpdating] = useState(false);
  const [lastKnownGoodState, setLastKnownGoodState] = useState<PinFormState | null>(null);
  const [error, setError] = useState<string | null>(null);

  // Update form when pin selection changes
  useEffect(() => {
    if (selectedPin) {
      setFormState({
        title: selectedPin.title,
        description: selectedPin.description || "",
        pinType: selectedPin.pinType,
        icon: selectedPin.icon,
        size: selectedPin.size,
        color: selectedPin.color,
        opacity: selectedPin.opacity ?? 1,
        isVisible: selectedPin.isVisible,
        minZoom: selectedPin.minZoom ?? 0,
        maxZoom: selectedPin.maxZoom ?? 200,
      });
    }
  }, [selectedPin]);

  // Handle pin updates with optimistic updates
  const handleUpdatePin = useCallback(
    async <K extends keyof Pin>(field: K, value: Pin[K]) => {
      if (!selectedPin || isUpdating) return;

      setIsUpdating(true);
      setError(null);
      const previousValue = formState[field as keyof PinFormState];

      // Save last known good state before update
      setLastKnownGoodState(formState);

      try {
        // Optimistic update: Update local form state immediately
        setFormState((prev) => ({ ...prev, [field]: value }));

        // Optimistic update: Update Zustand store immediately
        updatePinInStore(selectedPin.id, { [field]: value } as Partial<Pin>);

        // Persist to database (fire-and-forget since Zustand is source of truth)
        await updatePin({
          id: selectedPin.id,
          [field]: value,
        });

        // Clear last known good state on success
        setLastKnownGoodState(null);
        showToast("Pin updated successfully", "success");
      } catch (err) {
        const errorMessage = err instanceof Error ? err.message : "Failed to update pin";

        // Check for concurrent edit conflict
        if (errorMessage.includes("concurrent") || errorMessage.includes("conflict")) {
          showToast("This pin was modified by another user. Please refresh.", "error");
        } else {
          showToast(`Failed to update pin: ${errorMessage}`, "error");
        }

        setError(errorMessage);

        // Rollback: Revert all updates on error
        setFormState((prev) => ({ ...prev, [field]: previousValue }));

        updatePinInStore(selectedPin.id, { [field]: previousValue } as Partial<Pin>);

        // Also rollback to last known good state if available
        if (lastKnownGoodState) {
          setFormState(lastKnownGoodState);
          updatePinInStore(selectedPin.id, lastKnownGoodState as Partial<Pin>);
        }
      } finally {
        setIsUpdating(false);
      }
    },
    [selectedPin, isUpdating, formState, updatePinInStore, showToast, lastKnownGoodState]
  );

  // Handle custom icon upload
  const handleIconUpload = useCallback(
    async (file: File) => {
      if (!selectedPin) throw new Error("No pin selected");

      setIsUpdating(true);
      setError(null);

      try {
        const formData = new FormData();
        formData.append("file", file);

        const result = await uploadPinIcon(selectedPin.id, formData);

        // Update local state
        setFormState((prev) => ({ ...prev, icon: result.pin.icon }));

        // Update Zustand store (source of truth)
        updatePinInStore(selectedPin.id, { icon: result.pin.icon });

        showToast("Icon uploaded successfully", "success");
      } catch (err) {
        const errorMessage = err instanceof Error ? err.message : "Failed to upload icon";
        showToast(`Failed to upload icon: ${errorMessage}`, "error");
        setError(errorMessage);
        throw err;
      } finally {
        setIsUpdating(false);
      }
    },
    [selectedPin, updatePinInStore, showToast]
  );

  // Retry failed update
  const retryUpdate = useCallback(() => {
    if (error && lastKnownGoodState) {
      setError(null);
      // Trigger a refetch by re-fetching from server action
      // Note: This will be handled by calling component
    }
  }, [error, lastKnownGoodState]);

  return {
    selectedPin,
    formState,
    isUpdating,
    error,
    handleUpdatePin,
    handleIconUpload,
    retryUpdate,
  };
}

import { useState, useRef, useCallback, useEffect } from "react";

export function useResizableSidebar(initialWidth = 320, minWidth = 200, maxWidth = 600) {
  const [width, setWidth] = useState(initialWidth);
  const [isCollapsed, setIsCollapsed] = useState(false);
  const [isResizing, setIsResizing] = useState(false);

  const startX = useRef(0);
  const startWidth = useRef(0);
  const currentWidth = useRef(initialWidth);
  const rafId = useRef<number | null>(null);
  const sidebarRef = useRef<HTMLDivElement>(null);

  const startResize = useCallback((e: React.MouseEvent) => {
    e.preventDefault();
    setIsResizing(true);
    startX.current = e.clientX;
    startWidth.current = currentWidth.current;
  }, []);

  const resize = useCallback(
    (e: MouseEvent) => {
      if (!isResizing) return;

      if (rafId.current !== null) {
        return;
      }

      rafId.current = requestAnimationFrame(() => {
        const deltaX = e.clientX - startX.current;
        const newWidth = Math.min(Math.max(startWidth.current + deltaX, minWidth), maxWidth);
        currentWidth.current = newWidth;

        if (sidebarRef.current) {
          sidebarRef.current.style.width = `${newWidth}px`;
        }

        rafId.current = null;
      });
    },
    [isResizing, minWidth, maxWidth]
  );

  const stopResize = useCallback(() => {
    if (!isResizing) return;

    setIsResizing(false);
    setWidth(currentWidth.current);

    if (rafId.current !== null) {
      cancelAnimationFrame(rafId.current);
      rafId.current = null;
    }
  }, [isResizing]);

  useEffect(() => {
    if (isResizing) {
      document.addEventListener("mousemove", resize, { passive: true });
      document.addEventListener("mouseup", stopResize);

      return () => {
        document.removeEventListener("mousemove", resize);
        document.removeEventListener("mouseup", stopResize);

        if (rafId.current !== null) {
          cancelAnimationFrame(rafId.current);
          rafId.current = null;
        }
      };
    }
  }, [isResizing, resize, stopResize]);

  const toggleCollapse = useCallback(() => {
    setIsCollapsed((prev) => !prev);
  }, []);

  return {
    width,
    isCollapsed,
    isResizing,
    startResize,
    toggleCollapse,
    sidebarRef,
  };
}

import { useEffect, useMemo } from "react";
import { useMapStore } from "@/stores/map-store";
import { useQuery } from "@tanstack/react-query";
import { getWorldById, getWorldWithData } from "@/actions/worlds";
import { CACHE_TIMES } from "@/components/providers/query-provider";
import type { OptimizedWorldLayer } from "@/types/world.type";
import type { OptimizedWorld } from "@/types/world.type";

/**
 * Initializes map layers from world data into Zustand store
 * Transforms OptimizedWorldLayer (DB schema) to UILayer (store schema)
 * Memoized to prevent unnecessary recalculations
 */
export function useWorldInitialization(worldLayers: OptimizedWorldLayer[] | null) {
  const setLayers = useMapStore((state) => state.setLayers);

  // Memoize layer transformation to prevent recalculation on every render
  const uiLayers = useMemo(() => {
    if (!worldLayers || worldLayers.length === 0) {
      return [];
    }

    return worldLayers.map((layer) => ({
      id: layer.id,
      name: layer.name,
      visible: layer.isVisible,
      locked: false,
      opacity: layer.opacity,
      zIndex: layer.zIndex,
      scale: 1.0,
      offsetX: 0,
      offsetY: 0,
    }));
  }, [worldLayers]);

  useEffect(() => {
    if (uiLayers.length > 0) {
      setLayers(uiLayers);
    }
  }, [uiLayers, setLayers]);
}

/**
 * Fetches world data using TanStack Query for non-blocking Client Component rendering
 * Provides cached world data with configurable stale time
 */
export function useWorld(worldId: string) {
  return useQuery<OptimizedWorld | null>({
    queryKey: ["world", worldId],
    queryFn: () => getWorldById(worldId),
    // World metadata rarely changes - use longer cache time
    staleTime: CACHE_TIMES.WORLD, // 5 minutes
    refetchOnMount: false,
    refetchOnWindowFocus: false,
    refetchOnReconnect: false,
    retry: 1,
  });
}

/**
 * Fetches world with all related data (layers + pins) in a single query
 * Optimized to eliminate multiple fetch requests and reduce load time
 * Use this for initial world load to get all data in ONE request
 * @param worldId - World ID to fetch
 * @returns World with pins data
 */
export function useWorldWithData(worldId: string) {
  return useQuery({
    queryKey: ["world-complete", worldId],
    queryFn: () => getWorldWithData(worldId),
    // Complete world data - cache for 1 minute
    staleTime: CACHE_TIMES.WORLD, // 5 minutes
    refetchOnMount: false,
    refetchOnWindowFocus: false,
    refetchOnReconnect: false,
    retry: 1,
  });
}

