        onChange={(e) => onNameChange(e.target.value)}
        placeholder="Layer name..."
        className="w-full px-2 py-1.5 text-sm bg-background-base border border-border-subtle rounded-sm focus:outline-none focus:border-accent-gold text-text-primary placeholder:text-text-muted"
        autoFocus
        onKeyDown={(e) => {
          if (e.key === "Enter") onAdd();
          if (e.key === "Escape") onCancel();
        }}
      />
      <div className="flex gap-2">
        <button
          onClick={onAdd}
          className="flex-1 px-2 py-1 text-xs bg-accent-gold text-background-base rounded-sm hover:bg-accent-gold/90 transition-colors"
        >
          Create
        </button>
        <button
          onClick={onCancel}
          className="flex-1 px-2 py-1 text-xs bg-background-base border border-border-subtle text-text-secondary rounded-sm hover:bg-background-elevated transition-colors"
        >
          Cancel
        </button>
      </div>
    </div>
  );
}

"use client";

import { type AutosaveStatus } from "@/hooks/use-autosave";

interface AutosaveIndicatorProps {
  status: AutosaveStatus;
}

function getStatusText(status: AutosaveStatus): string {
  switch (status) {
    case "unsaved":
      return "Unsaved changes";
    case "saving":
      return "Saving...";
    case "saved":
      return "All changes saved";
    case "error":
      return "Save failed";
    default:
      return "";
  }
}

export function AutosaveIndicator({ status }: AutosaveIndicatorProps) {
  if (status === "idle") {
    return null;
  }

  const statusText = getStatusText(status);

  const getIcon = () => {
    switch (status) {
      case "unsaved":
        return (
          <div
            className="h-2 w-2 rounded-full bg-amber-500"
            title={statusText}
          />
        );

      case "saving":
        return (
          <div
            className="h-3 w-3 animate-spin rounded-full border-2 border-blue-500 border-t-transparent"
            title={statusText}
          />
        );

      case "saved":
        return (
          <svg
            className="h-3 w-3 text-green-600"
            fill="none"
            stroke="currentColor"
            viewBox="0 0 24 24"
          >
            <path
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeWidth={3}
              d="M5 13l4 4L19 7"
            />
          </svg>
        );

      case "error":
        return (
          <svg
            className="h-3 w-3 text-red-600"
            fill="none"
            stroke="currentColor"
            viewBox="0 0 24 24"
          >
            <path
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeWidth={3}
              d="M6 18L18 6M6 6l12 12"
            />
          </svg>
        );

      default:
        return null;
    }
  };

  return <div title={statusText}>{getIcon()}</div>;
}

"use client";

import { useState, useCallback } from "react";
import { LayerHeader } from "./layer-header";
import { LayerProperties } from "./layer-properties";

interface BaseMapLayerItemProps {
  mapImage: string | null;
  isVisible: boolean;
  isLocked?: boolean;
  opacity: number;
  scale: number;
  onToggleVisibility: () => void;
  onOpacityChange: (opacity: number) => void;
  onScaleChange: (scale: number) => void;
  onUploadMap?: () => void;
}

export function BaseMapLayerItem({
  mapImage,
  isVisible,
  isLocked = true,
  opacity,
  scale,
  onToggleVisibility,
  onOpacityChange,
  onScaleChange,
  onUploadMap,
}: BaseMapLayerItemProps) {
  const [isExpanded, setIsExpanded] = useState(false);

  const handleToggleExpand = useCallback(() => {
    setIsExpanded((prev) => !prev);
  }, []);

  const handleOpacityChange = useCallback(
    (e: React.ChangeEvent<HTMLInputElement>) => {
      const newOpacity = parseInt(e.target.value) / 100;
      onOpacityChange(newOpacity);
    },
    [onOpacityChange]
  );

  const handleScaleChange = useCallback(
    (e: React.ChangeEvent<HTMLInputElement>) => {
      const newScale = parseInt(e.target.value) / 100;
      onScaleChange(newScale);
    },
    [onScaleChange]
  );

  const handleResetScale = useCallback(() => {
    onScaleChange(1.0);
  }, [onScaleChange]);

  const handleToggleVisibility = useCallback(
    (e: React.MouseEvent) => {
      e.stopPropagation();
      onToggleVisibility();
    },
    [onToggleVisibility]
  );

  const handleUploadMap = useCallback(
    (e: React.MouseEvent) => {
      e.stopPropagation();
      onUploadMap?.();
    },
    [onUploadMap]
  );

  return (
    <div className="group relative rounded-sm bg-background-elevated overflow-hidden">
      <LayerHeader
        mapImage={mapImage}
        isVisible={isVisible}
        isLocked={isLocked}
        isExpanded={isExpanded}
        onToggleExpand={handleToggleExpand}
        onToggleVisibility={handleToggleVisibility}
        onUploadMap={onUploadMap ? handleUploadMap : undefined}
      />

      {isExpanded && (
        <LayerProperties
          opacity={opacity}
          scale={scale}
          isVisible={isVisible}
          isLocked={isLocked}
          onOpacityChange={handleOpacityChange}
          onScaleChange={handleScaleChange}
          onResetScale={handleResetScale}
        />
      )}
    </div>
  );
}

