}: LayerPropertiesProps) {
  return (
    <div className="px-3 pb-3 space-y-3 animate-in fade-in slide-in-from-top-1 duration-200">
      {/* Opacity Control */}
      <SliderControl
        label="Opacity"
        value={opacity * 100}
        onChange={onOpacityChange}
        displayValue={`${Math.round(opacity * 100)}%`}
      />

      {/* Size Control */}
      <SliderControl
        label="Size"
        value={scale * 100}
        onChange={onScaleChange}
        min={50}
        max={200}
        step={5}
