import { PinsRenderer } from "../pins-renderer";
import { SelectedPinPopup } from "../selected-pin-popup";

interface MapPinsWrapperProps {
  baseMapVisible: boolean;
  visiblePins: PinWithLayer[];
  selectedPin: PinWithLayer | null;
  imageDimensions: { width: number; height: number } | null;
  layerScale: number;
  mapImage: string;
  transform: { translateX: number; translateY: number; scale: number };
  imageRef: React.RefObject<HTMLImageElement | HTMLDivElement | null>;
  onPinClick: (pin: PinWithLayer) => void;
  onPopupClose: () => void;
  onImageLoad: () => void;
  onImageError: () => void;
  showGrid: boolean;
  gridSize: number;
}

export function MapPinsWrapper({
  baseMapVisible,
  visiblePins,
  selectedPin,
  imageDimensions,
  layerScale,
  mapImage,
  transform,
  imageRef,
  onPinClick,
  onPopupClose,
  onImageLoad,
  onImageError,
  showGrid,
  gridSize,
}: MapPinsWrapperProps) {
  if (!imageDimensions) return null;

  const pinsRenderer = (
    <PinsRenderer
      pins={visiblePins}
      imageDimensions={imageDimensions}
      transform={transform}
