"use client";

import { useRef } from "react";
import { useGrid, useScale, useLayers, useSelectedLayerId, useBaseMapVisible, useMapStore } from "@/stores/map-store";
import {
  usePins,
  useCreatePin,
  useSelectedPin,
  useIsCreatingPin,
  usePinsStore,
} from "@/stores/use-pins-store";
import { PinContextMenu } from "@/components/pins/ui/pin-context-menu";
import { useMapPan } from "../logic/use-map-pan";
import { useMapZoom } from "../logic/use-map-zoom";
import { useMapImage } from "../logic/use-map-image";
import { useMapInteractions } from "../logic/use-map-interactions";
import { usePinsFiltering } from "../logic/use-pins-filtering";
import { useMapWheel } from "../logic/use-map-wheel";
import { useMapHandlers } from "../logic/use-map-handlers";
import { ZoomControls } from "./zoom-controls";
import { MapLayersIndicator } from "./map-layers-indicator";
import { PlacementIndicator } from "./placement-indicator";
import { MapContainer } from "./map-canvas/map-container";
import { MapTransformLayer } from "./map-canvas/map-transform-layer";
import { MapContent } from "./map-canvas/map-content";
import { MapPinsWrapper } from "./map-canvas/map-pins-wrapper";

const GRID_SIZE = 40;

export interface MapCanvasProps {
  mapImage?: string | null;
  worldId?: string;
}

export function MapCanvas({ mapImage, worldId }: MapCanvasProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const grid = useGrid();
  const scale = useScale();
  const layers = useLayers();
  const selectedLayerId = useSelectedLayerId();
  const baseMapVisible = useBaseMapVisible();
  const baseMapLayer = useMapStore((state) => state.layers.find((l) => l.isBaseMap));

  const pins = usePins();
  const createPin = useCreatePin();
  const selectedPin = useSelectedPin();
  const isCreatingPin = useIsCreatingPin();
  const selectPin = usePinsStore((state) => state.selectPin);
  const clearSelection = usePinsStore((state) => state.clearSelection);
  const stopCreating = usePinsStore((state) => state.stopCreating);
  const startCreating = usePinsStore((state) => state.startCreating);

  const {
    transform,
    isDragging,
    handleMouseDown,
    reset: resetTransform,
    setTransform,
  } = useMapPan({ isCreatingPin });

  const { handleZoomIn, handleZoomOut } = useMapZoom(transform, setTransform);

  useMapWheel({ containerRef, transform, setTransform });

  const {
    imageRef,
    imageError,
    imageLoaded,
    imageDimensions,
    shouldShowGrid,
    handleImageLoad,
    handleImageError,
  } = useMapImage(mapImage);

  const { visiblePins } = usePinsFiltering({ pins, layers });

  const {
    contextMenu,
    closeContextMenu,
    handleClick,
    handleContextMenu,
    handleSelectPinType,
  } = useMapInteractions({
    worldId,
    selectedPin,
    isCreatingPin,
    transform,
    imageDimensions,
    containerRef,
    onCreatePin: (data) => {
      createPin({
        ...data,
        layerId: selectedLayerId || undefined,
      });
    },
    onCloseContextMenu: () => {},
    onStopCreating: stopCreating,
    onSelectPin: selectPin,
    onClearSelection: clearSelection,
  });

  const { handlePinClick, handlePopupClose } = useMapHandlers({
    isCreatingPin,
    selectPin,
    clearSelection,
    stopCreating,
    startCreating,
  });

  const getGridSize = (): number => {
    const scaleRatio = parseInt(scale.split(":")[1]);
    return GRID_SIZE * (1000 / scaleRatio);
  };

  const visibleLayers = layers
    .filter((layer) => layer.visible)
    .sort((a, b) => a.zIndex - b.zIndex);

  const layerScale = baseMapLayer?.scale ?? 1;

  return (
    <MapContainer
      ref={containerRef}
      isCreatingPin={isCreatingPin}
      isDragging={isDragging}
      showContextMenu={!!contextMenu}
      onMouseDown={handleMouseDown}
      onClick={handleClick}
      onContextMenu={handleContextMenu}
    >
      <MapTransformLayer
        translateX={transform.translateX}
        translateY={transform.translateY}
        scale={transform.scale}
        isDragging={isDragging}
      >
        <MapContent mapImage={mapImage} imageError={imageError}>
          {() => (
            <>
              <MapPinsWrapper
                baseMapVisible={baseMapVisible}
                visiblePins={visiblePins}
                selectedPin={selectedPin ?? null}
                imageDimensions={imageDimensions}
                layerScale={layerScale}
                mapImage={mapImage!}
                transform={transform}
                imageRef={imageRef}
                onPinClick={handlePinClick}
                onPopupClose={handlePopupClose}
                onImageLoad={handleImageLoad}
                onImageError={handleImageError}
                showGrid={grid && imageLoaded}
                gridSize={getGridSize()}
              />

              {!baseMapVisible && selectedPin && imageDimensions && (
                <MapPinsWrapper
                  baseMapVisible={false}
                  visiblePins={visiblePins}
                  selectedPin={selectedPin ?? null}
                  imageDimensions={imageDimensions}
                  layerScale={layerScale}
                  mapImage={mapImage!}
                  transform={transform}
                  imageRef={imageRef}
                  onPinClick={handlePinClick}
                  onPopupClose={handlePopupClose}
                  onImageLoad={handleImageLoad}
                  onImageError={handleImageError}
                  showGrid={false}
                  gridSize={getGridSize()}
                />
              )}

              <MapLayersIndicator layers={visibleLayers} />
            </>
          )}
        </MapContent>
      </MapTransformLayer>

      <ZoomControls
        scale={transform.scale}
        onZoomIn={handleZoomIn}
        onZoomOut={handleZoomOut}
        onReset={resetTransform}
      />

      <PlacementIndicator show={isCreatingPin && !contextMenu} />

      {contextMenu && worldId && (
        <PinContextMenu
          position={contextMenu.position}
          coordinates={contextMenu.coordinates}
          onClose={closeContextMenu}
          onSelectPinType={handleSelectPinType}
        />
      )}
    </MapContainer>
  );

import type { FC } from "react";
import React from "react";

export interface MapImageProps {
  imageRef: React.RefObject<HTMLImageElement | HTMLDivElement | null>;
  mapImage: string;
  imageDimensions: { width: number; height: number };
  showGrid: boolean;
  gridSize: number;
  layerScale?: number; // Scale factor for layer content (0.5 - 2.0)
  onLoad: () => void;
  onError: () => void;
  children?: React.ReactNode;
}

export const MapImage: FC<MapImageProps> = ({
  imageRef,
  mapImage,
  imageDimensions,
  showGrid,
  gridSize,
  layerScale = 1,
  onLoad,
  onError,
  children,
}) => {
  const { width, height } = imageDimensions;

  // Apply layer scale to dimensions instead of CSS transform
  const scaledWidth = width * layerScale;
  const scaledHeight = height * layerScale;

  return (
    <div
      className="relative"
      style={{
        width: scaledWidth > 0 ? scaledWidth : "100%",
        height: scaledHeight > 0 ? scaledHeight : "100%",
      }}
    >
      <img
        ref={imageRef as any}
        src={mapImage}
        alt="World map"
        className="max-w-none"
        style={{
          width: "100%",
          height: "100%",
          objectFit: "contain",
        }}
        onLoad={onLoad}
        onError={onError}
      />

      {showGrid && (
        <svg
          className="absolute top-0 left-0 pointer-events-none"
          style={{
            width: scaledWidth || "100%",
            height: scaledHeight || "100%",
            zIndex: 5,
          }}
          viewBox={`0 0 ${scaledWidth || 1920} ${scaledHeight || 1080}`}
          preserveAspectRatio="none"
        >
          <defs>
            <pattern
              id={`grid-${gridSize}`}
              width={gridSize * layerScale}
              height={gridSize * layerScale}
              patternUnits="userSpaceOnUse"
            >
              <path
                d={`M ${gridSize * layerScale} 0 L 0 0 0 ${gridSize * layerScale}`}
                fill="none"
                stroke="rgba(212, 175, 55, 0.2)"
                strokeWidth="1"
              />
            </pattern>
          </defs>
          <rect width="100%" height="100%" fill={`url(#grid-${gridSize})`} />
        </svg>
      )}

      {/* Pass ORIGINAL dimensions to children (pins need this for correct positioning) */}
      {React.Children.map(children, (child) => {
        if (React.isValidElement(child)) {
          return React.cloneElement(child, {
            imageDimensions: { width, height },
          } as any);
        }
        return child;
      })}
    </div>
  );
};

import { FC } from "react";

export interface Layer {
  id: string;
  name: string;
  visible: boolean;
  opacity: number;
  zIndex: number;
  locked: boolean;
}

export interface MapLayersIndicatorProps {
  layers: Layer[];
}

export const MapLayersIndicator: FC<MapLayersIndicatorProps> = ({ layers }) => {
  if (layers.length === 0) return null;

  return (
    <div
      className="absolute top-4 right-4 flex flex-col gap-2 pointer-events-none"
      style={{ opacity: 0.8 }}
    >
      {layers.map((layer) => (
        <div
          key={layer.id}
          className="px-3 py-1.5 rounded-sm bg-background-elevated/90 border border-border-subtle text-xs text-text-secondary backdrop-blur-sm"
          style={{
            opacity: layer.opacity,
            zIndex: layer.zIndex,
          }}
        >
          {layer.name}
          {layer.locked && (
