/**
 * Centralized Event Management System
 *
 * Provides a unified way to handle UI interactions with proper event bubbling control.
 * Prevents event conflicts between overlapping UI elements (popups, panels, etc.)
 *
 * @module event-manager
 */

export type InteractiveElement =
  | "map-canvas"
  | "pin-marker"
  | "pin-popup"
  | "sidebar"
  | "zoom-controls"
  | "context-menu";

export type InteractionMode =
  | "idle"
  | "dragging-map"
  | "dragging-pin"
  | "creating-pin"
  | "inspecting-pin";

interface EventState {
  /** Current mode of interaction */
  mode: InteractionMode;

  /** Element that captured the last event */
  capturedBy: InteractiveElement | null;

  /** Elements that should receive events (whitelist) */
  activeElements: Set<InteractiveElement>;

  /** Prevents deselection during interaction */
  isInteracting: boolean;
}

class EventManager {
  private state: EventState = {
    mode: "idle",
    capturedBy: null,
    activeElements: new Set(),
    isInteracting: false,
  };

  private listeners: Map<string, Set<() => void>> = new Map();

  /**
   * Capture an event for a specific element
   * @param element - The element capturing the event
   * @returns Cleanup function to release capture
   */
  capture(element: InteractiveElement): () => void {
    this.state.capturedBy = element;
    this.state.isInteracting = true;

    // Notify listeners
    this.notify("capture", element);

    // Return cleanup function
    return () => {
      if (this.state.capturedBy === element) {
        this.state.capturedBy = null;
        this.state.isInteracting = false;
        this.notify("release", element);
      }
    };
  }

  /**
   * Check if an event was captured by a specific element
   */
  isCapturedBy(element: InteractiveElement): boolean {
    return this.state.capturedBy === element;
  }

  /**
   * Check if any element has captured the event
   */
  isCaptured(): boolean {
    return this.state.capturedBy !== null;
  }

  /**
   * Set the current interaction mode
   */
  setMode(mode: InteractionMode): void {
    const previous = this.state.mode;
    this.state.mode = mode;
    this.notify("mode-change", { previous, current: mode });
  }

  /**
   * Get current interaction mode
   */
  getMode(): InteractionMode {
    return this.state.mode;
  }

  /**
   * Register an active element (should receive events)
   */
  activateElement(element: InteractiveElement): () => void {
    this.state.activeElements.add(element);

    return () => {
      this.state.activeElements.delete(element);
    };
  }

  /**
   * Check if an element is active
   */
  isElementActive(element: InteractiveElement): boolean {
    return this.state.activeElements.has(element);
  }

  /**
   * Check if we're currently interacting
   */
  isInteracting(): boolean {
    return this.state.isInteracting;
  }

  /**
   * Subscribe to event manager events
   */
  on(event: string, callback: () => void): () => void {
    if (!this.listeners.has(event)) {
      this.listeners.set(event, new Set());
    }

    this.listeners.get(event)!.add(callback);

    // Return cleanup function
    return () => {
      const callbacks = this.listeners.get(event);
      if (callbacks) {
        callbacks.delete(callback);
      }
    };
  }

  /**
   * Notify all listeners of an event
   */
  private notify(event: string, data?: unknown): void {
    const callbacks = this.listeners.get(event);
    if (callbacks) {
      callbacks.forEach((cb) => cb());
    }
  }

  /**
   * Reset all state (useful for testing/cleanup)
   */
  reset(): void {
    this.state = {
      mode: "idle",
      capturedBy: null,
      activeElements: new Set(),
      isInteracting: false,
    };
  }

  /**
   * Get current state (read-only)
   */
  getState(): Readonly<EventState> {
    return { ...this.state };
  }
}

// Singleton instance
export const eventManager = new EventManager();

/**
 * React hook for event management
 */
export function useEventManager() {
  return {
    capture: eventManager.capture.bind(eventManager),
    isCapturedBy: eventManager.isCapturedBy.bind(eventManager),
    isCaptured: eventManager.isCaptured.bind(eventManager),
    setMode: eventManager.setMode.bind(eventManager),
    getMode: eventManager.getMode.bind(eventManager),
    activateElement: eventManager.activateElement.bind(eventManager),
    isElementActive: eventManager.isElementActive.bind(eventManager),
    isInteracting: eventManager.isInteracting.bind(eventManager),
    on: eventManager.on.bind(eventManager),
  };
}

/**
 * Higher-order component props for event handling
 */
export interface WithEventCaptureProps {
  onCaptureStart?: () => void;
  onCaptureEnd?: () => void;

}

/**
 * Utility to stop event propagation safely
 */
export function stopPropagation(event: React.MouseEvent | MouseEvent): void {
  event.stopPropagation();
  event.preventDefault();
}

/**
 * Check if click should be allowed based on event manager state
 */
export function shouldAllowClick(
  event: React.MouseEvent,
  currentElement: InteractiveElement
): boolean {
  // If nothing captured, allow
  if (!eventManager.isCaptured()) {
    return true;
  }

  // If current element captured, allow
  if (eventManager.isCapturedBy(currentElement)) {
    return true;
  }

  // Otherwise, block
  return false;
}

/**
 * Performance testing utilities for validating MemoizedPinMarker
 *
 * Usage:
 * 1. Import in your component
 * 2. Wrap component with <PerformanceMonitor>
 * 3. Check console for render counts
 *
 * Example:
 * ```tsx
 * import { PerformanceMonitor, useRenderCount } from '@/lib/performance-test-utils'
 *
 * function MyComponent() {
 *   const renders = useRenderCount('MyComponent')
 *   return <div>Renders: {renders}</div>
 * }
 */
'use client';

import { useEffect, useRef, useState } from 'react';

/**
 * Hook to track render counts for a component
 * Useful for verifying memo optimization is working
 *
 * @param componentName - Name of component for logging
 * @returns Current render count
 */
export function useRenderCount(componentName: string): number {
  const rendersRef = useRef(0);
  const [, forceUpdate] = useState({});

  rendersRef.current += 1;

  useEffect(() => {
    if (process.env.NODE_ENV === 'development') {
      console.log(
        `[Performance] ${componentName} rendered (count: ${rendersRef.current})`
      );
    }
  });

  return rendersRef.current;
}

/**
 * Hook to track why a component re-rendered
 * Helps identify which prop changes caused re-render
 *
 * @param componentName - Name of component for logging
 * @param props - Current props to track
 */
export function useRenderTracker<T extends Record<string, any>>(
  componentName: string,
  props: T
): void {
  const prevPropsRef = useRef<T>(props);

  useEffect(() => {
    if (process.env.NODE_ENV !== 'development') return;

    const changedProps: string[] = [];
    const prevProps = prevPropsRef.current;

    for (const key in props) {
      if (props[key] !== prevProps[key]) {
        changedProps.push(key);
      }
    }

    if (changedProps.length > 0) {
      console.log(
        `[Performance] ${componentName} re-rendered due to changed props:`,
        changedProps
      );
    }

    prevPropsRef.current = props;
  });
}

/**
 * Performance boundary wrapper
 * Measures render time for children
 */
export function PerformanceMonitor({
  name,
  children,
  logThreshold = 16, // Log if render takes >16ms (60fps threshold)
}: {
  name: string;
  children: React.ReactNode;
  logThreshold?: number;
}) {
  const startTimeRef = useRef<number>(0);

  if (process.env.NODE_ENV === 'development') {
    startTimeRef.current = performance.now();
  }

  useEffect(() => {
    if (process.env.NODE_ENV !== 'development') return;

    const endTime = performance.now();
    const renderTime = endTime - startTimeRef.current;

    if (renderTime > logThreshold) {
      console.warn(
        `[Performance] Slow render detected in ${name}: ${renderTime.toFixed(2)}ms (threshold: ${logThreshold}ms)`
      );
    }
  });

  return <>{children}</>;
}

/**
 * FPS counter component
 * Displays real-time frame rate during interactions
 */
export function FPSCounter() {
  const [fps, setFps] = useState(60);
  const framesRef = useRef(0);
  const lastTimeRef = useRef(performance.now());

  useEffect(() => {
    if (process.env.NODE_ENV !== 'development') return;

    let rafId: number;

    function updateFPS() {
      const now = performance.now();
      framesRef.current++;

      if (now >= lastTimeRef.current + 1000) {
        setFps(Math.round((framesRef.current * 1000) / (now - lastTimeRef.current)));
        framesRef.current = 0;
        lastTimeRef.current = now;
      }

      rafId = requestAnimationFrame(updateFPS);
    }

    rafId = requestAnimationFrame(updateFPS);

    return () => cancelAnimationFrame(rafId);
  }, []);

  if (process.env.NODE_ENV !== 'development') {
    return null;
  }

  return (
    <div
      style={{
        position: 'fixed',
        bottom: 10,
        right: 10,
        background: 'rgba(0, 0, 0, 0.8)',
        color: fps >= 55 ? '#4ade80' : fps >= 30 ? '#fbbf24' : '#ef4444',
        padding: '8px 12px',
        borderRadius: '6px',
        fontFamily: 'monospace',
        fontSize: '14px',
        fontWeight: 'bold',
        zIndex: 9999,
        pointerEvents: 'none',
      }}
    >
      {fps} FPS
    </div>
  );
}

/**
 * Log performance metrics for a batch operation
 * Useful for testing bulk operations like loading 100 pins
 */
export class PerformanceLogger {
  private startTime: number;
  private markers: Map<string, number>;

  constructor(operation: string) {
    this.startTime = performance.now();
    this.markers = new Map();

    if (process.env.NODE_ENV === 'development') {
      console.log(`[Performance] Started operation: ${operation}`);
    }
  }

  /**
   * Mark a checkpoint within the operation
   */
  mark(markerName: string): void {
    const time = performance.now();
    this.markers.set(markerName, time - this.startTime);

    if (process.env.NODE_ENV === 'development') {
      console.log(

        `[Performance] Checkpoint "${markerName}": ${(time - this.startTime).toFixed(2)}ms`
      );
    }
  }

  /**
   * End the operation and log summary
   */
  end(): void {
    const totalTime = performance.now() - this.startTime;

    if (process.env.NODE_ENV === 'development') {
      console.log(`[Performance] Operation completed in ${totalTime.toFixed(2)}ms`);

      if (this.markers.size > 0) {
        console.table(
          Array.from(this.markers.entries()).map(([name, time]) => ({
            Checkpoint: name,
            'Time (ms)': time.toFixed(2),
            '% of Total': ((time / totalTime) * 100).toFixed(1),
          }))
        );
      }
    }
  }
}

/**
 * Utility to measure render count changes during an operation
 *
 * Example:
 * ```tsx
 * const { getRenderCounts, compareRenderCounts } = useRenderTracker()
 *
 * // Before operation
 * const before = getRenderCounts()
 *
 * // Perform operation
 * await someAsyncOperation()
 *
 * // After operation
 * const report = compareRenderCounts(before)
 * console.log(report)
 * ```
 */
export function usePerformanceTracker() {
  const [renderCounts, setRenderCounts] = useState<Record<string, number>>({});

  const getRenderCounts = () => ({ ...renderCounts });

  const updateRenderCount = (componentName: string) => {
    setRenderCounts((prev) => ({
      ...prev,
      [componentName]: (prev[componentName] || 0) + 1,
    }));
  };

  const compareRenderCounts = (before: Record<string, number>) => {
    const after = renderCounts;
    const report: Record<string, { before: number; after: number; delta: number }> = {};

    const allKeys = new Set([...Object.keys(before), ...Object.keys(after)]);

    allKeys.forEach((key) => {
      const beforeCount = before[key] || 0;
      const afterCount = after[key] || 0;
      report[key] = {
        before: beforeCount,
        after: afterCount,
        delta: afterCount - beforeCount,
      };
    });

    return report;
  };

  return {
    renderCounts,
    updateRenderCount,
    getRenderCounts,
    compareRenderCounts,
  };
}

/**
 * Development-mode performance testing helper
 * Wrap any function to measure its execution time
 */
export function measurePerformance<T extends (...args: any[]) => any>(
  fn: T,
  name: string = fn.name
): T {
  if (process.env.NODE_ENV !== 'development') {
    return fn;
  }

  return ((...args: any[]) => {
    const start = performance.now();
    const result = fn(...args);
    const end = performance.now();

    console.log(`[Performance] ${name} took ${(end - start).toFixed(2)}ms`);

    return result;
  }) as T;
}

import { PrismaClient } from "@prisma/client";
import { Pool } from "pg";
import { PrismaPg } from "@prisma/adapter-pg";

const globalForPrisma = globalThis as unknown as {
  prisma: PrismaClient | undefined;
};

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
});
const adapter = new PrismaPg(pool);

export const prisma = globalForPrisma.prisma ?? new PrismaClient({ adapter });

if (process.env.NODE_ENV !== "production") globalForPrisma.prisma = prisma;

import { type ClassValue, clsx } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

import { create } from "zustand";
import { persist } from "zustand/middleware";
import type { MapLayer } from "@/types/world.type";

const SCALE_OPTIONS = ["1:1000", "1:500", "1:100"] as const;
type ScaleOption = (typeof SCALE_OPTIONS)[number];

interface Layer {
  id: string;
  name: string;
  visible: boolean;
  opacity: number;
  zIndex: number;
  locked: boolean;
  isBaseMap?: boolean; // Special flag for base map layer
  scale: number; // Visual scale of layer content (0.5 - 2.0)
  offsetX: number; // Pixel offset from top-left (X axis)
  offsetY: number; // Pixel offset from top-left (Y axis)
}

interface MapState {
  grid: boolean;
  snap: boolean;
  scale: ScaleOption;
  layers: Layer[];
  selectedLayerId: string | null;

  // Computed values (memoized to prevent infinite loops)
  visibleLayerIds: string[];
  activeLayerIds: string[];
  baseMapVisible: boolean;

  // Layer actions
  setGrid: (value: boolean) => void;
  setSnap: (value: boolean) => void;
  setScale: (value: ScaleOption) => void;
  setLayers: (layers: Layer[]) => void;
  setSelectedLayerId: (layerId: string | null) => void;

  // Layer CRUD
  toggleLayerVisibility: (layerId: string) => void;
  toggleLayerLock: (layerId: string) => void;
  updateLayerOpacity: (layerId: string, opacity: number) => void;
  updateLayerZIndex: (layerId: string, zIndex: number) => void;
  updateLayerScale: (layerId: string, scale: number) => void;
  updateLayerPosition: (layerId: string, offsetX: number, offsetY: number) => void;
  addLayer: (layer: Omit<Layer, "id">) => void;
  removeLayer: (layerId: string) => void;
  moveLayerUp: (layerId: string) => void;
  moveLayerDown: (layerId: string) => void;

  // Base map layer actions
  toggleBaseMapVisibility: () => void;

  reset: () => void;
}

const initialState = {
  grid: false,
  snap: false,
  scale: "1:1000" as ScaleOption,
  layers: [
    {
      id: "base-map",
      name: "Base Map",
      visible: true,
      opacity: 1,
      zIndex: 0,
      locked: true,
      isBaseMap: true,
      scale: 1.0,
      offsetX: 0,
      offsetY: 0,
    },
  ] as Layer[],
  selectedLayerId: null as string | null,
  visibleLayerIds: ["base-map"],
  activeLayerIds: [] as string[],
  baseMapVisible: true,
};

export const useMapStore = create<MapState>()(
  persist(
    (set, get) => ({
      ...initialState,

      setGrid: (value) => set({ grid: value }),

      setSnap: (value) => set({ snap: value }),

      setScale: (value) => set({ scale: value }),

      setLayers: (layers) =>
        set(() => {
          const newVisibleLayerIds = layers
            .filter((l) => l.visible)
            .map((l) => l.id);
          const newActiveLayerIds = layers
            .filter((l) => !l.locked)
            .map((l) => l.id);

          const baseMapLayer = layers.find((l) => l.isBaseMap);
          const newBaseMapVisible = baseMapLayer?.visible ?? true;

          return {
            layers,
            visibleLayerIds: newVisibleLayerIds,
            activeLayerIds: newActiveLayerIds,
            baseMapVisible: newBaseMapVisible,
          };
        }),

      setSelectedLayerId: (layerId) => set({ selectedLayerId: layerId }),

      toggleLayerVisibility: (layerId) =>
        set((state) => {
          const newLayers = state.layers.map((layer) =>
            layer.id === layerId ? { ...layer, visible: !layer.visible } : layer
          );
          const newVisibleLayerIds = newLayers
            .filter((layer) => layer.visible)
            .map((layer) => layer.id);
          const baseMapLayer = newLayers.find((l) => l.isBaseMap);
          const newBaseMapVisible = baseMapLayer?.visible ?? true;
          return {
            layers: newLayers,
            visibleLayerIds: newVisibleLayerIds,
            baseMapVisible: newBaseMapVisible,
          };
        }),

      toggleLayerLock: (layerId) =>
        set((state) => {
          const newLayers = state.layers.map((layer) =>
            layer.id === layerId ? { ...layer, locked: !layer.locked } : layer
          );
          const newActiveLayerIds = newLayers
            .filter((layer) => !layer.locked)
            .map((layer) => layer.id);
          return {
            layers: newLayers,
            activeLayerIds: newActiveLayerIds,
          };
        }),

      updateLayerOpacity: (layerId, opacity) =>
        set((state) => ({
          layers: state.layers.map((layer) =>
            layer.id === layerId ? { ...layer, opacity } : layer
          ),
        })),

      updateLayerZIndex: (layerId, zIndex) =>
        set((state) => ({
          layers: state.layers.map((layer) =>
            layer.id === layerId ? { ...layer, zIndex } : layer
          ),
        })),

      updateLayerScale: (layerId, scale) =>
        set((state) => ({
          layers: state.layers.map((layer) =>
            layer.id === layerId ? { ...layer, scale } : layer
          ),
        })),

      updateLayerPosition: (layerId, offsetX, offsetY) =>
        set((state) => {
          // Prevent moving base map layer
          const layer = state.layers.find((l) => l.id === layerId);
          if (layer?.isBaseMap) {
            console.warn("Cannot move base map layer");
            return state;
          }

          return {
            layers: state.layers.map((l) =>
              l.id === layerId ? { ...l, offsetX, offsetY } : l
            ),
          };
        }),

      addLayer: (layer) =>
        set((state) => {
          const newLayer = { ...layer, id: crypto.randomUUID(), offsetX: 0, offsetY: 0 };
          const newLayers = [...state.layers, newLayer];
          const newVisibleLayerIds = newLayers
            .filter((l) => l.visible)
            .map((l) => l.id);
          const newActiveLayerIds = newLayers
            .filter((l) => !l.locked)
            .map((l) => l.id);
          return {
            layers: newLayers,
            visibleLayerIds: newVisibleLayerIds,
            activeLayerIds: newActiveLayerIds,
          };
        }),

      removeLayer: (layerId) =>
        set((state) => {

          const newLayers = state.layers.filter((layer) => layer.id !== layerId);
          const newVisibleLayerIds = newLayers
            .filter((l) => l.visible)
            .map((l) => l.id);
          const newActiveLayerIds = newLayers
            .filter((l) => l.locked === false)
            .map((l) => l.id);
          return {
            layers: newLayers,
            visibleLayerIds: newVisibleLayerIds,
            activeLayerIds: newActiveLayerIds,
            // Clear selection if removed layer was selected
            selectedLayerId:
              state.selectedLayerId === layerId ? null : state.selectedLayerId,
          };
        }),

      moveLayerUp: (layerId) =>
        set((state) => {
          const index = state.layers.findIndex((l) => l.id === layerId);
          if (index === 0) return state;
          const newLayers = [...state.layers];
          [newLayers[index - 1], newLayers[index]] = [
            newLayers[index],
            newLayers[index - 1],
          ];
          const newVisibleLayerIds = newLayers
            .filter((l) => l.visible)
            .map((l) => l.id);
          const newActiveLayerIds = newLayers
            .filter((l) => !l.locked)
            .map((l) => l.id);
          return {
            layers: newLayers,
            visibleLayerIds: newVisibleLayerIds,
            activeLayerIds: newActiveLayerIds,
          };
        }),

      moveLayerDown: (layerId) =>
        set((state) => {
          const index = state.layers.findIndex((l) => l.id === layerId);
          if (index === state.layers.length - 1) return state;
          const newLayers = [...state.layers];
          [newLayers[index], newLayers[index + 1]] = [
            newLayers[index + 1],
            newLayers[index],
          ];
          const newVisibleLayerIds = newLayers
            .filter((l) => l.visible)
            .map((l) => l.id);
          const newActiveLayerIds = newLayers
            .filter((l) => !l.locked)
            .map((l) => l.id);
          return {
            layers: newLayers,
            visibleLayerIds: newVisibleLayerIds,
            activeLayerIds: newActiveLayerIds,
          };
        }),

      toggleBaseMapVisibility: () =>
        set((state) => {
          const baseMapLayer = state.layers.find((l) => l.isBaseMap);
          if (!baseMapLayer) return state;

          const newLayers = state.layers.map((layer) =>
            layer.isBaseMap ? { ...layer, visible: !layer.visible } : layer
          );
          const newVisibleLayerIds = newLayers
            .filter((l) => l.visible)
            .map((l) => l.id);
          const newBaseMapVisible = !baseMapLayer.visible;

          return {
            layers: newLayers,
            visibleLayerIds: newVisibleLayerIds,
            baseMapVisible: newBaseMapVisible,
          };
        }),

      reset: () => set(initialState),
    }),
    {
      name: "map-storage",
    }
  )
);

// Selector hooks for optimized re-renders
export const useGrid = () => useMapStore((state) => state.grid);
export const useSnap = () => useMapStore((state) => state.snap);
export const useScale = () => useMapStore((state) => state.scale);
export const useLayers = () => useMapStore((state) => state.layers);
export const useSelectedLayerId = () =>
  useMapStore((state) => state.selectedLayerId);
export const useVisibleLayerIds = () =>
  useMapStore((state) => state.visibleLayerIds);
export const useActiveLayerIds = () =>
  useMapStore((state) => state.activeLayerIds);

export const useBaseMapVisible = () =>
  useMapStore((state) => state.baseMapVisible);
export const useLayerPosition = (layerId: string) =>
  useMapStore((state) => {
    const layer = state.layers.find((l) => l.id === layerId);
    return { offsetX: layer?.offsetX ?? 0, offsetY: layer?.offsetY ?? 0 };
  });

import { create } from "zustand";
import { devtools, persist } from "zustand/middleware";
import type { Pin, PinType } from "@prisma/client";
import { createPin as createPinAction, deletePin as deletePinAction, updatePin as updatePinAction } from "@/actions/pins";
import { PinTypeEnum } from "@/types/pin.type";

// UI State for pin interactions
export interface PinUIState {
  selectedPinId: string | null;
  isCreating: boolean;
  isEditing: boolean;
  hoverPinId: string | null;
}

// Filter state for pins - using Record<PinTypeEnum, boolean> approach
export interface PinFilters {
  searchTerm: string;
  pinTypeFilters: Record<PinTypeEnum, boolean>;
  layerIds: string[];
  showVisibleOnly: boolean;
}

// Pin data stored in client state (synced with server)
interface PinDataState {
  pins: Pin[];
  filteredPins: Pin[];
  isLoading: boolean;
  error: string | null;
}

interface PinsStore extends PinUIState, PinFilters, PinDataState {
  // Selection state
  selectPin: (pinId: string | null) => void;
  clearSelection: () => void;

  // Creation/editing state
  startCreating: () => void;
  stopCreating: () => void;
  startEditing: () => void;
  stopEditing: () => void;

  // Hover state
  setHoverPin: (pinId: string | null) => void;

  // Pin CRUD operations (local state)
  setPins: (pins: Pin[]) => void;
  addPin: (pin: Pin) => void;
  updatePin: (pinId: string, updates: Partial<Pin>) => void;
  deletePin: (pinId: string) => void;

  // Pin CRUD operations (server sync with optimistic updates)
  createPin: (data: Parameters<typeof createPinAction>[0]) => Promise<void>;
  deletePinServer: (pinId: string) => Promise<void>;
  updatePinServer: (data: Parameters<typeof updatePinAction>[0]) => Promise<void>;

  // Filter actions
  setSearchTerm: (term: string) => void;
  setPinTypeFilter: (pinType: PinTypeEnum, value: boolean) => void;
  togglePinTypeFilter: (pinType: PinTypeEnum) => void;
  showAllPinTypes: () => void;
  hideAllPinTypes: () => void;
  setLayerIds: (layerIds: string[]) => void;
  toggleLayerId: (layerId: string) => void;
  toggleShowVisibleOnly: () => void;
  resetFilters: () => void;
  applyFilters: () => void;
  getVisiblePinTypes: () => PinTypeEnum[];

  // Loading and error state
  setLoading: (isLoading: boolean) => void;
  setError: (error: string | null) => void;

  // Reset all
  reset: () => void;
}

// Helper function to create default pin type filters
const createDefaultPinTypeFilters = (): Record<PinTypeEnum, boolean> => ({
  [PinTypeEnum.CITY]: true,
  [PinTypeEnum.VILLAGE]: true,
  [PinTypeEnum.POI]: true,
  [PinTypeEnum.CHARACTER]: true,
  [PinTypeEnum.DUNGEON]: true,
  [PinTypeEnum.SHOP]: true,
  [PinTypeEnum.QUEST]: true,
  [PinTypeEnum.TREASURE]: true,
  [PinTypeEnum.CUSTOM]: true,
});

const initialState: PinUIState & PinFilters & PinDataState = {
  // UI State
  selectedPinId: null,
  isCreating: false,
  isEditing: false,
  hoverPinId: null,

  // Filters
  searchTerm: "",
  pinTypeFilters: createDefaultPinTypeFilters(),
  layerIds: [],

  showVisibleOnly: false,

  // Pin data
  pins: [],
  filteredPins: [],
  isLoading: false,
  error: null,
};

// Helper function to apply filters
const filterPins = (
  pins: Pin[],
  searchTerm: string,
  pinTypeFilters: Record<PinTypeEnum, boolean>,
  layerIds: string[],
  showVisibleOnly: boolean
): Pin[] => {
  return pins.filter((pin) => {
    // Search term filter
    if (searchTerm && !pin.title.toLowerCase().includes(searchTerm.toLowerCase())) {
      return false;
    }

    // Pin type filter - check if type is explicitly set to false
    if (pinTypeFilters[pin.pinType as PinTypeEnum] === false) {
      return false;
    }

    // Layer filter
    if (layerIds.length > 0 && pin.layerId && !layerIds.includes(pin.layerId)) {
      return false;
    }

    // Visibility filter
    if (showVisibleOnly && !pin.isVisible) {
      return false;
    }

    return true;
  });
};

export const usePinsStore = create<PinsStore>()(
  devtools(
    persist(
      (set, get) => ({
        ...initialState,

        // Selection actions
        selectPin: (pinId) => set({ selectedPinId: pinId }),

        clearSelection: () => set({ selectedPinId: null }),

        // Creation/editing actions
        startCreating: () => set({ isCreating: true, selectedPinId: null }),

        stopCreating: () => set({ isCreating: false }),

        startEditing: () => set({ isEditing: true }),

        stopEditing: () => set({ isEditing: false }),

        // Hover action
        setHoverPin: (pinId) => set({ hoverPinId: pinId }),

        // Pin CRUD operations
        setPins: (pins) => {
          const state = get();
          const filtered = filterPins(
            pins,
            state.searchTerm,
            state.pinTypeFilters,
            state.layerIds,
            state.showVisibleOnly
          );
          set({ pins, filteredPins: filtered });
        },

        addPin: (pin) => {
          set((state) => {
            const newPins = [...state.pins, pin];
            const filtered = filterPins(
              newPins,
              state.searchTerm,
              state.pinTypeFilters,
              state.layerIds,
              state.showVisibleOnly
            );
            return { pins: newPins, filteredPins: filtered };
          });
        },

        updatePin: (pinId, updates) => {
          set((state) => {
            const newPins = state.pins.map((pin) =>
              pin.id === pinId ? { ...pin, ...updates } : pin
            );
            const filtered = filterPins(
              newPins,
              state.searchTerm,

              state.pinTypeFilters,
              state.layerIds,
              state.showVisibleOnly
            );
            return { pins: newPins, filteredPins: filtered };
          });
        },

        deletePin: (pinId) => {
          set((state) => {
            const newPins = state.pins.filter((pin) => pin.id !== pinId);
            const filtered = filterPins(
              newPins,
              state.searchTerm,
              state.pinTypeFilters,
              state.layerIds,
              state.showVisibleOnly
            );
            // Clear selection if deleted pin was selected
            const newSelectedPinId =
              state.selectedPinId === pinId ? null : state.selectedPinId;
            return {
              pins: newPins,
              filteredPins: filtered,
              selectedPinId: newSelectedPinId,
            };
          });
        },

        // Filter actions
        setSearchTerm: (term) =>
          set((state) => {
            const filtered = filterPins(
              state.pins,
              term,
              state.pinTypeFilters,
              state.layerIds,
              state.showVisibleOnly
            );
            return { searchTerm: term, filteredPins: filtered };
          }),

        setPinTypeFilter: (pinType, value) =>
          set((state) => {
            const newFilters = {
              ...state.pinTypeFilters,
              [pinType]: value,
            };
            const filtered = filterPins(
              state.pins,
              state.searchTerm,
              newFilters,
              state.layerIds,
              state.showVisibleOnly
            );
            return { pinTypeFilters: newFilters, filteredPins: filtered };
          }),

        togglePinTypeFilter: (pinType) =>
          set((state) => {
            const newFilters = {
              ...state.pinTypeFilters,
              [pinType]: !state.pinTypeFilters[pinType],
            };
            const filtered = filterPins(
              state.pins,
              state.searchTerm,
              newFilters,
              state.layerIds,
              state.showVisibleOnly
            );
            return { pinTypeFilters: newFilters, filteredPins: filtered };
          }),

        showAllPinTypes: () =>
          set((state) => {
            const newFilters = createDefaultPinTypeFilters();
            const filtered = filterPins(
              state.pins,
              state.searchTerm,
              newFilters,
              state.layerIds,
              state.showVisibleOnly
            );
            return { pinTypeFilters: newFilters, filteredPins: filtered };
          }),

        hideAllPinTypes: () =>
          set((state) => {
            const newFilters = Object.fromEntries(
              Object.entries(createDefaultPinTypeFilters()).map(([key]) => [key, false])
            ) as Record<PinTypeEnum, boolean>;
            const filtered = filterPins(
              state.pins,
              state.searchTerm,
              newFilters,
              state.layerIds,
              state.showVisibleOnly
            );
            return { pinTypeFilters: newFilters, filteredPins: filtered };

          }),

        setLayerIds: (layerIds) =>
          set((state) => {
            const filtered = filterPins(
              state.pins,
              state.searchTerm,
              state.pinTypeFilters,
              layerIds,
              state.showVisibleOnly
            );
            return { layerIds, filteredPins: filtered };
          }),

        toggleLayerId: (layerId) =>
          set((state) => {
            const newLayerIds = state.layerIds.includes(layerId)
              ? state.layerIds.filter((id) => id !== layerId)
              : [...state.layerIds, layerId];
            const filtered = filterPins(
              state.pins,
              state.searchTerm,
              state.pinTypeFilters,
              newLayerIds,
              state.showVisibleOnly
            );
            return { layerIds: newLayerIds, filteredPins: filtered };
          }),

        toggleShowVisibleOnly: () =>
          set((state) => {
            const newShowVisibleOnly = !state.showVisibleOnly;
            const filtered = filterPins(
              state.pins,
              state.searchTerm,
              state.pinTypeFilters,
              state.layerIds,
              newShowVisibleOnly
            );
            return { showVisibleOnly: newShowVisibleOnly, filteredPins: filtered };
          }),

        resetFilters: () =>
          set((state) => {
            const newFilters = createDefaultPinTypeFilters();
            const filtered = filterPins(state.pins, "", newFilters, [], false);
            return {
              searchTerm: "",
              pinTypeFilters: newFilters,
              layerIds: [],
              showVisibleOnly: false,
              filteredPins: filtered,
            };
          }),

        applyFilters: () =>
          set((state) => {
            const filtered = filterPins(
              state.pins,
              state.searchTerm,
              state.pinTypeFilters,
              state.layerIds,
              state.showVisibleOnly
            );
            return { filteredPins: filtered };
          }),

        getVisiblePinTypes: () => {
          const state = get();
          return Object.entries(state.pinTypeFilters)
            .filter(([, visible]) => visible)
            .map(([type]) => type as PinTypeEnum);
        },

        // Loading and error actions
        setLoading: (isLoading) => set({ isLoading }),

        setError: (error) => set({ error }),

        // Reset all
        reset: () => set(initialState),

        // Server sync methods with optimistic updates
        createPin: async (data) => {
          try {
            // Optimistic update - add pin with temporary ID
            const tempId = `temp-${Date.now()}`;
            const optimisticPin: Pin = {
              ...data,
              id: tempId,
              createdAt: new Date(),
              updatedAt: new Date(),
              isVisible: data.isVisible ?? true,
              opacity: data.opacity ?? 1,
              size: data.size ?? 32,
              minZoom: 0,
              maxZoom: 200,
            } as Pin;

            get().addPin(optimisticPin);

            // Server call
            const result = await createPinAction(data);

            // Replace optimistic pin with real one
            set((state) => ({
              pins: state.pins.map((p) =>
                p.id === tempId ? { ...result.pin, gameWorldId: data.gameWorldId } : p
              ),
              filteredPins: state.filteredPins.map((p) =>
                p.id === tempId ? { ...result.pin, gameWorldId: data.gameWorldId } : p
              ),
            }));
          } catch (error) {
            console.error("[PinsStore] Failed to create pin:", error);
            get().setError(error instanceof Error ? error.message : "Failed to create pin");
            throw error;
          }
        },

        deletePinServer: async (pinId) => {
          try {
            // Optimistic update - remove from store
            const pinToDelete = get().pins.find((p) => p.id === pinId);
            if (!pinToDelete) {
              throw new Error("Pin not found");
            }

            get().deletePin(pinId);

            // Server call
            await deletePinAction(pinId);
          } catch (error) {
            console.error("[PinsStore] Failed to delete pin:", error);
            get().setError(error instanceof Error ? error.message : "Failed to delete pin");
            throw error;
          }
        },

        updatePinServer: async (data) => {
          try {
            // Optimistic update - update in store
            get().updatePin(data.id, data as Partial<Pin>);

            // Server call
            await updatePinAction(data);
          } catch (error) {
            console.error("[PinsStore] Failed to update pin:", error);
            get().setError(error instanceof Error ? error.message : "Failed to update pin");
            throw error;
          }
        },
      }),
      {
        name: "pins-storage",
        // Only persist UI state and filters, not the actual pins (those come from server)
        partialize: (state) => ({
          selectedPinId: state.selectedPinId,
          isCreating: state.isCreating,
          isEditing: state.isEditing,
          searchTerm: state.searchTerm,
          pinTypeFilters: state.pinTypeFilters,
          layerIds: state.layerIds,
          showVisibleOnly: state.showVisibleOnly,
        }),
      }
    ),
    {
      name: "pins-store",
    }
  )
);

