/**
 * Update a gallery item
 * @param data - Gallery item update data
 * @returns Result with updated gallery item or error
 */
export async function updateGalleryItem(data: GalleryItemUpdateInput): Promise<Result<any>> {
  return safeAsync(async () => {
    // Validate input
    const validated = UpdateGalleryItemSchema.parse(data);

    // Get authenticated user
    const user = await getAuthenticatedUser();

    // Check if gallery item exists and verify permission
    const existingItem = await verifyGalleryPermission(validated.id, user.id);

    // Get worldId for revalidation
    const worldId = existingItem.pin?.gameWorldId || existingItem.loreEntry?.gameWorldId;

    // Build update data
    const updateData: any = {};
    if (validated.title !== undefined) updateData.title = validated.title;
    if (validated.description !== undefined) updateData.description = validated.description;
    if (validated.imageUrl !== undefined) updateData.imageUrl = validated.imageUrl;
    if (validated.type !== undefined) updateData.type = validated.type;
    if (validated.order !== undefined) updateData.order = validated.order;
    if (validated.pinId !== undefined) updateData.pinId = validated.pinId;
    if (validated.loreEntryId !== undefined) updateData.loreEntryId = validated.loreEntryId;

    // Update gallery item
    const galleryItem = await prisma.galleryItem.update({
      where: { id: validated.id },

      data: updateData,
    });

    if (worldId) {
      revalidatePath(`/world/${worldId}`);
    }

    return galleryItem;
  }, "updateGalleryItem");
}

/**
 * Delete a gallery item
 * @param id - Gallery item ID
 * @returns Result with deleted gallery item ID or error
 */
export async function deleteGalleryItem(id: string): Promise<Result<{ itemId: string }>> {
  return safeAsync(async () => {
    // Get authenticated user
    const user = await getAuthenticatedUser();

    // Check if gallery item exists and verify permission
    const item = await verifyGalleryPermission(id, user.id);

    // Get worldId for revalidation
    const worldId = item.pin?.gameWorldId || item.loreEntry?.gameWorldId;

    // Delete file from disk
    const { unlink } = require("fs/promises");
    const path = require("path");

    try {
      const filePath = path.join(process.cwd(), "public", item.imageUrl);
      await unlink(filePath);
    } catch (error) {
      console.warn("[deleteGalleryItem] Failed to delete file:", error);
      // Continue even if file deletion fails
    }

    // Delete gallery item from database
    await prisma.galleryItem.delete({
      where: { id },
    });

    if (worldId) {
      revalidatePath(`/world/${worldId}`);
    }

    return { itemId: id };
  }, "deleteGalleryItem");
}

/**
 * Link a gallery item to a pin
 * @param itemId - Gallery item ID
 * @param pinId - Pin ID
 * @returns Result with updated gallery item or error
 */
export async function linkGalleryItemToPin(itemId: string, pinId: string): Promise<Result<any>> {
  return safeAsync(async () => {
    // Get authenticated user
    const user = await getAuthenticatedUser();

    // Verify permissions for both gallery item and pin
    await verifyGalleryPermission(itemId, user.id);
    await verifyPinPermission(pinId, user.id);

    // Verify pin and gallery item belong to same world
    const galleryItem = await prisma.galleryItem.findUnique({
      where: { id: itemId },
      include: { pin: true, loreEntry: true },
    });

    const pin = await prisma.pin.findUnique({
      where: { id: pinId },
    });

    const galleryItemWorldId = galleryItem?.pin?.gameWorldId || galleryItem?.loreEntry?.gameWorldId;

    if (galleryItemWorldId && pin?.gameWorldId !== galleryItemWorldId) {
      throw new ValidationError("Pin and gallery item must belong to the same world");
    }

    // Update gallery item
    const updated = await prisma.galleryItem.update({
      where: { id: itemId },
      data: { pinId },
    });

    if (galleryItemWorldId) {
      revalidatePath(`/world/${galleryItemWorldId}`);
    }

    return updated;
  }, "linkGalleryItemToPin");
}

/**
 * Link a gallery item to a lore entry
 * @param itemId - Gallery item ID

 * @param loreEntryId - Lore entry ID
 * @returns Result with updated gallery item or error
 */
export async function linkGalleryItemToLore(itemId: string, loreEntryId: string): Promise<Result<any>> {
  return safeAsync(async () => {
    // Get authenticated user
    const user = await getAuthenticatedUser();

    // Verify permissions for both gallery item and lore entry
    await verifyGalleryPermission(itemId, user.id);
    await verifyLorePermission(loreEntryId, user.id);

    // Verify lore entry and gallery item belong to same world
    const galleryItem = await prisma.galleryItem.findUnique({
      where: { id: itemId },
      include: { pin: true, loreEntry: true },
    });

    const lore = await prisma.loreEntry.findUnique({
      where: { id: loreEntryId },
    });

    const galleryItemWorldId = galleryItem?.pin?.gameWorldId || galleryItem?.loreEntry?.gameWorldId;

    if (galleryItemWorldId && lore?.gameWorldId !== galleryItemWorldId) {
      throw new ValidationError("Lore entry and gallery item must belong to the same world");
    }

    // Update gallery item
    const updated = await prisma.galleryItem.update({
      where: { id: itemId },
      data: { loreEntryId },
    });

    if (galleryItemWorldId) {
      revalidatePath(`/world/${galleryItemWorldId}`);
    }

    return updated;
  }, "linkGalleryItemToLore");
}

/**
 * Reorder gallery items
 * @param updates - Array of { id, order } pairs
 * @returns Result with updated gallery items or error
 */
export async function reorderGalleryItems(updates: Array<{ id: string; order: number }>): Promise<Result<any[]>> {
  return safeAsync(async () => {
    // Get authenticated user
    const user = await getAuthenticatedUser();

    // Verify permission for first item (assumes all items belong to same world)
    if (updates.length > 0) {
      await verifyGalleryPermission(updates[0].id, user.id);
    }

    // Update all items
    const updatedItems = await Promise.all(
      updates.map((update) =>
        prisma.galleryItem.update({
          where: { id: update.id },
          data: { order: update.order },
        })
      )
    );

    return updatedItems;
  }, "reorderGalleryItems");
}

"use server";

import { prisma } from "@/lib/prisma";
import { revalidatePath } from "next/cache";
import { safeAsync, type Result } from "@/lib/errors";
import {
  getAuthenticatedUser,
  verifyWorldPermission,
  verifyLayerPermission,
} from "@/lib/server-helpers";

/**
 * Create a new layer for a world
 * @param worldId - World ID to add layer to
 * @param data - Layer data (name, description, zIndex, etc.)
 * @returns Result with created layer or error
 */
export async function createLayer(
  worldId: string,
  data: {
    name: string;
    description?: string;
    isVisible?: boolean;
    opacity?: number;
    zIndex?: number;
    offsetX?: number;
    offsetY?: number;
    scale?: number;
  }
): Promise<Result<any>> {
  return safeAsync(async () => {
    // Get authenticated user
    const user = await getAuthenticatedUser();

    // Verify user has permission to edit the world
    await verifyWorldPermission(worldId, user.id);

    // Get the highest zIndex to place new layer on top
    const highestZIndex = await prisma.mapLayer.findFirst({
      where: { gameWorldId: worldId },
      orderBy: { zIndex: "desc" },
      select: { zIndex: true },
    });

    const layer = await prisma.mapLayer.create({
      data: {
        name: data.name,
        description: data.description,
        isVisible: data.isVisible ?? true,
        opacity: data.opacity ?? 1.0,
        zIndex: data.zIndex ?? (highestZIndex?.zIndex ?? -1) + 1,
        offsetX: data.offsetX ?? 0,
        offsetY: data.offsetY ?? 0,
        scale: data.scale ?? 1.0,
        gameWorldId: worldId,
      },
    });

    revalidatePath(`/world/${worldId}`);

    return layer;
  }, "createLayer");
}

/**
 * Update a layer's properties
 * @param layerId - Layer ID to update
 * @param data - Partial layer data to update
 * @returns Result with updated layer or error
 */
export async function updateLayer(
  layerId: string,
  data: {
    name?: string;
    description?: string;
    isVisible?: boolean;
    opacity?: number;
    zIndex?: number;
    offsetX?: number;
    offsetY?: number;
    scale?: number;
  }
): Promise<Result<any>> {
  return safeAsync(async () => {
    // Get authenticated user
    const user = await getAuthenticatedUser();

    // Verify layer exists and user has permission
    const layer = await verifyLayerPermission(layerId, user.id);

    const updatedLayer = await prisma.mapLayer.update({
      where: { id: layerId },
      data: {
        ...(data.name !== undefined && { name: data.name }),
        ...(data.description !== undefined && { description: data.description }),
        ...(data.isVisible !== undefined && { isVisible: data.isVisible }),
        ...(data.opacity !== undefined && { opacity: data.opacity }),
        ...(data.zIndex !== undefined && { zIndex: data.zIndex }),
        ...(data.offsetX !== undefined && { offsetX: data.offsetX }),
        ...(data.offsetY !== undefined && { offsetY: data.offsetY }),

        ...(data.scale !== undefined && { scale: data.scale }),
      },
    });

    revalidatePath(`/world/${layer.gameWorldId}`);

    return updatedLayer;
  }, "updateLayer");
}

/**
 * Update layer position (offsetX and offsetY)
 * Optimized for drag operations - updates only position fields
 * @param layerId - Layer ID to update
 * @param offsetX - X offset in pixels
 * @param offsetY - Y offset in pixels
 * @returns Result with updated layer or error
 */
export async function updateLayerPosition(
  layerId: string,
  offsetX: number,
  offsetY: number
): Promise<Result<any>> {
  return safeAsync(async () => {
    // Get authenticated user
    const user = await getAuthenticatedUser();

    // Verify layer exists and user has permission
    await verifyLayerPermission(layerId, user.id);

    const updatedLayer = await prisma.mapLayer.update({
      where: { id: layerId },
      data: { offsetX, offsetY },
    });

    // No revalidatePath needed - Zustand store manages client-side state
    // This optimization prevents unnecessary page refreshes during drag operations

    return updatedLayer;
  }, "updateLayerPosition");
}

/**
 * Update layer scale
 * @param layerId - Layer ID to update
 * @param scale - Scale factor (0.5 - 2.0)
 * @returns Result with updated layer or error
 */
export async function updateLayerScale(layerId: string, scale: number): Promise<Result<any>> {
  return safeAsync(async () => {
    // Get authenticated user
    const user = await getAuthenticatedUser();

    // Verify layer exists and user has permission
    await verifyLayerPermission(layerId, user.id);

    const updatedLayer = await prisma.mapLayer.update({
      where: { id: layerId },
      data: { scale },
    });

    // No revalidatePath needed - Zustand store manages client-side state

    return updatedLayer;
  }, "updateLayerScale");
}

/**
 * Update layer z-index (for reordering layers)
 * @param layerId - Layer ID to update
 * @param zIndex - New z-index value
 * @returns Result with updated layer or error
 */
export async function updateLayerZIndex(layerId: string, zIndex: number): Promise<Result<any>> {
  return safeAsync(async () => {
    // Get authenticated user
    const user = await getAuthenticatedUser();

    // Verify layer exists and user has permission
    await verifyLayerPermission(layerId, user.id);

    const updatedLayer = await prisma.mapLayer.update({
      where: { id: layerId },
      data: { zIndex },
    });

    // No revalidatePath needed - Zustand store manages client-side state

    return updatedLayer;
  }, "updateLayerZIndex");
}

/**
 * Delete a layer
 * @param layerId - Layer ID to delete
 * @returns Result with deleted layer or error
 */
export async function deleteLayer(layerId: string): Promise<Result<any>> {
  return safeAsync(async () => {
    // Get authenticated user

    const user = await getAuthenticatedUser();

    // Verify layer exists and user has permission
    const layer = await verifyLayerPermission(layerId, user.id);

    const deletedLayer = await prisma.mapLayer.delete({
      where: { id: layerId },
    });

    revalidatePath(`/world/${layer.gameWorldId}`);

    return deletedLayer;
  }, "deleteLayer");
}

/**
 * Batch update multiple layers (for z-index reordering)
 * @param updates - Array of layer updates
 * @returns Result with updated layers or error
 */
export async function batchUpdateLayers(
  updates: Array<{
    id: string;
    zIndex: number;
    offsetX?: number;
    offsetY?: number;
    scale?: number;
  }>
): Promise<Result<any[]>> {
  return safeAsync(async () => {
    // Get authenticated user
    const user = await getAuthenticatedUser();

    // Verify permission for first layer (assumes all layers belong to same world)
    if (updates.length > 0) {
      await verifyLayerPermission(updates[0].id, user.id);
    }

    // Update all layers in a transaction
    const updatedLayers = await prisma.$transaction(
      updates.map((update) =>
        prisma.mapLayer.update({
          where: { id: update.id },
          data: {
            zIndex: update.zIndex,
            ...(update.offsetX !== undefined && { offsetX: update.offsetX }),
            ...(update.offsetY !== undefined && { offsetY: update.offsetY }),
            ...(update.scale !== undefined && { scale: update.scale }),
          },
        })
      )
    );

    return updatedLayers;
  }, "batchUpdateLayers");
}

"use server";

import { prisma } from "@/lib/prisma";
import { revalidatePath } from "next/cache";
import {
  CreateLoreEntrySchema,
  UpdateLoreEntrySchema,
} from "@/components/lore/logic/lore-schemas";
import type { LoreEntryCreateInput, LoreEntryUpdateInput } from "@/types/lore.type";
import {
  safeAsync,
  ValidationError,
  type Result,
} from "@/lib/errors";
import {
  getAuthenticatedUser,
  verifyWorldPermission,
  verifyLorePermission,
} from "@/lib/server-helpers";

/**
 * Create a new lore entry in a world
 * @param data - Lore entry creation data (validated with Zod)
 * @returns Result with created lore entry ID and data, or error
 */
export async function createLoreEntry(data: LoreEntryCreateInput): Promise<Result<{ loreId: string; loreEntry: any }>> {
  return safeAsync(async () => {
    // Validate input with Zod
    const validated = CreateLoreEntrySchema.parse(data);

    // Get authenticated user
    const user = await getAuthenticatedUser();

    // Verify user has access to the world
    await verifyWorldPermission(validated.gameWorldId, user.id);

    // Check if slug already exists in this world
    const existingLore = await prisma.loreEntry.findUnique({
      where: {
        gameWorldId_slug: {
          gameWorldId: validated.gameWorldId,
          slug: validated.slug,
        },
      },
    });

    let finalSlug = validated.slug;
    if (existingLore) {
      // If slug exists, append a random suffix
      finalSlug = `${validated.slug}-${Math.random().toString(36).substring(2, 8)}`;
    }

    // Create lore entry
    const loreEntry = await prisma.loreEntry.create({
      data: {
        title: validated.title,
        content: validated.content,
        slug: finalSlug,
        category: validated.category,
        isVisible: validated.isVisible ?? false,
        isPublic: validated.isPublic ?? true,
        userId: user.id,
        gameWorldId: validated.gameWorldId,
      },
    });

    revalidatePath(`/world/${validated.gameWorldId}`);

    return { loreId: loreEntry.id, loreEntry };
  }, "createLoreEntry");
}

/**
 * Get a lore entry by ID
 * @param id - Lore entry ID
 * @returns Lore entry with full details or null
 */
export async function getLoreEntryById(id: string) {
  try {
    const loreEntry = await prisma.loreEntry.findUnique({
      where: { id },
      include: {
        user: {
          select: {
            name: true,
            image: true,
          },
        },
        gameWorld: {
          select: {
            id: true,
            title: true,
          },
        },
        gallery: {
          orderBy: { order: "asc" },
        },
      },
    });

    return loreEntry;
  } catch (error) {
    console.error("[getLoreEntryById] Failed to fetch lore entry:", error);
    return null;
  }
}

/**
 * Get all lore entries for a world
 * @param gameWorldId - World ID
 * @returns Array of lore entries
 */
export async function getLoreEntriesByWorld(gameWorldId: string) {
  try {
    const loreEntries = await prisma.loreEntry.findMany({
      where: {
        gameWorldId,
      },
      orderBy: {
        updatedAt: "desc",
      },
      include: {
        user: {
          select: {
            name: true,
            image: true,
          },
        },
      },
    });

    return loreEntries;
  } catch (error) {
    console.error("[getLoreEntriesByWorld] Failed to fetch lore entries:", error);
    return [];
  }
}

/**
 * Update an existing lore entry
 * @param data - Lore entry update data (validated with Zod)
 * @returns Result with updated lore entry or error
 */
export async function updateLoreEntry(data: LoreEntryUpdateInput): Promise<Result<any>> {
  return safeAsync(async () => {
    // Validate input with Zod
    const validated = UpdateLoreEntrySchema.parse(data);

    // Get authenticated user
    const user = await getAuthenticatedUser();

    // Check if lore entry exists and user has permission
    const existingLore = await verifyLorePermission(validated.id, user.id);

    // If slug is being updated, check for uniqueness
    let finalSlug = validated.slug;
    if (validated.slug) {
      const existingWithSlug = await prisma.loreEntry.findUnique({
        where: {
          gameWorldId_slug: {
            gameWorldId: existingLore.gameWorldId,
            slug: validated.slug,
          },
        },
      });

      if (existingWithSlug && existingWithSlug.id !== validated.id) {
        // Slug already exists, append random suffix
        finalSlug = `${validated.slug}-${Math.random().toString(36).substring(2, 8)}`;
      }
    }

    // Build update data (only include fields that are provided)
    const updateData: any = {};
    if (validated.title !== undefined) updateData.title = validated.title;
    if (validated.content !== undefined) updateData.content = validated.content;
    if (finalSlug !== undefined) updateData.slug = finalSlug;
    if (validated.category !== undefined) updateData.category = validated.category;
    if (validated.isVisible !== undefined) updateData.isVisible = validated.isVisible;
    if (validated.isPublic !== undefined) updateData.isPublic = validated.isPublic;

    // Update lore entry
    const loreEntry = await prisma.loreEntry.update({
      where: { id: validated.id },
      data: updateData,
    });

    revalidatePath(`/world/${existingLore.gameWorldId}`);

    return loreEntry;
  }, "updateLoreEntry");
}

/**
 * Delete a lore entry
 * @param id - Lore entry ID
 * @returns Result with deleted lore entry ID or error
 */
export async function deleteLoreEntry(id: string): Promise<Result<{ loreId: string }>> {
  return safeAsync(async () => {

    // Get authenticated user
    const user = await getAuthenticatedUser();

    // Check if lore entry exists and user has permission
    const loreEntry = await verifyLorePermission(id, user.id);

    // Delete lore entry
    await prisma.loreEntry.delete({
      where: { id },
    });

    revalidatePath(`/world/${loreEntry.gameWorldId}`);

    return { loreId: id };
  }, "deleteLoreEntry");
}

/**
 * Toggle lore entry visibility
 * Convenience action for showing/hiding lore entries
 * @param id - Lore entry ID
 * @returns Result with updated lore entry or error
 */
export async function toggleLoreVisibility(id: string): Promise<Result<any>> {
  return safeAsync(async () => {
    // Get authenticated user
    const user = await getAuthenticatedUser();

    // Verify permission
    const loreEntry = await verifyLorePermission(id, user.id);

    // Toggle visibility
    const updated = await prisma.loreEntry.update({
      where: { id },
      data: { isVisible: !loreEntry.isVisible },
    });

    revalidatePath(`/world/${loreEntry.gameWorldId}`);

    return updated;
  }, "toggleLoreVisibility");
}

"use server";

import { prisma } from "@/lib/prisma";
import { z } from "zod";
import {
  safeAsync,
  ValidationError,
  type Result,
} from "@/lib/errors";
import {
  getAuthenticatedUser,
  verifyWorldPermission,
} from "@/lib/server-helpers";

// ============================================
// SEARCH SCHEMAS
// ============================================

/**
 * Search filters schema
 */
export const SearchFiltersSchema = z.object({
  contentType: z.enum(["all", "pins", "lore"]).default("all"),
  pinType: z.enum(["CITY", "VILLAGE", "POI", "CHARACTER", "DUNGEON", "SHOP", "QUEST", "TREASURE", "CUSTOM"]).optional(),
  loreCategory: z.enum(["GENERAL", "HISTORY", "GEOGRAPHY", "CHARACTERS", "FACTIONS", "MAGIC", "ITEMS", "QUESTS", "CUSTOM"]).optional(),
  layerId: z.string().optional(),
});

export type SearchFilters = z.infer<typeof SearchFiltersSchema>;

/**
 * Search query schema
 */
export const SearchQuerySchema = z.object({
  worldId: z.string().min(1, "World ID is required"),
  query: z.string().min(1, "Search query is required").max(200, "Search query too long"),
  filters: SearchFiltersSchema.optional(),
  limit: z.number().min(1).max(100).default(50),
});

export type SearchQuery = z.infer<typeof SearchQuerySchema>;

/**
 * Search result item types
 */
export interface PinSearchResult {
  type: "pin";
  id: string;
  title: string;
  description: string | null;
  pinType: string;
  latitude: number;
  longitude: number;
  layerId: string | null;
  layerName: string | null;
  icon: string | null;
  color: string;
  relevance: number;
}

export interface LoreSearchResult {
  type: "lore";
  id: string;
  title: string;
  content: string;
  category: string;
  slug: string;
  relevance: number;
}

export type SearchResultItem = PinSearchResult | LoreSearchResult;

export interface SearchResults {
  pins: PinSearchResult[];
  lore: LoreSearchResult[];
  total: number;
  query: string;
}

// ============================================
// SEARCH HELPERS
// ============================================

/**
 * Calculate relevance score for a search match
 * Higher score = better match
 */
function calculateRelevance(
  query: string,
  title: string,
  content?: string | null
): number {
  const queryLower = query.toLowerCase();
  const titleLower = title.toLowerCase();
  const contentLower = content?.toLowerCase() || "";

  let score = 0;

  // Exact title match = 100 points
  if (titleLower === queryLower) {

    score += 100;
  }
  // Title starts with query = 80 points
  else if (titleLower.startsWith(queryLower)) {
    score += 80;
  }
  // Title contains query = 60 points
  else if (titleLower.includes(queryLower)) {
    score += 60;
  }

  // Count word matches in title (10 points each)
  const queryWords = queryLower.split(/\s+/).filter(w => w.length > 0);
  const titleWords = titleLower.split(/\s+/);
  queryWords.forEach(word => {
    if (titleWords.some(tw => tw.includes(word))) {
      score += 10;
    }
  });

  // Content matches (5 points each occurrence, max 25)
  if (contentLower) {
    const contentMatches = (contentLower.match(new RegExp(queryLower, "gi")) || []).length;
    score += Math.min(contentMatches * 5, 25);
  }

  return score;
}

/**
 * Highlight search terms in text
 */
function highlightText(text: string, query: string): string {
  if (!query) return text;

  const regex = new RegExp(`(${query.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")})`, "gi");
  return text.replace(regex, "__HIGHLIGHT__$1__ENDHIGHLIGHT__");
}

/**
 * Unescape highlighted text for display
 */
export async function unescapeHighlight(text: string): Promise<string> {
  return text
    .replace(/__HIGHLIGHT__/g, "<mark>")
    .replace(/__ENDHIGHLIGHT__/g, "</mark>");
}

