"use client";

import { useCallback, useState } from "react";
import { Upload, X, Image as ImageIcon } from "lucide-react";
import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";
import {
  validateAndPrepareImage,
  formatFileSize,
  revokePreviewURL,
  createPreviewURL,
} from "../utils/image-utils";
import {
  IMAGE_MAX_SIZE,
  IMAGE_ALLOWED_TYPES,
} from "../logic/gallery-schemas";

interface FileWithPreview {
  file: File;
  preview: string;
  valid: boolean;
  error?: string;
}

interface ImageUploadZoneProps {
  onUpload?: (files: File[]) => void;
  maxSize?: number;
  accept?: string;
  multiple?: boolean;
  className?: string;
}

export function ImageUploadZone({
  onUpload,
  maxSize = IMAGE_MAX_SIZE,
  accept = IMAGE_ALLOWED_TYPES.join(","),
  multiple = true,
  className,
}: ImageUploadZoneProps) {
  const [isDragging, setIsDragging] = useState(false);
  const [pendingFiles, setPendingFiles] = useState<FileWithPreview[]>([]);

  const handleDragOver = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(true);
  }, []);

  const handleDragLeave = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
  }, []);

  const processFiles = useCallback(async (files: FileList | File[]) => {
    const fileArray = Array.from(files);
    const processedFiles: FileWithPreview[] = [];

    for (const file of fileArray) {
      const preview = createPreviewURL(file);
      const result = await validateAndPrepareImage(file);

      processedFiles.push({
        file,
        preview,
        valid: result.valid,
        error: result.valid ? undefined : result.error,
      });
    }

    setPendingFiles((prev) => [...prev, ...processedFiles]);
  }, []);

  const handleDrop = useCallback(
    async (e: React.DragEvent) => {
      e.preventDefault();
      setIsDragging(false);

      const files = e.dataTransfer.files;
      await processFiles(files);
    },
    [processFiles]
  );

  const handleFileInput = useCallback(
    async (e: React.ChangeEvent<HTMLInputElement>) => {
      const files = e.target.files;
      if (files) {
        await processFiles(files);
      }
    },
    [processFiles]
  );

  const removePendingFile = useCallback((index: number) => {
    setPendingFiles((prev) => {
      const newFiles = [...prev];
      revokePreviewURL(newFiles[index].preview);
      newFiles.splice(index, 1);
      return newFiles;
    });
  }, []);

  const handleUpload = useCallback(() => {
    const validFiles = pendingFiles.filter((f) => f.valid).map((f) => f.file);
    if (validFiles.length > 0 && onUpload) {
      onUpload(validFiles);
      // Clean up previews
      pendingFiles.forEach((f) => revokePreviewURL(f.preview));
      setPendingFiles([]);
    }
  }, [pendingFiles, onUpload]);

  const hasValidFiles = pendingFiles.some((f) => f.valid);

  return (
    <div className={cn("space-y-4", className)}>
      {/* Upload zone */}
      <div
        className={cn(
          "relative border-2 border-dashed rounded-lg p-8 transition-colors duration-200",
          isDragging
            ? "border-accent-gold bg-accent-gold/10"
            : "border-border-subtle hover:border-border-ornate"
        )}
        onDragOver={handleDragOver}
        onDragLeave={handleDragLeave}
        onDrop={handleDrop}
      >
        <input
          type="file"
          id="image-upload"
          className="absolute inset-0 w-full h-full opacity-0 cursor-pointer"
          accept={accept}
          multiple={multiple}
          onChange={handleFileInput}
        />

