      // Call success callback
      onSuccess?.();
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to save lore entry");
    } finally {

      setIsSubmitting(false);
    }
  };

  const handleCancel = () => {
    stopCreating();
    stopEditing();
  };

  return (
    <div className="p-4 bg-background-elevated border border-border-base rounded-sm">
      <div className="flex items-center justify-between mb-4">
        <h3 className="text-lg font-semibold text-text-secondary">
          {isEditing ? "Edit Lore Entry" : "New Lore Entry"}
        </h3>
        <Button
          size="sm"
          variant="ghost"
          onClick={handleCancel}
          className="h-8 w-8 p-0"
        >
          <X className="w-4 h-4" />
        </Button>
      </div>

      <form onSubmit={handleSubmit} className="space-y-4">
        {/* Error message */}
        {error && (
          <div className="p-3 bg-red-500/10 border border-red-500/30 rounded-sm">
            <p className="text-sm text-red-500">{error}</p>
          </div>
        )}

        {/* Title */}
        <div>
          <label className="block text-sm font-medium text-text-secondary mb-1">
            Title <span className="text-red-500">*</span>
          </label>
          <input
            type="text"
            value={title}
            onChange={(e) => setTitle(e.target.value)}
            placeholder="Enter title..."
            className="w-full h-10 px-3 text-sm bg-background-base border border-border-base rounded-sm focus:outline-none focus:ring-1 focus:ring-accent-gold focus:border-accent-gold placeholder:text-text-muted"
            disabled={isSubmitting}
            maxLength={200}
          />
          <p className="text-xs text-text-muted mt-1">
            {title.length} / 200 characters
          </p>
        </div>

        {/* Category */}
        <div>
          <label className="block text-sm font-medium text-text-secondary mb-1">
            Category
          </label>
          <select
            value={category}
            onChange={(e) => setCategory(e.target.value as LoreCategory)}
            className="w-full h-10 px-3 text-sm bg-background-base border border-border-base rounded-sm focus:outline-none focus:ring-1 focus:ring-accent-gold focus:border-accent-gold cursor-pointer"
            disabled={isSubmitting}
          >
            {categories.map((cat) => (
              <option key={cat.value} value={cat.value}>
                {cat.label}
              </option>
            ))}
          </select>
        </div>

        {/* Content */}
        <div>
          <label className="block text-sm font-medium text-text-secondary mb-1">
            Content <span className="text-red-500">*</span>
          </label>
          <textarea
            value={content}
            onChange={(e) => setContent(e.target.value)}
            placeholder="Write your lore entry here... (Markdown supported)"
            rows={8}
            className="w-full px-3 py-2 text-sm bg-background-base border border-border-base rounded-sm focus:outline-none focus:ring-1 focus:ring-accent-gold focus:border-accent-gold placeholder:text-text-muted resize-y"
            disabled={isSubmitting}
            maxLength={50000}
          />
          <p className="text-xs text-text-muted mt-1">
            {content.length} / 50,000 characters
          </p>
        </div>

        {/* Visibility toggles */}
        <div className="flex gap-4">
          <label className="flex items-center gap-2 cursor-pointer">
            <input
              type="checkbox"
              checked={isVisible}
              onChange={(e) => setIsVisible(e.target.checked)}
              className="w-4 h-4 rounded-sm border-border-base text-accent-gold focus:ring-accent-gold"
              disabled={isSubmitting}
            />

"use client";

import { useState, useMemo } from "react";
import { BookOpen, Badge, Plus, Search, Filter } from "lucide-react";
import { useLoreStore } from "@/stores/use-lore-store";
import { LoreCategory } from "@/types/lore.type";
import { LoreCard } from "./lore-card";
import { Button } from "@/components/ui/button";

interface LoreListProps {
  worldId: string;
}

export function LoreList({ worldId }: LoreListProps) {
  const loreEntries = useLoreStore((state) => state.loreEntries);
  const selectedLoreId = useLoreStore((state) => state.selectedLoreId);
  const searchTerm = useLoreStore((state) => state.searchTerm);
  const categoryFilters = useLoreStore((state) => state.categoryFilters);
  const showVisibleOnly = useLoreStore((state) => state.showVisibleOnly);

  const selectLore = useLoreStore((state) => state.selectLore);
  const setSearchTerm = useLoreStore((state) => state.setSearchTerm);
  const toggleCategoryFilter = useLoreStore((state) => state.toggleCategoryFilter);
  const toggleShowVisibleOnly = useLoreStore((state) => state.toggleShowVisibleOnly);
  const startCreating = useLoreStore((state) => state.startCreating);

  // Local filter state for UI
  const [localSearchTerm, setLocalSearchTerm] = useState(searchTerm);

  // Filter lore entries based on filters
  const filteredLoreEntries = useMemo(() => {
    return loreEntries.filter((lore) => {
      // Search term filter
      if (searchTerm) {
        const searchLower = searchTerm.toLowerCase();
        const matchesSearch =
          lore.title.toLowerCase().includes(searchLower) ||
          lore.content.toLowerCase().includes(searchLower);
        if (!matchesSearch) return false;
      }

      // Category filter
      if (!categoryFilters[lore.category]) {
        return false;
      }

      // Visibility filter
      if (showVisibleOnly && !lore.isVisible) {
        return false;
      }

      return true;
    });
  }, [loreEntries, searchTerm, categoryFilters, showVisibleOnly]);

  // Category labels for display
  const categoryLabels: Record<LoreCategory, string> = {
    GENERAL: "General",
    HISTORY: "History",
    GEOGRAPHY: "Geography",
    CHARACTERS: "Characters",
    FACTIONS: "Factions",
    MAGIC: "Magic",
    ITEMS: "Items",
    QUESTS: "Quests",
    CUSTOM: "Custom",
  };

  // Handle search input with debouncing
  const handleSearchChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const value = e.target.value;
    setLocalSearchTerm(value);
    setSearchTerm(value);
  };

  const loreCount = filteredLoreEntries.length;
  const totalCount = loreEntries.length;

  return (
    <div className="flex flex-col h-full">
      {/* Header */}
      <div className="flex items-center justify-between mb-4">
        <h2 className="text-lg font-semibold text-text-secondary">Lore</h2>
        <Button
          size="sm"
          variant="ghost"
          onClick={startCreating}
          className="h-8 px-3 text-accent-gold hover:bg-accent-gold/10"
        >
          <Plus className="w-4 h-4" />
          <span className="ml-1">Add</span>
        </Button>
      </div>

      {/* Search */}
      <div className="mb-3">
        <div className="relative">
          <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 w-4 h-4 text-text-muted" />
          <input
            type="text"

            placeholder="Search lore..."
            value={localSearchTerm}
            onChange={handleSearchChange}
            className="w-full h-9 pl-9 pr-3 text-sm bg-background-base border border-border-base rounded-sm focus:outline-none focus:ring-1 focus:ring-accent-gold focus:border-accent-gold placeholder:text-text-muted"
          />
        </div>
      </div>

      {/* Filters */}
      <div className="mb-3 flex items-center gap-2">
        <button
          onClick={toggleShowVisibleOnly}
          className={`
            px-2 py-1 text-xs rounded-sm transition-colors
            ${showVisibleOnly
              ? "bg-accent-gold/20 text-accent-gold border border-accent-gold/30"
              : "bg-background-elevated text-text-muted border border-border-base hover:border-border-muted"
            }
          `}
        >
          Visible Only
        </button>
        <div className="ml-auto">
          <Badge className="text-xs bg-accent-gold/10 text-accent-gold border-accent-gold/30">
            {loreCount}
            {totalCount > loreCount && ` / ${totalCount}`}
          </Badge>
        </div>
      </div>

      {/* Category Filters */}
      <div className="mb-3 flex flex-wrap gap-1">
        {Object.entries(categoryLabels).map(([category, label]) => {
          const isEnabled = categoryFilters[category as LoreCategory];
          return (
            <button
              key={category}
              onClick={() => toggleCategoryFilter(category as LoreCategory)}
              className={`
                px-2 py-1 text-xs rounded-sm transition-colors border
                ${isEnabled
                  ? "bg-background-elevated text-text-secondary border-border-base"
                  : "bg-background-base text-text-muted border-border-base opacity-50"
                }
              `}
              title={`Filter by ${label}`}
            >
              {label}
            </button>
          );
        })}
      </div>

      {/* Lore List */}
      {filteredLoreEntries.length === 0 ? (
        <div className="flex-1 flex items-center justify-center px-4 py-8">
          <div className="text-center">
            <BookOpen className="w-12 h-12 mx-auto mb-3 text-text-muted" />
            <p className="text-sm text-text-muted mb-1">No lore entries found</p>
            <p className="text-xs text-text-muted">
              {totalCount > 0
                ? "Try adjusting your filters"
                : "Create your first lore entry"}
            </p>
          </div>
        </div>
      ) : (
        <div className="flex-1 overflow-y-auto space-y-2 pr-1">
          {filteredLoreEntries.map((lore) => (
            <LoreCard
              key={lore.id}
              lore={lore}
              isSelected={selectedLoreId === lore.id}
              onSelect={() => selectLore(lore.id)}
              categoryLabel={categoryLabels[lore.category]}
            />
          ))}
        </div>
      )}
    </div>
  );
}

/**
 * Pin Sync Queue Manager
 *
 * Manages concurrent database sync requests for pin position updates.
 * Prevents race conditions by tracking and cancelling stale requests.
 *
 * Features:
 * - Per-pin request tracking with AbortController
 * - Automatic cancellation of pending requests when new update starts
 * - Request deduplication (only one active request per pin)
 * - Error isolation (failed requests don't block new ones)
 */

interface PendingRequest {
  pinId: string;
  abortController: AbortController;
  timestamp: number;
  rollbackPosition: { latitude: number; longitude: number } | null;
}

class PinSyncQueue {
  private pendingRequests = new Map<string, PendingRequest>();

  /**
   * Cancel any pending sync request for a specific pin
   * @param pinId - The pin ID to cancel requests for
   * @returns The rollback position if there was a pending request, null otherwise
   */
  cancelPendingRequest(pinId: string): { latitude: number; longitude: number } | null {
    const pending = this.pendingRequests.get(pinId);

    if (pending) {
      // Abort the pending request
      pending.abortController.abort();
      this.pendingRequests.delete(pinId);

      // Return the rollback position
      return pending.rollbackPosition;
    }

    return null;
  }

  /**
   * Register a new sync request for a pin
   * Automatically cancels any existing pending request for the same pin
   *
   * @param pinId - The pin ID being updated
   * @param rollbackPosition - Position to rollback to if this request fails
   * @returns AbortController for the new request
   */
  registerRequest(
    pinId: string,
    rollbackPosition: { latitude: number; longitude: number }
  ): AbortController {
    // Cancel any existing pending request first
    this.cancelPendingRequest(pinId);

    // Create new abort controller for this request
    const abortController = new AbortController();

    // Register the new request
    this.pendingRequests.set(pinId, {
      pinId,
      abortController,
      timestamp: Date.now(),
      rollbackPosition,
    });

    return abortController;
  }

  /**
   * Mark a request as completed (remove from pending map)
   * @param pinId - The pin ID whose request completed
   */
  markCompleted(pinId: string): void {
    this.pendingRequests.delete(pinId);
  }

  /**
   * Check if there's a pending request for a pin
   * @param pinId - The pin ID to check
   * @returns true if there's a pending request
   */
  hasPendingRequest(pinId: string): boolean {
    return this.pendingRequests.has(pinId);
  }

  /**
   * Get all pending pin IDs (useful for debugging)
   * @returns Array of pin IDs with pending requests
   */
  getPendingPins(): string[] {
    return Array.from(this.pendingRequests.keys());
  }

  /**
   * Clear all pending requests (useful for cleanup on unmount)
   */

  clearAll(): void {
    this.pendingRequests.forEach((request) => {
      request.abortController.abort();
    });
    this.pendingRequests.clear();
  }
}

// Singleton instance
export const pinSyncQueue = new PinSyncQueue();

