import { useRef, useEffect } from 'react';

/**
 * useFocusReturn - Return focus to element after component unmounts
 *
 * Useful for dialogs, popups, and dropdowns to restore
 * keyboard focus to the triggering element when closed.
 *
 * @param enabled - Whether focus return is active
 * @param deps - Dependencies to re-capture focus
 *
 * @example
 * ```tsx
 * const [isOpen, setIsOpen] = useState(false);
 * useFocusReturn(isOpen);
 *
 * return (
 *   <>
 *     <button onClick={() => setIsOpen(true)}>Open</button>
 *     {isOpen && <Modal onClose={() => setIsOpen(false)} />}
 *   </>
 * );
 * ```
 */
export function useFocusReturn(enabled: boolean, deps: React.DependencyList = []) {
  const previousActiveElement = useRef<HTMLElement | null>(null);

  useEffect(() => {
    if (!enabled) {
      // When disabled (dialog closes), restore focus
      previousActiveElement.current?.focus();
      previousActiveElement.current = null;
      return;
    }

    // When enabled (dialog opens), save current focus
    previousActiveElement.current = document.activeElement as HTMLElement;
  }, [enabled, ...deps]);
}

/**
 * useFocusManagement - Combined focus management for dialogs
 *
 * Captures focus on mount, returns focus on unmount.
 * Use this for modals, dialogs, and popovers.
 *
 * @param isOpen - Whether the dialog is open
 *
 * @example
 * ```tsx
 * const [isOpen, setIsOpen] = useState(false);
 * useFocusManagement(isOpen);
 *
 * return (
 *   <Dialog open={isOpen} onClose={() => setIsOpen(false)}>
 *     <DialogContent>Content</DialogContent>
 *   </Dialog>
 * );
 * ```
 */
export function useFocusManagement(isOpen: boolean) {
  useEffect(() => {
    if (!isOpen) return;

    // Save current focus when dialog opens
    const previousFocus = document.activeElement as HTMLElement;

    // Return focus when dialog closes
    return () => {
      previousFocus?.focus();
    };
  }, [isOpen]);
}

import { useEffect, useRef } from 'react';

/**
 * useFocusTrap - Trap focus within a container (for modals, dialogs)
 *
 * Prevents keyboard users from tabbing outside of a modal/dialog.
 * Automatically focuses the first focusable element on mount.
 *
 * @param enabled - Whether focus trap is active
 * @param containerRef - Ref to the container element
 *
 * @example
 * ```tsx
 * const dialogRef = useRef<HTMLDivElement>(null);
 * useFocusTrap(true, dialogRef);
 *
 * return (
 *   <div ref={dialogRef} role="dialog">
 *     <button>Close</button>
 *   </div>
 * );
 * ```
 */
export function useFocusTrap(enabled: boolean, containerRef: React.RefObject<HTMLElement>) {
  const previousActiveElement = useRef<HTMLElement | null>(null);

  useEffect(() => {
    if (!enabled || !containerRef.current) return;

    // Save the currently focused element
    previousActiveElement.current = document.activeElement as HTMLElement;

    const container = containerRef.current;

    // Find all focusable elements within container
    const focusableElements = container.querySelectorAll<
      HTMLElement
    >(
      'a[href], button:not([disabled]), textarea:not([disabled]), input:not([disabled]), select:not([disabled]), [tabindex]:not([tabindex="-1"])'
    );

    const firstElement = focusableElements[0] as HTMLElement;
    const lastElement = focusableElements[focusableElements.length - 1] as HTMLElement;

    // Focus the first element
    firstElement?.focus();

    // Handle Tab and Shift+Tab
    const handleTab = (event: KeyboardEvent) => {
      if (event.key !== 'Tab') return;

      if (event.shiftKey) {
        // Shift+Tab: if on first element, cycle to last
        if (document.activeElement === firstElement) {
          event.preventDefault();
          lastElement?.focus();
        }
      } else {
        // Tab: if on last element, cycle to first
        if (document.activeElement === lastElement) {
          event.preventDefault();
          firstElement?.focus();
        }
      }
    };

    document.addEventListener('keydown', handleTab);

    // Cleanup: restore focus to previous element
    return () => {
      document.removeEventListener('keydown', handleTab);
      previousActiveElement.current?.focus();
    };
  }, [enabled, containerRef]);
}

import { useEffect } from 'react';

export interface KeyboardShortcut {
  key: string;
  ctrlKey?: boolean;
  shiftKey?: boolean;
  altKey?: boolean;
  metaKey?: boolean;
  handler: (event: KeyboardEvent) => void;
  description: string;
}

/**
 * useKeyboardNav - Register global keyboard shortcuts
 *
 * Provides keyboard navigation and shortcuts for the application.
 * Prevents default browser behavior when needed.
 *
 * @param shortcuts - Array of keyboard shortcuts
 * @param enabled - Whether shortcuts are active
 *
 * @example
 * ```tsx
 * useKeyboardNav([
 *   {
 *     key: 'k',
 *     ctrlKey: true,
 *     handler: () => console.log('Cmd+K pressed'),
 *     description: 'Open command palette'
 *   },
 *   {
 *     key: 'Escape',
 *     handler: () => setIsModalOpen(false),
 *     description: 'Close modal'
 *   }
 * ], true);
 * ```
 */
export function useKeyboardNav(
  shortcuts: KeyboardShortcut[],
  enabled: boolean = true
) {
  useEffect(() => {
    if (!enabled) return;

    const handleKeyDown = (event: KeyboardEvent) => {
      // Check if user is typing in an input
      const target = event.target as HTMLElement;
      const isInputTarget =
        target.tagName === 'INPUT' ||
        target.tagName === 'TEXTAREA' ||
        target.tagName === 'SELECT' ||
        target.isContentEditable;

      // Find matching shortcut
      const matchedShortcut = shortcuts.find((shortcut) => {
        const keyMatch = event.key.toLowerCase() === shortcut.key.toLowerCase();
        const ctrlMatch = shortcut.ctrlKey ? event.ctrlKey || event.metaKey : !event.ctrlKey && !event.metaKey;
        const shiftMatch = shortcut.shiftKey ? event.shiftKey : !event.shiftKey;
        const altMatch = shortcut.altKey ? event.altKey : !event.altKey;
        const metaMatch = shortcut.metaKey ? event.metaKey : !event.metaKey;

        return keyMatch && ctrlMatch && shiftMatch && altMatch && metaMatch;
      });

      if (matchedShortcut) {
        // Allow shortcuts in inputs (like Escape to close)
        // but prevent others from triggering while typing
        if (isInputTarget && matchedShortcut.key !== 'Escape') {
          return;
        }

        event.preventDefault();
        matchedShortcut.handler(event);
      }
    };

    document.addEventListener('keydown', handleKeyDown);

    return () => {
      document.removeEventListener('keydown', handleKeyDown);
    };
  }, [shortcuts, enabled]);
}

