import { useState, useEffect, useCallback } from "react";

interface LoadingStateOptions {
  minDuration?: number; // Minimum duration to show loading (ms) - prevents flicker
  maxDuration?: number; // Maximum duration before timing out (ms)
}

interface LoadingStateReturn {
  isLoading: boolean;
  isMinDurationMet: boolean;
  startLoading: () => void;
  stopLoading: () => void;
  setLoading: (loading: boolean) => void;
}

/**
 * Consistent loading state management
 * Prevents flickering by enforcing minimum loading duration
 *
 * @example
 * ```tsx
 * const { isLoading, startLoading, stopLoading } = useLoadingState({ minDuration: 300 });
 *
 * const fetchData = async () => {
 *   startLoading();
 *   try {
 *     const data = await api.fetch();
 *     setData(data);
 *   } finally {
 *     stopLoading();
 *   }
 * };
 * ```
 */
export function useLoadingState(
  options: LoadingStateOptions = {}
): LoadingStateReturn {
  const { minDuration = 300, maxDuration } = options;

  const [isLoading, setIsLoading] = useState(false);
  const [startTime, setStartTime] = useState<number | null>(null);
  const [isMinDurationMet, setIsMinDurationMet] = useState(true);

  // Enforce minimum duration
  useEffect(() => {
    if (isLoading && startTime) {
      // Mark that we haven't met minimum duration yet
      setIsMinDurationMet(false);

      const minTimer = setTimeout(() => {
        setIsMinDurationMet(true);
      }, minDuration);

      // Optional max duration timeout
      let maxTimer: NodeJS.Timeout | undefined;
      if (maxDuration) {
        maxTimer = setTimeout(() => {
          console.warn(`Loading state exceeded max duration of ${maxDuration}ms`);
          setIsLoading(false);
        }, maxDuration);
      }

      return () => {
        clearTimeout(minTimer);
        if (maxTimer) clearTimeout(maxTimer);
      };
    } else if (!isLoading) {
      // Reset when loading stops
      setIsMinDurationMet(true);
    }
  }, [isLoading, startTime, minDuration, maxDuration]);

  const startLoading = useCallback(() => {
    setStartTime(Date.now());
    setIsLoading(true);
  }, []);

  const stopLoading = useCallback(() => {
    setIsLoading(false);
    setStartTime(null);
  }, []);

  const setLoading = useCallback((loading: boolean) => {
    if (loading) {
      startLoading();
    } else {
      stopLoading();
    }
  }, [startLoading, stopLoading]);

  return {
    isLoading,
    isMinDurationMet,
    startLoading,
    stopLoading,
    setLoading,
  };
}

/**

 * Simplified hook for async operations with automatic loading state
 *
 * @example
 * ```tsx
 * const { data, isLoading, error, execute } = useAsyncOperation(
 *   async () => {
 *     const response = await fetch("/api/data");
 *     return response.json();
 *   }
 * );
 *
 * return (
 *   <div>
 *     {isLoading && <SkeletonSpinner />}
 *     {error && <ErrorMessage>{error}</ErrorMessage>}
 *     {data && <DataDisplay data={data} />}
 *   </div>
 * );
 * ```
 */
export function useAsyncOperation<T>(
  asyncFn: () => Promise<T>,
  options: LoadingStateOptions = {}
) {
  const { isLoading, startLoading, stopLoading } = useLoadingState(options);
  const [data, setData] = useState<T | null>(null);
  const [error, setError] = useState<Error | null>(null);

  const execute = useCallback(async () => {
    startLoading();
    try {
      const result = await asyncFn();
      setData(result);
      setError(null);
      return result;
    } catch (err) {
      const error = err instanceof Error ? err : new Error("Unknown error");
      setError(error);
      throw error;
    } finally {
      stopLoading();
    }
  }, [asyncFn, startLoading, stopLoading]);

  return {
    data,
    isLoading,
    error,
    execute,
  };
}

/**
 * Custom error types for server actions
 * Provides structured error handling with user-friendly messages
 */

/**
 * Base application error class
 * All custom errors extend from this
 */
export class AppError extends Error {
  constructor(
    message: string,
    public code: string,
    public statusCode: number = 500,
    public isUserFacing: boolean = true
  ) {
    super(message);
    this.name = this.constructor.name;
    Error.captureStackTrace(this, this.constructor);
  }
}

/**
 * Validation error (400)
 * Thrown when input validation fails
 */
export class ValidationError extends AppError {
  constructor(message: string) {
    super(message, "VALIDATION_ERROR", 400, true);
  }
}

/**
 * Authentication error (401)
 * Thrown when user is not authenticated
 */
export class AuthenticationError extends AppError {
  constructor(message: string = "You must be logged in to perform this action") {
    super(message, "AUTHENTICATION_ERROR", 401, true);
  }
}

/**
 * Authorization error (403)
 * Thrown when user lacks permission
 */
export class AuthorizationError extends AppError {
  constructor(message: string = "You don't have permission to perform this action") {
    super(message, "AUTHORIZATION_ERROR", 403, true);
  }
}

/**
 * Not found error (404)
 * Thrown when resource doesn't exist
 */
export class NotFoundError extends AppError {
  constructor(resource: string) {
    super(`${resource} not found`, "NOT_FOUND_ERROR", 404, true);
  }
}

/**
 * Database error (500)
 * Thrown when database operation fails
 */
export class DatabaseError extends AppError {
  constructor(message: string = "Database operation failed") {
    super(message, "DATABASE_ERROR", 500, false);
  }
}

/**
 * File upload error (400)
 * Thrown when file upload fails
 */
export class FileUploadError extends AppError {
  constructor(message: string) {
    super(message, "FILE_UPLOAD_ERROR", 400, true);
  }
}

/**
 * Result type for safe error handling
 * Use this instead of throwing errors directly
 */
export type Result<T, E = AppError> =
  | { success: true; data: T }
  | { success: false; error: E };

/**
 * Helper function to create success result
 */
export function ok<T>(data: T): Result<T> {
  return { success: true, data };
}

/**
 * Helper function to create error result
 */

export function err<E extends AppError>(error: E): Result<never, E> {
  return { success: false, error };
}

/**
 * Wrap an async function in a try-catch and return a Result
 * Use this for safe error handling in server actions
 */
export async function safeAsync<T>(
  fn: () => Promise<T>,
  context: string
): Promise<Result<T>> {
  try {
    const data = await fn();
    return ok(data);
  } catch (error) {
    console.error(`[${context}] Operation failed:`, error);

    // If it's already an AppError, return it
    if (error instanceof AppError) {
      return err(error);
    }

    // If it's a Zod validation error, convert to ValidationError
    if (error instanceof Error && error.name === "ZodError") {
      return err(new ValidationError("Invalid input data"));
    }

    // Otherwise, wrap in a generic DatabaseError
    return err(new DatabaseError("An unexpected error occurred"));
  }
}

/**
 * Log error with context for debugging
 */
export function logError(context: string, error: unknown, metadata?: Record<string, unknown>) {
  const errorLog = {
    context,
    timestamp: new Date().toISOString(),
    error: error instanceof Error ? {
      name: error.name,
      message: error.message,
      stack: error.stack,
    } : error,
    metadata,
  };

  console.error(`[Error] ${context}:`, JSON.stringify(errorLog, null, 2));
}

/**
 * Get user-friendly error message from AppError
 */
export function getErrorMessage(error: AppError): string {
  if (!error.isUserFacing) {
    return "An unexpected error occurred. Please try again.";
  }
  return error.message;
}

import * as LucideIcons from "lucide-react";
