import { create } from "zustand";
import { devtools } from "zustand/middleware";
import type { Pin } from "@prisma/client";
import { createPin as createPinAction, deletePin as deletePinAction, updatePin as updatePinAction } from "@/actions/pins";
import { usePinsFilterStore } from "./use-pins-filter-store";

/**
 * Data Store - Manages pin data and server synchronization
 *
 * This store handles:
 * - Pin data storage
 * - CRUD operations (local state)
 * - Server sync with optimistic updates
 * - Loading and error states
 *
 * Data is NOT persisted (comes from server)
 */

interface PinDataState {
  pins: Pin[];
  isLoading: boolean;
  error: string | null;
}

interface PinDataActions {
  setPins: (pins: Pin[]) => void;
  addPin: (pin: Pin) => void;
  updatePin: (pinId: string, updates: Partial<Pin>) => void;
  deletePin: (pinId: string) => void;
  createPin: (data: Parameters<typeof createPinAction>[0]) => Promise<void>;
  deletePinServer: (pinId: string) => Promise<void>;
  updatePinServer: (data: Parameters<typeof updatePinAction>[0]) => Promise<void>;
  setLoading: (isLoading: boolean) => void;
  setError: (error: string | null) => void;
  reset: () => void;
}

type PinDataStore = PinDataState & PinDataActions;

const initialState: PinDataState = {
  pins: [],
  isLoading: false,
  error: null,
};

export const usePinsDataStore = create<PinDataStore>()(
  devtools(
    (set, get) => ({
      ...initialState,

      setPins: (pins) => {
        // Update data store
        set({ pins });

        // Re-apply filters in filter store
        const applyFilters = usePinsFilterStore.getState().applyFilters;
        applyFilters(pins);
      },

      addPin: (pin) => {
        set((state) => {
          const newPins = [...state.pins, pin];

          // Re-apply filters
          const applyFilters = usePinsFilterStore.getState().applyFilters;
          applyFilters(newPins);

          return { pins: newPins };
        });
      },

      updatePin: (pinId, updates) => {
        set((state) => {
          const newPins = state.pins.map((pin) =>
            pin.id === pinId ? { ...pin, ...updates } : pin
          );

          // Re-apply filters
          const applyFilters = usePinsFilterStore.getState().applyFilters;
          applyFilters(newPins);

          return { pins: newPins };
        });
      },

      deletePin: (pinId) => {
        set((state) => {
          const newPins = state.pins.filter((pin) => pin.id !== pinId);

          // Re-apply filters
          const applyFilters = usePinsFilterStore.getState().applyFilters;
          applyFilters(newPins);

          return { pins: newPins };
        });
      },

      setLoading: (isLoading) => set({ isLoading }),

      setError: (error) => set({ error }),

      reset: () => set(initialState),

      // Server sync methods with optimistic updates
      createPin: async (data) => {
        try {
          // Optimistic update - add pin with temporary ID
          const tempId = `temp-${Date.now()}`;
          const optimisticPin: Pin = {
            ...data,
            id: tempId,
            createdAt: new Date(),
            updatedAt: new Date(),
            isVisible: data.isVisible ?? true,
            opacity: data.opacity ?? 1,
            size: data.size ?? 32,
            minZoom: 0,
            maxZoom: 200,
          } as Pin;

          get().addPin(optimisticPin);

          // Server call
          const result = await createPinAction(data);

          // Replace optimistic pin with real one
          set((state) => ({
            pins: state.pins.map((p) =>
              p.id === tempId ? { ...result.pin, gameWorldId: data.gameWorldId } : p
            ),
          }));

          // Re-apply filters after replacement
          const applyFilters = usePinsFilterStore.getState().applyFilters;
          applyFilters(get().pins);
        } catch (error) {
          console.error("[PinsDataStore] Failed to create pin:", error);
          get().setError(error instanceof Error ? error.message : "Failed to create pin");
          throw error;
        }
      },

      deletePinServer: async (pinId) => {
        try {
          // Optimistic update - remove from store
          const pinToDelete = get().pins.find((p) => p.id === pinId);
          if (!pinToDelete) {
            throw new Error("Pin not found");
          }

          get().deletePin(pinId);

          // Server call
          await deletePinAction(pinId);
        } catch (error) {
          console.error("[PinsDataStore] Failed to delete pin:", error);
          get().setError(error instanceof Error ? error.message : "Failed to delete pin");
          throw error;
        }
      },

      updatePinServer: async (data) => {
        try {
          // Optimistic update - update in store
          get().updatePin(data.id, data as Partial<Pin>);

          // Server call
          await updatePinAction(data);
        } catch (error) {
          console.error("[PinsDataStore] Failed to update pin:", error);
          get().setError(error instanceof Error ? error.message : "Failed to update pin");
          throw error;
        }
      },
    }),
    {
      name: "pins-data-store",
    }
  )
);

// Selector hooks for optimized re-renders
export const usePins = () => usePinsDataStore((state) => state.pins);
export const usePinById = (pinId: string) =>
  usePinsDataStore((state) => state.pins.find((pin) => pin.id === pinId));
export const usePinsLoading = () => usePinsDataStore((state) => state.isLoading);
export const usePinsError = () => usePinsDataStore((state) => state.error);

// Action hooks
export const useSetPins = () => usePinsDataStore((state) => state.setPins);
export const useAddPin = () => usePinsDataStore((state) => state.addPin);
export const useUpdatePin = () => usePinsDataStore((state) => state.updatePin);
export const useDeletePin = () => usePinsDataStore((state) => state.deletePin);

// Server sync hooks
export const useCreatePin = () => usePinsDataStore((state) => state.createPin);
export const useDeletePinServer = () => usePinsDataStore((state) => state.deletePinServer);
export const useUpdatePinServer = () => usePinsDataStore((state) => state.updatePinServer);

import { create } from "zustand";
import { devtools, persist } from "zustand/middleware";
import type { Pin } from "@prisma/client";
import { PinTypeEnum } from "@/types/pin.type";

/**
 * Filter Store - Manages pin filtering state and logic
 *
 * This store handles:
 * - Search term filtering
 * - Pin type visibility toggles
 * - Layer filtering
 * - Visibility filtering
 * - Filtered pins computation
 *
 * Filter state is persisted to localStorage
 */

export interface PinFilters {
  searchTerm: string;
  pinTypeFilters: Record<PinTypeEnum, boolean>;
  layerIds: string[];
  showVisibleOnly: boolean;
}

interface PinFilterActions {
  setSearchTerm: (term: string) => void;
  setPinTypeFilter: (pinType: PinTypeEnum, value: boolean) => void;
  togglePinTypeFilter: (pinType: PinTypeEnum) => void;
  showAllPinTypes: () => void;
  hideAllPinTypes: () => void;
  setLayerIds: (layerIds: string[]) => void;
  toggleLayerId: (layerId: string) => void;
  toggleShowVisibleOnly: () => void;
  resetFilters: () => void;
  applyFilters: (pins: Pin[]) => Pin[];
  getVisiblePinTypes: () => PinTypeEnum[];
  reset: () => void;
}

type PinFilterStore = PinFilters & {
  filteredPins: Pin[];
} & PinFilterActions;

// Helper function to create default pin type filters
const createDefaultPinTypeFilters = (): Record<PinTypeEnum, boolean> => ({
  [PinTypeEnum.CITY]: true,
  [PinTypeEnum.VILLAGE]: true,
  [PinTypeEnum.POI]: true,
  [PinTypeEnum.CHARACTER]: true,
  [PinTypeEnum.DUNGEON]: true,
  [PinTypeEnum.SHOP]: true,
  [PinTypeEnum.QUEST]: true,
  [PinTypeEnum.TREASURE]: true,
  [PinTypeEnum.CUSTOM]: true,
});

const initialState: PinFilters = {
  searchTerm: "",
  pinTypeFilters: createDefaultPinTypeFilters(),
  layerIds: [],
  showVisibleOnly: false,
};

// Helper function to apply filters
const filterPins = (
  pins: Pin[],
  searchTerm: string,
  pinTypeFilters: Record<PinTypeEnum, boolean>,
  layerIds: string[],
  showVisibleOnly: boolean
): Pin[] => {
  return pins.filter((pin) => {
    // Search term filter
    if (searchTerm && !pin.title.toLowerCase().includes(searchTerm.toLowerCase())) {
      return false;
    }

    // Pin type filter - check if type is explicitly set to false
    if (pinTypeFilters[pin.pinType as PinTypeEnum] === false) {
      return false;
    }

    // Layer filter
    if (layerIds.length > 0 && pin.layerId && !layerIds.includes(pin.layerId)) {
      return false;
    }

    // Visibility filter
    if (showVisibleOnly && !pin.isVisible) {
      return false;
    }

    return true;
  });
};

export const usePinsFilterStore = create<PinFilterStore>()(
  devtools(
    persist(

      (set, get) => ({
        ...initialState,
        filteredPins: [],

        setSearchTerm: (term) => {
          const pins = get().filteredPins.length > 0 ? get().filteredPins : [];
          const filtered = filterPins(
            pins,
            term,
            get().pinTypeFilters,
            get().layerIds,
            get().showVisibleOnly
          );
          set({ searchTerm: term, filteredPins: filtered });
        },

        setPinTypeFilter: (pinType, value) => {
          const newFilters = {
            ...get().pinTypeFilters,
            [pinType]: value,
          };
          const pins = get().filteredPins.length > 0 ? get().filteredPins : [];
          const filtered = filterPins(
            pins,
            get().searchTerm,
            newFilters,
            get().layerIds,
            get().showVisibleOnly
          );
          set({ pinTypeFilters: newFilters, filteredPins: filtered });
        },

        togglePinTypeFilter: (pinType) => {
          const newFilters = {
            ...get().pinTypeFilters,
            [pinType]: !get().pinTypeFilters[pinType],
          };
          const pins = get().filteredPins.length > 0 ? get().filteredPins : [];
          const filtered = filterPins(
            pins,
            get().searchTerm,
            newFilters,
            get().layerIds,
            get().showVisibleOnly
          );
          set({ pinTypeFilters: newFilters, filteredPins: filtered });
        },

        showAllPinTypes: () => {
          const newFilters = createDefaultPinTypeFilters();
          const pins = get().filteredPins.length > 0 ? get().filteredPins : [];
          const filtered = filterPins(
            pins,
            get().searchTerm,
            newFilters,
            get().layerIds,
            get().showVisibleOnly
          );
          set({ pinTypeFilters: newFilters, filteredPins: filtered });
        },

        hideAllPinTypes: () => {
          const newFilters = Object.fromEntries(
            Object.entries(createDefaultPinTypeFilters()).map(([key]) => [key, false])
          ) as Record<PinTypeEnum, boolean>;
          const pins = get().filteredPins.length > 0 ? get().filteredPins : [];
          const filtered = filterPins(
            pins,
            get().searchTerm,
            newFilters,
            get().layerIds,
            get().showVisibleOnly
          );
          set({ pinTypeFilters: newFilters, filteredPins: filtered });
        },

        setLayerIds: (layerIds) => {
          const pins = get().filteredPins.length > 0 ? get().filteredPins : [];
          const filtered = filterPins(
            pins,
            get().searchTerm,
            get().pinTypeFilters,
            layerIds,
            get().showVisibleOnly
          );
          set({ layerIds, filteredPins: filtered });
        },

        toggleLayerId: (layerId) => {
          const newLayerIds = get().layerIds.includes(layerId)
            ? get().layerIds.filter((id) => id !== layerId)
            : [...get().layerIds, layerId];
          const pins = get().filteredPins.length > 0 ? get().filteredPins : [];
          const filtered = filterPins(
            pins,
            get().searchTerm,
            get().pinTypeFilters,
            newLayerIds,
            get().showVisibleOnly
          );

          set({ layerIds: newLayerIds, filteredPins: filtered });
        },

        toggleShowVisibleOnly: () => {
          const newShowVisibleOnly = !get().showVisibleOnly;
          const pins = get().filteredPins.length > 0 ? get().filteredPins : [];
          const filtered = filterPins(
            pins,
            get().searchTerm,
            get().pinTypeFilters,
            get().layerIds,
            newShowVisibleOnly
          );
          set({ showVisibleOnly: newShowVisibleOnly, filteredPins: filtered });
        },

        resetFilters: () => {
          const newFilters = createDefaultPinTypeFilters();
          set({
            searchTerm: "",
            pinTypeFilters: newFilters,
            layerIds: [],
            showVisibleOnly: false,
            filteredPins: [],
          });
        },

        applyFilters: (pins) => {
          const filtered = filterPins(
            pins,
            get().searchTerm,
            get().pinTypeFilters,
            get().layerIds,
            get().showVisibleOnly
          );
          set({ filteredPins: filtered });
          return filtered;
        },

        getVisiblePinTypes: () => {
          return Object.entries(get().pinTypeFilters)
            .filter(([, visible]) => visible)
            .map(([type]) => type as PinTypeEnum);
        },

        reset: () => set({ ...initialState, filteredPins: [] }),
      }),
      {
        name: "pins-filter-storage",
        partialize: (state) => ({
          searchTerm: state.searchTerm,
          pinTypeFilters: state.pinTypeFilters,
          layerIds: state.layerIds,
          showVisibleOnly: state.showVisibleOnly,
        }),
      }
    ),
    {
      name: "pins-filter-store",
    }
  )
);

