        stopCreating: () => set({ isCreating: false }),

        startEditing: () => set({ isEditing: true }),

        stopEditing: () => set({ isEditing: false }),

        setHoverPin: (pinId) => set({ hoverPinId: pinId }),

        reset: () => set(initialState),
