      name: "pins-ui-store",
    }
  )
);

// Selector hooks for optimized re-renders
export const useSelectedPinId = () => usePinsUIStore((state) => state.selectedPinId);
export const useIsCreatingPin = () => usePinsUIStore((state) => state.isCreating);
export const useIsEditingPin = () => usePinsUIStore((state) => state.isEditing);
export const useHoverPinId = () => usePinsUIStore((state) => state.hoverPinId);

// Action hooks
export const useSelectPin = () => usePinsUIStore((state) => state.selectPin);
export const useClearSelection = () => usePinsUIStore((state) => state.clearSelection);
export const useStartCreating = () => usePinsUIStore((state) => state.startCreating);
export const useStopCreating = () => usePinsUIStore((state) => state.stopCreating);
export const useStartEditing = () => usePinsUIStore((state) => state.startEditing);
export const useStopEditing = () => usePinsUIStore((state) => state.stopEditing);
export const useSetHoverPin = () => usePinsUIStore((state) => state.setHoverPin);

import { create } from "zustand";
import { devtools } from "zustand/middleware";
import type { GalleryItemWithRelations, MediaType } from "@/types/gallery.type";
import {
  uploadGalleryImage,
  deleteGalleryItem as deleteGalleryItemAction,
  updateGalleryItem as updateGalleryItemAction,
  reorderGalleryItems,
} from "@/actions/gallery";

// UI State for gallery interactions
export interface GalleryUIState {
  selectedImageId: string | null;
  isUploading: boolean;
  isEditing: boolean;
  lightboxOpen: boolean;
  lightboxIndex: number;
}

// Filter state for gallery items
export interface GalleryFilters {
  searchTerm: string;
  type: MediaType | "ALL";
  linkedTo: "ALL" | "PINS" | "LORE" | "UNLINKED";
}

// Gallery data stored in client state (synced with server)
interface GalleryDataState {
  galleryItems: GalleryItemWithRelations[];
  filteredGalleryItems: GalleryItemWithRelations[];
  isLoading: boolean;
  error: string | null;
  uploadProgress: Map<string, number>; // fileId -> progress percentage
}

interface GalleryStore extends GalleryUIState, GalleryFilters, GalleryDataState {
  // Selection actions
  selectImage: (imageId: string | null) => void;
  clearSelection: () => void;

  // Upload/editing actions
  startUploading: () => void;
  stopUploading: () => void;
  startEditing: () => void;
  stopEditing: () => void;

  // Lightbox actions
  openLightbox: (index: number) => void;
  closeLightbox: () => void;
  nextImage: () => void;
  previousImage: () => void;

  // Gallery CRUD operations (local state)
  setGalleryItems: (items: GalleryItemWithRelations[]) => void;
  addGalleryItem: (item: GalleryItemWithRelations) => void;
  updateGalleryItem: (itemId: string, updates: Partial<GalleryItemWithRelations>) => void;
  deleteGalleryItem: (itemId: string) => void;

  // Gallery CRUD operations (server sync with optimistic updates)
  uploadImage: (
    file: File,
    metadata: {
      title: string;
      description?: string;
      gameWorldId: string;
      pinId?: string;
      loreEntryId?: string;
    }
  ) => Promise<void>;
  deleteGalleryItemServer: (itemId: string) => Promise<void>;
  updateGalleryItemServer: (
    data: Parameters<typeof updateGalleryItemAction>[0]
  ) => Promise<void>;

  // Upload progress
  setUploadProgress: (fileId: string, progress: number) => void;
  removeUploadProgress: (fileId: string) => void;

  // Filter actions
  setSearchTerm: (term: string) => void;
  setTypeFilter: (type: MediaType | "ALL") => void;
  setLinkedToFilter: (filter: "ALL" | "PINS" | "LORE" | "UNLINKED") => void;
  resetFilters: () => void;
  applyFilters: () => void;

  // Loading and error state
  setLoading: (isLoading: boolean) => void;
  setError: (error: string | null) => void;

  // Reset all
  reset: () => void;
}

const initialState: GalleryUIState & GalleryFilters & GalleryDataState = {
  // UI State
  selectedImageId: null,
  isUploading: false,
  isEditing: false,
  lightboxOpen: false,
  lightboxIndex: 0,

  // Filters
  searchTerm: "",
  type: "ALL",
  linkedTo: "ALL",

  // Data
  galleryItems: [],
  filteredGalleryItems: [],
  isLoading: false,
  error: null,
  uploadProgress: new Map(),
};

export const useGalleryStore = create<GalleryStore>()(
  devtools(
    (set, get) => ({
      ...initialState,

      // Selection actions
      selectImage: (imageId) =>
        set({ selectedImageId: imageId }, false, "selectImage"),

      clearSelection: () =>
        set({ selectedImageId: null }, false, "clearSelection"),

      // Upload/editing actions
      startUploading: () =>
        set({ isUploading: true }, false, "startUploading"),

      stopUploading: () =>
        set({ isUploading: false }, false, "stopUploading"),

      startEditing: () =>
        set({ isEditing: true }, false, "startEditing"),

      stopEditing: () =>
        set({ isEditing: false }, false, "stopEditing"),

      // Lightbox actions
      openLightbox: (index) =>
        set(
          {
            lightboxOpen: true,
            lightboxIndex: index,
          },
          false,
          "openLightbox"
        ),

      closeLightbox: () =>
        set(
          {
            lightboxOpen: false,
            lightboxIndex: 0,
          },
          false,
          "closeLightbox"
        ),

      nextImage: () =>
        set((state) => {
          const maxIndex = state.filteredGalleryItems.length - 1;
          const newIndex = Math.min(state.lightboxIndex + 1, maxIndex);
          return { lightboxIndex: newIndex };
        }, false, "nextImage"),

      previousImage: () =>
        set((state) => {
          const newIndex = Math.max(state.lightboxIndex - 1, 0);
          return { lightboxIndex: newIndex };
        }, false, "previousImage"),

      // Gallery CRUD operations (local state)
      setGalleryItems: (items) =>
        set(
          {
            galleryItems: items,
            filteredGalleryItems: items,
          },
          false,
          "setGalleryItems"
        ),

      addGalleryItem: (item) =>
        set(
          (state) => ({
            galleryItems: [item, ...state.galleryItems],
          }),
          false,
          "addGalleryItem"
        ),

      updateGalleryItem: (itemId, updates) =>
        set(
          (state) => ({
            galleryItems: state.galleryItems.map((item) =>
              item.id === itemId ? { ...item, ...updates } : item
            ),
          }),

          false,
          "updateGalleryItem"
        ),

      deleteGalleryItem: (itemId) =>
        set(
          (state) => ({
            galleryItems: state.galleryItems.filter((item) => item.id !== itemId),
            selectedImageId:
              state.selectedImageId === itemId ? null : state.selectedImageId,
          }),
          false,
          "deleteGalleryItem"
        ),

      // Gallery CRUD operations (server sync with optimistic updates)
      uploadImage: async (file, metadata) => {
        const state = get();
        const fileId = `temp-${Date.now()}-${Math.random()}`;

        // Set uploading state
        set({ isUploading: true }, false, "uploadImage_start");

        try {
          // Create FormData
          const formData = new FormData();
          formData.append("file", file);
          formData.append("title", metadata.title);
          if (metadata.description) {
            formData.append("description", metadata.description);
          }
          formData.append("gameWorldId", metadata.gameWorldId);
          if (metadata.pinId) {
            formData.append("pinId", metadata.pinId);
          }
          if (metadata.loreEntryId) {
            formData.append("loreEntryId", metadata.loreEntryId);
          }

          // Upload to server
          const result = await uploadGalleryImage(formData);

          // Add to store
          set(
            (state) => ({
              galleryItems: [result.galleryItem, ...state.galleryItems],
              isUploading: false,
            }),
            false,
            "uploadImage_success"
          );
        } catch (error) {
          set(
            {
              isUploading: false,
              error:
                error instanceof Error
                  ? error.message
                  : "Failed to upload image",
            },
            false,
            "uploadImage_error"
          );
          throw error;
        }
      },

      deleteGalleryItemServer: async (itemId) => {
        const state = get();
        const originalItem = state.galleryItems.find((item) => item.id === itemId);

        // Optimistic delete
        set(
          (state) => ({
            galleryItems: state.galleryItems.filter((item) => item.id !== itemId),
            selectedImageId:
              state.selectedImageId === itemId ? null : state.selectedImageId,
          }),
          false,
          "deleteGalleryItem_optimistic"
        );

        try {
          await deleteGalleryItemAction(itemId);
        } catch (error) {
          // Rollback on error
          if (originalItem) {
            set(
              (state) => ({
                galleryItems: [...state.galleryItems, originalItem],
                selectedImageId: itemId,
                error:
                  error instanceof Error
                    ? error.message
                    : "Failed to delete image",
              }),
              false,
              "deleteGalleryItem_error"
            );
          }

          throw error;
        }
      },

      updateGalleryItemServer: async (data) => {
        const state = get();
        const originalItem = state.galleryItems.find(
          (item) => item.id === data.id
        );

        // Optimistic update
        const updates: Partial<GalleryItemWithRelations> = {};
        if (data.title !== undefined) updates.title = data.title;
        if (data.description !== undefined) updates.description = data.description;
        if (data.imageUrl !== undefined) updates.imageUrl = data.imageUrl;
        if (data.type !== undefined) updates.type = data.type;
        if (data.order !== undefined) updates.order = data.order;
        if (data.pinId !== undefined) updates.pinId = data.pinId;
        if (data.loreEntryId !== undefined) updates.loreEntryId = data.loreEntryId;

        set(
          (state) => ({
            galleryItems: state.galleryItems.map((item) =>
              item.id === data.id
                ? { ...item, ...updates, updatedAt: new Date() }
                : item
            ),
          }),
          false,
          "updateGalleryItem_optimistic"
        );

        try {
          const result = await updateGalleryItemAction(data);

          // Update with server response
          set(
            (state) => ({
              galleryItems: state.galleryItems.map((item) =>
                item.id === data.id ? result : item
              ),
            }),
            false,
            "updateGalleryItem_success"
          );
        } catch (error) {
          // Rollback on error
          if (originalItem) {
            set(
              (state) => ({
                galleryItems: state.galleryItems.map((item) =>
                  item.id === data.id ? originalItem : item
                ),
                error:
                  error instanceof Error
                    ? error.message
                    : "Failed to update image",
              }),
              false,
              "updateGalleryItem_error"
            );
          }
          throw error;
        }
      },

      // Upload progress
      setUploadProgress: (fileId, progress) =>
        set(
          (state) => {
            const newProgress = new Map(state.uploadProgress);
            newProgress.set(fileId, progress);
            return { uploadProgress: newProgress };
          },
          false,
          "setUploadProgress"
        ),

      removeUploadProgress: (fileId) =>
        set(
          (state) => {
            const newProgress = new Map(state.uploadProgress);
            newProgress.delete(fileId);
            return { uploadProgress: newProgress };
          },
          false,
          "removeUploadProgress"
        ),

      // Filter actions
      setSearchTerm: (term) =>
        set({ searchTerm: term }, false, "setSearchTerm"),

      setTypeFilter: (type) =>
        set({ type }, false, "setTypeFilter"),

      setLinkedToFilter: (filter) =>
        set({ linkedTo: filter }, false, "setLinkedToFilter"),

      resetFilters: () =>

        set(
          {
            searchTerm: "",
            type: "ALL",
            linkedTo: "ALL",
          },
          false,
          "resetFilters"
        ),

      applyFilters: () => {
        const state = get();
        const { galleryItems, searchTerm, type, linkedTo } = state;

        const filtered = galleryItems.filter((item) => {
          // Search term filter
          if (searchTerm) {
            const searchLower = searchTerm.toLowerCase();
            const matchesSearch =
              item.title.toLowerCase().includes(searchLower) ||
              (item.description?.toLowerCase().includes(searchLower) ?? false);
            if (!matchesSearch) return false;
          }

          // Type filter
          if (type !== "ALL" && item.type !== type) {
            return false;
          }

          // Linked-to filter
          if (linkedTo === "PINS" && !item.pinId) {
            return false;
          }
          if (linkedTo === "LORE" && !item.loreEntryId) {
            return false;
          }
          if (linkedTo === "UNLINKED" && (item.pinId || item.loreEntryId)) {
            return false;
          }

          return true;
        });

        set({ filteredGalleryItems: filtered }, false, "applyFilters");
      },

      // Loading and error state
      setLoading: (isLoading) =>
        set({ isLoading }, false, "setLoading"),

      setError: (error) =>
        set({ error }, false, "setError"),

      // Reset all
      reset: () => set(initialState, false, "reset"),
    }),
    { name: "GalleryStore" }
  )
);

import { create } from "zustand";
import { devtools } from "zustand/middleware";
import type { LoreEntry, LoreCategory } from "@prisma/client";
import {
  createLoreEntry as createLoreAction,
  deleteLoreEntry as deleteLoreAction,
  updateLoreEntry as updateLoreAction,
} from "@/actions/lore";

// UI State for lore interactions
export interface LoreUIState {
  selectedLoreId: string | null;
  isCreating: boolean;
  isEditing: boolean;
  expandedLoreIds: Set<string>;
}

// Filter state for lore entries
export interface LoreFilters {
  searchTerm: string;
  categoryFilters: Record<LoreCategory, boolean>;
  showVisibleOnly: boolean;
}

// Lore data stored in client state (synced with server)
interface LoreDataState {
  loreEntries: LoreEntry[];
  filteredLoreEntries: LoreEntry[];
  isLoading: boolean;
  error: string | null;
}

interface LoreStore extends LoreUIState, LoreFilters, LoreDataState {
  // Selection state
  selectLore: (loreId: string | null) => void;
  clearSelection: () => void;
  toggleExpanded: (loreId: string) => void;

  // Creation/editing state
  startCreating: () => void;
  stopCreating: () => void;
  startEditing: () => void;
  stopEditing: () => void;

  // Lore CRUD operations (local state)
  setLoreEntries: (loreEntries: LoreEntry[]) => void;
  addLoreEntry: (loreEntry: LoreEntry) => void;
  updateLoreEntry: (loreId: string, updates: Partial<LoreEntry>) => void;
  deleteLoreEntry: (loreId: string) => void;

  // Lore CRUD operations (server sync with optimistic updates)
  createLoreEntry: (
    data: Parameters<typeof createLoreAction>[0]
  ) => Promise<void>;
  deleteLoreEntryServer: (loreId: string) => Promise<void>;
  updateLoreEntryServer: (
    data: Parameters<typeof updateLoreAction>[0]
  ) => Promise<void>;

  // Filter actions
  setSearchTerm: (term: string) => void;
  setCategoryFilter: (category: LoreCategory, value: boolean) => void;
  toggleCategoryFilter: (category: LoreCategory) => void;
  showAllCategories: () => void;
  hideAllCategories: () => void;
  toggleShowVisibleOnly: () => void;
  resetFilters: () => void;
  applyFilters: () => void;
  getVisibleCategories: () => LoreCategory[];

  // Loading and error state
  setLoading: (isLoading: boolean) => void;
  setError: (error: string | null) => void;

  // Reset all
  reset: () => void;
}

// Helper function to create default category filters
const createDefaultCategoryFilters = (): Record<LoreCategory, boolean> => ({
  GENERAL: true,
  HISTORY: true,
  GEOGRAPHY: true,
  CHARACTERS: true,
  FACTIONS: true,
  MAGIC: true,
  ITEMS: true,
  QUESTS: true,
  CUSTOM: true,
});

const initialState: LoreUIState & LoreFilters & LoreDataState = {
  // UI State
  selectedLoreId: null,
  isCreating: false,
  isEditing: false,
  expandedLoreIds: new Set(),

  // Filters
  searchTerm: "",

  categoryFilters: createDefaultCategoryFilters(),
  showVisibleOnly: false,

  // Data
  loreEntries: [],
  filteredLoreEntries: [],
  isLoading: false,
  error: null,
};

export const useLoreStore = create<LoreStore>()(
  devtools(
    (set, get) => ({
      ...initialState,

      // Selection actions
      selectLore: (loreId) =>
        set({ selectedLoreId: loreId }, false, "selectLore"),

      clearSelection: () =>
        set({ selectedLoreId: null }, false, "clearSelection"),

      toggleExpanded: (loreId) =>
        set((state) => {
          const newExpanded = new Set(state.expandedLoreIds);
          if (newExpanded.has(loreId)) {
            newExpanded.delete(loreId);
          } else {
            newExpanded.add(loreId);
          }
          return { expandedLoreIds: newExpanded };
        }, false, "toggleExpanded"),

      // Creation/editing actions
      startCreating: () =>
        set({
          isCreating: true,
          isEditing: false,
          selectedLoreId: null,
        }, false, "startCreating"),

      stopCreating: () =>
        set({ isCreating: false }, false, "stopCreating"),

      startEditing: () =>
        set({ isEditing: true }, false, "startEditing"),

      stopEditing: () =>
        set({ isEditing: false }, false, "stopEditing"),

      // Lore CRUD operations (local state)
      setLoreEntries: (loreEntries) =>
        set(
          { loreEntries },
          false,
          "setLoreEntries"
        ),

      addLoreEntry: (loreEntry) =>
        set(
          (state) => ({
            loreEntries: [loreEntry, ...state.loreEntries],
          }),
          false,
          "addLoreEntry"
        ),

      updateLoreEntry: (loreId, updates) =>
        set(
          (state) => ({
            loreEntries: state.loreEntries.map((lore) =>
              lore.id === loreId ? { ...lore, ...updates } : lore
            ),
          }),
          false,
          "updateLoreEntry"
        ),

      deleteLoreEntry: (loreId) =>
        set(
          (state) => ({
            loreEntries: state.loreEntries.filter((lore) => lore.id !== loreId),
            selectedLoreId:
              state.selectedLoreId === loreId ? null : state.selectedLoreId,
          }),
          false,
          "deleteLoreEntry"
        ),

      // Lore CRUD operations (server sync with optimistic updates)
      createLoreEntry: async (data) => {
        const state = get();

        // Optimistic update
        const tempId = `temp-${Date.now()}`;
        const optimisticLore: LoreEntry = {
          id: tempId,
          title: data.title,
          content: data.content,
          slug: data.title.toLowerCase().replace(/\s+/g, "-"),

          category: data.category || "GENERAL",
          isVisible: data.isVisible ?? false,
          isPublic: data.isPublic ?? true,
          userId: "", // Will be filled by server
          gameWorldId: data.gameWorldId,
          createdAt: new Date(),
          updatedAt: new Date(),
        };

        set(
          (state) => ({
            loreEntries: [optimisticLore, ...state.loreEntries],
          }),
          false,
          "createLoreEntry_optimistic"
        );

        try {
          const result = await createLoreAction(data);

          // Replace optimistic entry with real one
          set(
            (state) => ({
              loreEntries: state.loreEntries.map((lore) =>
                lore.id === tempId ? result.loreEntry : lore
              ),
            }),
            false,
            "createLoreEntry_success"
          );
        } catch (error) {
          // Rollback on error
          set(
            (state) => ({
              loreEntries: state.loreEntries.filter(
                (lore) => lore.id !== tempId
              ),
              error:
                error instanceof Error
                  ? error.message
                  : "Failed to create lore entry",
            }),
            false,
            "createLoreEntry_error"
          );
          throw error;
        }
      },

      deleteLoreEntryServer: async (loreId) => {
        const state = get();
        const originalLore = state.loreEntries.find((lore) => lore.id === loreId);

        // Optimistic delete
        set(
          (state) => ({
            loreEntries: state.loreEntries.filter((lore) => lore.id !== loreId),
            selectedLoreId:
              state.selectedLoreId === loreId ? null : state.selectedLoreId,
          }),
          false,
          "deleteLoreEntry_optimistic"
        );

        try {
          await deleteLoreAction(loreId);
        } catch (error) {
          // Rollback on error
          if (originalLore) {
            set(
              (state) => ({
                loreEntries: [...state.loreEntries, originalLore],
                selectedLoreId: loreId,
                error:
                  error instanceof Error
                    ? error.message
                    : "Failed to delete lore entry",
              }),
              false,
              "deleteLoreEntry_error"
            );
          }
          throw error;
        }
      },

      updateLoreEntryServer: async (data) => {
        const state = get();
        const originalLore = state.loreEntries.find(
          (lore) => lore.id === data.id
        );

        // Optimistic update
        const updates: Partial<LoreEntry> = {};
        if (data.title !== undefined) updates.title = data.title;
        if (data.content !== undefined) updates.content = data.content;
        if (data.category !== undefined) updates.category = data.category;
        if (data.isVisible !== undefined) updates.isVisible = data.isVisible;
        if (data.isPublic !== undefined) updates.isPublic = data.isPublic;

        set(
          (state) => ({
            loreEntries: state.loreEntries.map((lore) =>
              lore.id === data.id ? { ...lore, ...updates, updatedAt: new Date() } : lore
            ),
          }),
          false,
          "updateLoreEntry_optimistic"
        );

        try {
          const result = await updateLoreAction(data);

          // Update with server response
          set(
            (state) => ({
              loreEntries: state.loreEntries.map((lore) =>
                lore.id === data.id ? result : lore
              ),
            }),
            false,
            "updateLoreEntry_success"
          );
        } catch (error) {
          // Rollback on error
          if (originalLore) {
            set(
              (state) => ({
                loreEntries: state.loreEntries.map((lore) =>
                  lore.id === data.id ? originalLore : lore
                ),
                error:
                  error instanceof Error
                    ? error.message
                    : "Failed to update lore entry",
              }),
              false,
              "updateLoreEntry_error"
            );
          }
          throw error;
        }
      },

      // Filter actions
      setSearchTerm: (term) =>
        set({ searchTerm: term }, false, "setSearchTerm"),

      setCategoryFilter: (category, value) =>
        set(
          (state) => ({
            categoryFilters: {
              ...state.categoryFilters,
              [category]: value,
            },
          }),
          false,
          "setCategoryFilter"
        ),

      toggleCategoryFilter: (category) =>
        set(
          (state) => ({
            categoryFilters: {
              ...state.categoryFilters,
              [category]: !state.categoryFilters[category],
            },
          }),
          false,
          "toggleCategoryFilter"
        ),

      showAllCategories: () =>
        set(
          { categoryFilters: createDefaultCategoryFilters() },
          false,
          "showAllCategories"
        ),

      hideAllCategories: () =>
        set(
          (state) => {
            const filters = { ...state.categoryFilters };
            Object.keys(filters).forEach((key) => {
              filters[key as LoreCategory] = false;
            });
            return { categoryFilters: filters };
          },
          false,
          "hideAllCategories"
        ),

      toggleShowVisibleOnly: () =>
        set(
          (state) => ({
            showVisibleOnly: !state.showVisibleOnly,
          }),
          false,
          "toggleShowVisibleOnly"
        ),

      resetFilters: () =>
        set(
          {
            searchTerm: "",
            categoryFilters: createDefaultCategoryFilters(),
            showVisibleOnly: false,
          },
          false,
          "resetFilters"
        ),

      applyFilters: () => {
        const state = get();
        const { loreEntries, searchTerm, categoryFilters, showVisibleOnly } =
          state;

        const filtered = loreEntries.filter((lore) => {
          // Search term filter
          if (searchTerm) {
            const searchLower = searchTerm.toLowerCase();
            const matchesSearch =
              lore.title.toLowerCase().includes(searchLower) ||
              lore.content.toLowerCase().includes(searchLower);
            if (!matchesSearch) return false;
          }

          // Category filter
          if (!categoryFilters[lore.category]) {
            return false;
          }

          // Visibility filter
          if (showVisibleOnly && !lore.isVisible) {
            return false;
          }

          return true;
        });

        set({ filteredLoreEntries: filtered }, false, "applyFilters");
      },

      getVisibleCategories: () => {
        const state = get();
        return Object.entries(state.categoryFilters)
          .filter(([_, enabled]) => enabled)
          .map(([category]) => category as LoreCategory);
      },

      // Loading and error state
      setLoading: (isLoading) =>
        set({ isLoading }, false, "setLoading"),

      setError: (error) =>
        set({ error }, false, "setError"),

      // Reset all
      reset: () => set(initialState, false, "reset"),
    }),
    { name: "LoreStore" }
  )
);

